insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cell', 'Stephen King', '150112224X', 'https://assets.hardcover.app/edition/12846341/b3519625-358c-42b4-9614-2410d01a418e.jpg', 'Cell is a 2006 apocalyptic horror novel by American author Stephen King. The story follows a New England artist struggling to reunite with his young son after a mysterious signal broadcast over the global cell phone network turns the majority of his fellow humans into mindless vicious animals.', 473, null, 2006, 80, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Needful Things', 'Stephen King', '6708395312', 'https://assets.hardcover.app/edition/31532254/ef799c15-7e10-4ace-82b9-cc5117605bf5.jpg', 'A newcomer opens a shop in Castle Rock. Bringing bargains as well as nightmares and disasters to the town.', 933, null, 1991, 149, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Talisman', 'Stephen King, Peter Straub', '9513148149', 'https://assets.hardcover.app/external_data/4088543/f9c85f7ea765db250806c91f891f88f0edb239ee.jpeg', 'On a brisk autumn day, a thirteen-year-old boy stands on the shores of the gray Atlantic, near a silent amusement park and a fading ocean resort called the Alhambra. The past has driven Jack Sawyer here: His father is gone, his mother is dying, and the world no longer makes sense. But for Jack everything is about to change. For he has been chosen to make a journey back across America–-and into another realm.

One of the most influential and heralded works of fantasy ever written, The Talisman is an extraordinary novel of loyalty, awakening, terror, and mystery. Jack Sawyer, on a desperate quest to save his mother’s life, must search for a prize across an epic landscape of innocents and monsters, of incredible dangers and even more incredible truths. The prize is essential, but the journey means even more. Let the quest begin. . . .', 766, null, 1984, 725, (select id from series where hardcover_id = 5620), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Death Masks', 'Jim Butcher, James Marsters', '184149402X', 'https://assets.hardcover.app/external_data/59738371/8e1ad815a9ca924e206d06c6b808c7616cc4fe3c.jpeg', 'Meet Harry Dresden, Chicago''s first (and only) Wizard P.I. Turns out the ''everyday'' world is full of strange and magical things - and most of them don''t play well with humans. That''s where Harry comes in. Harry Dresden should be happy that business is good - makes a change. But now he''s getting more than he bargained for: a duel with the Red Court of Vampires'' champion, who must kill Harry to end the war between vampires and wizards; professional hit men using Harry for target practice; the missing Shroud of Turin (less missing than expected) and a headless corpse the Chicago police need identifying . . . Not to mention the return of Harry''s ex-girlfriend Susan, still struggling with her semi-vampiric nature. And who seems to have a new man. Some days, it just doesn''t pay to get out of bed. No matter how much you''re charging. Magic - it can get a guy killed.', 448, null, 2003, 1244, (select id from series where hardcover_id = 990), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Matched', 'Ally Condie', '0525423648', 'https://assets.hardcover.app/editions/27268369/c3fbab63-aeef-4c86-98fe-0f9e055a12ea-8886579.jpg', 'Cassia has always trusted the Society to make the right choices for her: what to read, what to watch, what to believe. So when Xander''s face appears on-screen at her Matching ceremony, Cassia knows with complete certainty that he is her ideal mate . . . until she sees Ky Markham''s face flash for an instant before the screen fades to black.

The Society tells her it''s a glitch, a rare malfunction, and that she should focus on the happy life she''s destined to lead with Xander. But Cassia can''t stop thinking about Ky, and as they slowly fall in love, Cassia begins to doubt the Society''s infallibility and is faced with an impossible choice: between Xander and Ky, between the only life she''s known and a path that no one else has dared to follow.', 384, null, 2010, 4513, (select id from series where hardcover_id = 2140), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Farthest Shore', 'Ursula K. Le Guin', '1449840825', 'https://assets.hardcover.app/edition/14536115/364d66abefb3fe04d4ac3a3030875d7342e4850b.jpeg', 'In this third book in the Earthsea series, darkness threatens to overtake Earthsea: The world and its wizards are losing their magic. But Ged Sparrohawk—Archmage, wizard, and dragonlord—is determined to discover the source of this devastating loss.
Aided by Enlad’s young Prince Arren, Ged embarks on a treacherous journey that will test their strength and will. Because to restore magic, the two warriors must venture to the farthest reaches of their world—and even beyond the realm of death.

With millions of copies sold worldwide, Ursula K. Le Guin’s Earthsea Cycle has earned a treasured place on the shelves of fantasy lovers everywhere, alongside the works of such beloved authors as J.R.R. Tolkien and C.S. Lewis.', 336, null, 1972, 6524, (select id from series where hardcover_id = 1170), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Doomsday Book', 'Connie Willis, Daniel Dos Santos', '8386868422', 'https://assets.hardcover.app/editions/7114478/5092485842787575.jpg', ' Kivrin knows everything about the Middle Ages - she''s read all the books. She knows it''s dangerous: cutthroats in the woods, witch hunts, cholera, and millions dying in the plague. For a young historian, it''s fascinating.

When Kivrin''s tutors in Oxford''s history lab finally agree to send her on an on-site study trip, she jumps at the chance to observe medieval life first-hand. But a crisis that strangely links the past and future leaves her stranded in the most deadly and terrifying era in human history, face to face with the heart-rending reality behind the statistics. And while she fights for her own life, Kivrin finds she has become an unlikely angel of hope in this dark time.

Five years in the writing, Doomsday Book is a storytelling triumph. Connie Willis draws upon her understanding of the universalities of human nature to explore the timeless issues of evil, suffering and the indomitable will of the human spirit.', 593, null, 1992, 10086, (select id from series where hardcover_id = 1137), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Foucault''s Pendulum', 'Umberto Eco', '9872060940', 'https://assets.hardcover.app/edition/30628450/153e253a-101a-44cf-bb36-2c7726994e65.jpeg', 'Extraordinary narrative by Italian semiotician and professor Umberto Eco, who guides us through the darkest corners of history.', 641, null, 1988, 20318, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Flatland: A Romance of Many Dimensions', 'Edwin A. Abbott', '1417665297', 'https://assets.hardcover.app/external_data/3248161/8b98529f9b8a4bde2fe925942e27cc5bf013749d.jpeg', 'Flatland: A Romance of Many Dimensions, though written in 1884, is still considered useful in thinking about multiple dimensions. It is also seen as a satirical depiction of Victorian society and its hierarchies. A square, who is a resident of the two-dimensional Flatland, dreams of the one-dimensional Lineland. He attempts to convince the monarch of Lineland of the possibility of another dimension, but the monarch cannot see outside the line. The square is then visited himself by a Sphere from three-dimensional Spaceland, who must show the square Spaceland before he can conceive it. As more dimensions enter the scene, the story''s discussion of fixed thought and the kind of inhuman action which accompanies it intensifies.', 96, null, 1884, 32073, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Carry On', 'Rainbow Rowell', '3423640324', 'https://assets.hardcover.app/edition/17576064/2c5e4948-4d0d-4c90-b88b-1066602bad48.jpg', 'Simon Snow is the worst Chosen One who''s ever been chosen.

That''s what his roommate, Baz, says. And Baz might be evil and a vampire and a complete git, but he''s probably right.

Half the time, Simon can''t even make his wand work, and the other half, he starts something on fire. His mentor''s avoiding him, his girlfriend broke up with him, and there''s a magic-eating monster running around, wearing Simon''s face. Baz would be having a field day with all this, if he were here -- it''s their last year at the Watford School of Magicks, and Simon''s infuriating nemesis didn''t even bother to show up.

Carry Onis a ghost story, a love story and a mystery. It has just as much kissing and talking as you''d expect from a Rainbow Rowell story - but far, far more monsters.', 529, null, 2015, 36816, (select id from series where hardcover_id = 5636), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Interesting Times', 'Terry Pratchett', '0413772195', 'https://assets.hardcover.app/edition/31954810/65cd018cc384796ab0866e0941c61fe5e63ebe1a.jpeg', '"May you live in interesting times" is the worst thing one can wish on a citizen of Discworld -- especially on the distinctly unmagical sorcerer Rincewind, who has had far too much perilous excitement in his life. But when a request for a "Great Wizzard" arrives in Ankh-Morpork via carrier albatross from the faraway Counterweight Continent, it''s he who''s sent as emissary. Chaos threatens to follow the impending demise of the Agatean Empire''s current ruler. And, for some incomprehensible reason, someone believes Rincewind will have a mythic role in the war and wholesale bloodletting that will surely ensue. (Carnage is pretty much a given, since Cohen the Barbarian and his extremely elderly Silver Horde are busily formulating their own plan for looting, pillaging, and, er, looking wistfully at girls.) However, Rincewind firmly believes there are too many heroes already in the world, yet only one Rincewind. And he owes it to the world to keep that one alive for as long as possible.', 112, null, 1994, 37594, (select id from series where hardcover_id = 1018), '17') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ancillary Sword', 'Ann Leckie', '8466660429', 'https://assets.hardcover.app/book_mappings/7333227/e57d8f2657c4190fe750713df3f6c43b3d5aa74a.jpeg', 'The Lord of the Radch has given Breq command of the ship Mercy of Kalr and sent her to the only place she would have agreed to go — to Athoek Station, where Lieutenant Awn’s sister works in Horticulture.

Athoek was annexed some six hundred years ago, and by now everyone is fully civilized — or should be. But everything is not as tranquil as it appears. Old divisions are still troublesome, Athoek Station’s AI is unhappy with the situation, and it looks like the alien Presger might have taken an interest in what’s going on. With no guarantees that interest is benevolent.', 359, null, 2014, 42612, (select id from series where hardcover_id = 993), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('All the Birds in the Sky', 'Charlie Jane Anders', '1664447598', 'https://assets.hardcover.app/external_data/3461591/71aa94a5e7c331d7680cf58703529cfedfa512f1.jpeg', 'An ancient society of witches and a hipster technological startup go war as the world from tearing itself. To further complicate things, each of the groups’ most promising followers (Patricia, a brilliant witch and Laurence, an engineering “wunderkind”) may just be in love with each other. 

As the battle between magic and science wages in San Francisco against the backdrop of international chaos, Laurence and Patricia are forced to choose sides. But their choices will determine the fate of the planet and all mankind.

In a fashion unique to Charlie Jane Anders, All the Birds in the Sky offers a humorous and, at times, heart-breaking exploration of growing up extraordinary in world filled with cruelty, scientific ingenuity, and magic.', 313, null, 2016, 45615, (select id from series where hardcover_id = 5510), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Gone World', 'Tom Sweterlitsch', '1472214978', 'https://assets.hardcover.app/editions/30404856/2814039534798139.jpg', 'Inception meets True Detective in this science fiction thriller of spellbinding tension and staggering scope that follows a special agent into a savage murder case with grave implications for the fate of mankind....

“I promise you have never read a story like this.”—Blake Crouch, New York Times bestselling author of Dark Matter

Shannon Moss is part of a clandestine division within the Naval Criminal Investigative Service. In western Pennsylvania, 1997, she is assigned to solve the murder of a Navy SEAL''s family—and to locate his vanished teenage daughter. Though she can''t share the information with conventional law enforcement, Moss discovers that the missing SEAL was an astronaut aboard the spaceship U.S.S. Libra—a ship assumed lost to the currents of Deep Time. Moss knows first-hand the mental trauma of time-travel and believes the SEAL''s experience with the future has triggered this violence.

Determined to find the missing girl and driven by a troubling connection from her own past, Moss travels ahead in time to explore possible versions of the future, seeking evidence to crack the present-day case. To her horror, the future reveals that it''s not only the fate of a family that hinges on her work, for what she witnesses rising over time''s horizon and hurtling toward the present is the Terminus: the terrifying and cataclysmic end of humanity itself.

Luminous and unsettling, The Gone World bristles with world-shattering ideas yet remains at its heart an intensely human story.', 402, null, 2018, 47278, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Arctic Incident', 'Eoin Colfer', '0606274944', 'https://assets.hardcover.app/edition/13947664/c0caf79c-f323-4dd0-87c7-abf23d1aa97c.jpg', 'Artemis Fowl: The Arctic Incident is the second book in the epicly good Artemis Fowl series by Eoin Colfer. Criminal Mastermind Artemis Fowl never stops scheming . . . Artemis''s father has been missing for almost two years. His location? The Arctic Circle, where the Russian Mafiya are holding him prisoner. Now Artemis must execute a daring rescue operation to get his father back. But that''s not his only problem. Since abducting one of an underground race of armed and dangerous fairies, Artemis has become their prime suspect for any human wrongdoing. Elfin Captain Holly Short has accused him of supplying illegal human power cells (aka AAA batteries) to the goblin gangs. There''s going to be a terrifying uprising - but at least it will get Artemis away from his computer and he''ll meet some new people. It''s just a pity most of them want to kill him. ''Hugely satisfying - not to be missed'' - Irish Independent''Engagingly vivid, exciting and witty'' - The Telegraph''Fast, funny and very exciting'' - Daily Mail ***Artemis Fowl was winner of the WHSmith Children''s Book of the Year Award and Children''s Book of the Year at the Children''s Book Awards. Shortlisted for the Whitbread Children''s Book of the Year Award.*******Enter Artemis''s wicked world at www.artemisfowl.co.uk', 288, null, 2001, 47952, (select id from series where hardcover_id = 1374), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Gods Themselves', 'Isaac Asimov', '5041727163', 'https://assets.hardcover.app/edition/15365994/0c909cfbcb012c22c99cdc5224f4e4a0d9cf13cf.jpeg', 'Only a few know the terrifying truth -- an outcast Earth scientist, a rebellious alien inhabitant of a dying planet, a lunar-born human intuitionist who senses the imminent annihilation of the Sun. They know the truth -- but who will listen? They have foreseen the cost of abundant energy -- but who will believe? These few beings, human and alien, hold the key to the Earth''s survival.', 305, null, 1972, 53731, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dead Until Dark', 'Charlaine Harris', '078651650X', 'https://assets.hardcover.app/external_data/2371769/753f587778bd0b933d1091efcb554ae379529cb6.jpeg', 'For years, Charlaine Harris has delighted fans with her mystery series featuring small-town waitress-turned-paranormal sleuth Sookie Stackhouse. Now, we are pleased to offer her first novel in the series in a special hardcover edition.  And with HBO launching an all-new show, True Blood, based on the Southern Vampire novels, the demand for Charlaine Harris and Sookie Stackhouse will be bigger than ever.', 326, null, 2001, 59640, (select id from series where hardcover_id = 5512), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Thief Of Time', 'Terry Pratchett', '0753112078', 'https://assets.hardcover.app/edition/32195807/9444d0a0188e06ebcc96020f21566a611704c24f.jpeg', 'In Discworld, time is a resource managed by the highly capable Monks of History. Everybody wants more time, which is why on Discworld only the experts can manage it. While everyone always talks about slowing down, one young horologist is about to do the unthinkable. He''s going to stop. Well, stop time that is, by building the world''s first truly accurate clock. Which means esteemed History Monk Lu-Tze and his apprentice Lobsang Ludd have to put on some speed to stop the timepiece before it starts. For if the perfect clock starts ticking, time, as we know it, will end. And then the trouble will really begin.', 432, null, 2001, 65185, (select id from series where hardcover_id = 1018), '26') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The One', 'Kiera Cass', '9000338654', 'https://assets.hardcover.app/edition/30399854/7e811f59beeca6a130a31507236f69a110202f43.jpeg', 'The time has come for one winner to be crowned.

When she was chosen to compete in the Selection, America never dreamed she would find herself anywhere close to the crown—or to Prince Maxon''s heart. But as the end of the competition approaches, and the threats outside the palace walls grow more vicious, America realizes just how much she stands to lose—and how hard she''ll have to fight for the future she wants.', 323, null, 2014, 67638, (select id from series where hardcover_id = 1545), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mote in God''s Eye', 'Larry Niven, Jerry Pournelle', '8377314924', 'https://assets.hardcover.app/edition/26011758/67dc1bbe474a9206b98b826846191b94962bd86b.jpeg', 'Aliens - Moties - were first contacted in AD3017 in the region of space known as the Coalsack. The eponymous mote in his eye, which has winked out, much to the distress of pious Himmists, just might have been Motie laser light. It might even indicate the position of their home planet.', 598, null, 1974, 72914, (select id from series where hardcover_id = 1152), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mother Night', 'Kurt Vonnegut', '9736818284', 'https://assets.hardcover.app/edition/26790089/e72b1c16a366e3e7b2cf1ab3527d9fd8d4cdf247.jpeg', 'Mother Night is a daring challenge to our moral sense. American Howard W. Campbell, Jr., a spy during World War II, is now on trial in Israel as a Nazi war criminal. But is he really guilty? In this brilliant book rife with true gallows humor, Vonnegut turns black and white into a chilling shade of gray with a verdict that will haunt us all.', 268, null, 1962, 80091, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mist', 'Stephen King', '0671874756', 'https://assets.hardcover.app/external_data/544812/a65bc6c31757afc3f5822751b8404a2da1c37b1d.jpeg', 'The No. 1 bestselling author Stephen King''s terrifying novella about a town engulfed in a dense, mysterious mist - originally published in the acclaimed short story collection Skeleton Crew and made into a feature film by Frank Darabont - is now available as a stand-alone publication. A man staggered into the market . . . ''Something in the fog!'' he screamed Following a freak summer storm, David Drayton, his son Billy, and their neighbour Brent Norton join dozens of others and head to the local grocery store to replenish supplies. Once there, they become trapped by a strange mist that has enveloped the town. Violent forces concealed in the mist are starting to emerge. And there is another shocking threat from within - one group of survivors, led by a religious zealot, is calling for a sacrifice. Now David and his son must try to escape. But what''s outside may be even more dangerous. This exhilarating novella explores the horror in both the enemy you know - and the one you can only imagine.', 169, null, 1980, 80172, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fantastic Beasts and Where to Find Them', 'Newt Scamander, J.K. Rowling', '9722327550', 'https://assets.hardcover.app/edition/934203/9326659-L.jpg', 'An approved textbook at Hogwarts School of Witchcraft and Wizardry since its first publication, Fantastic Beasts and Where to Find Them is an indispensable guide to the magical beasts of the wizarding world. It showcases a menagerie of magical creatures, explained enchantingly by noted magizoologist, Newt Scamander, who you may remember from the film series of the same name. The shelves of the Hogwarts Library are also home to many more fascinating books. If you have enjoyed Fantastic Beasts and Where to Find Them you might want to check out some of its other treasures: Quidditch Through the Ages and The Tales of Beedle the Bard. Comic Relief, operating name Charity Projects, is a registered charity in the UK with charity nos. 326568 (England/Wales) and SC039730 (Scotland). Lumos Foundation is a registered charity in the UK with no. 1112575 (England/Wales). 15% of the proceeds* received by Pottermore Limited from this ebook will be made available to the charities for their work across the UK and globally including helping children and young people have a better life. These proceeds will be shared 20% for Comic Relief and 80% for Lumos Foundation. *Proceeds means the cash-price or cash-equivalent price less sales taxes.', 65, null, 1983, 83094, (select id from series where hardcover_id = 5441), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wind through the Keyhole', 'Stephen King', '9513173062', 'https://assets.hardcover.app/edition/32537551/43accd9afed9a87275138d026b5517be1f6507c0.jpeg', 'Sent by his father to investigate evidence of a murderous shape shifter, a "skin man," Roland Deschain takes charge of Bill Streeter, a brave but terrified boy who is the sole surviving witness to the beast''s most recent slaughter. Roland, himself only a teenager, calms the boy by reciting a story from the Magic Tales of the Eld that his mother used to read to him at bedtime, "The Wind through the Keyhole." (The novel can be placed between Dark Tower IV and Dark Tower V.)', 280, null, 2008, 89140, (select id from series where hardcover_id = 3413), '4.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ancillary Mercy', 'Ann Leckie', '0316402753', 'https://assets.hardcover.app/edition/30399400/44820cd574467f7aafc3daae6ab4e6b36ec7922b.jpeg', '"For a moment, things seemed to be under control for Breq, the soldier who used to be a warship. Then a search of Athoek Station''s slums turns up someone who shouldn''t exist, and a messenger from the mysterious Presger empire arrives, as does Breq''s enemy, the divided and quite possibly insane Anaander Mianaai--ruler of an empire at war with itself"--Page 4 of cover.

In the stunning conclusion to the Imperial Radch trilogy, a search of Athoek Station''s slums turns up someone who shouldn''t exist. A messenger from the mysterious Presger empire arrives, as does Breq''s enemy, the divided and quite possibly insane Anaander Mianaai, ruler of an empire at war with itself. Breq refuses to flee with her ship and crew, because that would leave the people of Athoek in terrible danger. The odds aren''t good, but that''s never stopped her before.', 333, null, 2015, 89213, (select id from series where hardcover_id = 993), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Proven Guilty', 'Jim Butcher', '0451461037', 'https://assets.hardcover.app/external_data/27836574/08d3e21c04762a746c28b54fc466b03e0ca97b0d.jpeg', 'The only wizard in the Chicago phone book, Harry is given the task of investigating rumors of black magic in the Windy City, while, at the same time, searching for some malevolent entities that feed on fear who have been set loose on Chicago.', 406, null, 2006, 98856, (select id from series where hardcover_id = 990), '8') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nevernight', 'Jay Kristoff', '8401019346', 'https://assets.hardcover.app/book_mappings/7333242/ff756f76fe1feb1c4e2a3f6eea822f520945b916.jpeg', 'In a land where three suns almost never set, a fledgling killer joins a school of assassins, seeking vengeance against the powers who destroyed her family.

Daughter of an executed traitor, Mia Corvere is barely able to escape her father’s failed rebellion with her life. Alone and friendless, she hides in a city built from the bones of a dead god, hunted by the Senate and her father’s former comrades. But her gift for speaking with the shadows leads her to the door of a retired killer, and a future she never imagined.

Now, a sixteen year old Mia is apprenticed to the deadliest flock of assassins in the entire Republic — the Red Church. Treachery and trials await her with the Church’s halls, and to fail is to die. But if she survives to initiation, Mia will be inducted among the chosen of the Lady of Blessed Murder, and one step closer to the only thing she desires.

Revenge.', 448, null, 2016, 101048, (select id from series where hardcover_id = 5678), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('White Noise', 'Don DeLillo, Richard Powers', '0147798388', 'https://assets.hardcover.app/external_data/3643397/19dc2294223ce8f7b54bb4cbf325a84d4e429084.jpeg', 'White Noise is the story of Jack, his wife, Babette, and their four ultramodern offspring. They live in a college town where Jack is Professor of Hitler Studies (and conceals the fact that he does not speak a word of German), and Babette teaches posture and volunteers by reading tabloids to a group of elderly shut-ins. They are happy enough, until a deadly toxic accident and Babette’s addiction to an experimental drug make Jake question everything. 

White Noise is considered a postmodern classic and its unfolding of themes of consumerism, family and divorce, and technology as a deadly threat have attracted the attention of literary scholars since its publication.', 337, null, 1984, 103997, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hidden Oracle', 'Rick Riordan', '2017038237', 'https://assets.hardcover.app/edition/30400842/b8e9e9e7-ec7f-4b78-bf1d-d78fce43079d.jpg', 'After angering his father Zeus, the god Apollo is cast down from Olympus. Weak and disoriented, he lands in New York City as a regular teenage boy. Now, without his godly powers, the four-thousand-year-old deity must learn to survive in the modern world until he can somehow find a way to regain Zeus''s favor. But Apollo has many enemies—gods, monsters, and mortals who would love to see the former Olympian permanently destroyed. Apollo needs help, and he can think of only one place to go . . . an enclave of modern demigods known as Camp Half-Blood.', 376, null, 2016, 108094, (select id from series where hardcover_id = 1588), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('James and the Giant Peach', 'Roald Dahl, Lane Smith', '1417786086', 'https://assets.hardcover.app/editions/18388444/7743031682438903-232188.jpg', 'When James Henry Trotter accidentally drops some magic crystals by the old peach tree, strange things start to happen. The peach at the top of the tree begins to grow, and before long it''s as big as a house. Then James discovers a secret entranceway into the fruit, and when he crawls inside, he meets a bunch of marvelous oversized friends — Old Green-Grasshopper, Centipede, Ladybug, Miss Spider, and more.

After years of feeling like an outsider in the house of his despicable Aunt Sponge and Aunt Spiker, James has finally found a place where he belongs. With a snip of the stem, the peach starts rolling away, and the exciting adventure begins!', 146, null, 1961, 113247, (select id from series where hardcover_id = 210403), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Eyre Affair', 'Jasper Fforde, Susan Duerdan', '0143145703', 'https://assets.hardcover.app/edition/8425462/dc16a3a65ab795d2fa4692fd4a70734c90c40c16.jpeg', 'The Eyre Affair

Great Britain circa 1985: time travel is routine, cloning is a reality (dodos are the resurrected pet of choice), and literature is taken very, very seriously. Baconians are trying to convince the world that Francis Bacon really wrote Shakespeare, there are riots between the Surrealists and Impressionists, and thousands of men are named John Milton, an homage to the real Milton and a very confusing situation for the police. Amidst all this, Acheron Hades, Third Most Wanted Man In the World, steals the original manuscript of Martin Chuzzlewit and kills a minor character, who then disappears from every volume of the novel ever printed! But that''s just a prelude . . . Hades'' real target is the beloved Jane Eyre, and it''s not long before he plucks her from the pages of Bronte''s novel. Enter Thursday Next. She''s the Special Operative''s renowned literary detective, and she drives a Porsche. With the help of her uncle Mycroft''s Prose Portal, Thursday enters the novel to rescue Jane Eyre from this heinous act of literary homicide. It''s tricky business, all these interlopers running about Thornfield, and deceptions run rampant as their paths cross with Jane, Rochester, and Miss Fairfax. Can Thursday save Jane Eyre and Bronte''s masterpiece? And what of the Crimean War? Will it ever end? And what about those annoying black holes that pop up now and again, sucking things into time-space voids . . . Suspenseful and outlandish, absorbing and fun, The Eyre Affair is a caper unlike any other and an introduction to the imagination of a most distinctive writer and his singular fictional universe. Next up in the Thursday Next series: Lost in a Good Book. Read more about it at thursdaynext.com.', null, null, 2001, 117696, (select id from series where hardcover_id = 1158), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('White Night', 'Jim Butcher, Chris McGrath', '0786298200', 'https://assets.hardcover.app/external_data/3685911/0910f7baaee7f2f7245e3bd25ba3a221c2a1fd95.jpeg', 'A sensational addition to the Dresden Files adventures-from a USA Today bestselling author.Professional wizard Harry Dresden is investigating a series of deaths in Chicago. Someone is killing practitioners of magic, those incapable of becoming full-fledged wizards. Shockingly, all the evidence points to Harry''s half-brother, Thomas, as the murderer. Determined to clear his sibling''s name, Harry uncovers a conspiracy within the White Council of Wizards that threatens not only him, but his nearest and dearest, too...', 467, null, 2007, 117922, (select id from series where hardcover_id = 990), '9') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nine Princes in Amber', 'Roger Zelazny, Tim          White', '1515446662', 'https://assets.hardcover.app/edition/14806587/aadddc7fa84f89a7d8edb29bb83c70a9f9213766.jpeg', 'Exiled to the Shadows for centuries, a man more than mortal awakens in an Earth hospital with no memory of his past—and is surrounded by enemies who hunger for his destruction. For Corwin is of the blood—the rightful successor to the throne of the real world. But to rule, he must conquer impossible realities and demonic assassins... and survive the ruthless machinations of the most insidious malevolence imaginable: his own family.', 175, null, 1970, 128171, (select id from series where hardcover_id = 1168), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Life After Life', 'Kate Atkinson', '9896414076', 'https://assets.hardcover.app/book_mappings/7333177/311fba28fe808cc3f12104078783c45c9d630e74.jpeg', 'What if you could live again and again, until you got it right? On a cold and snowy night in 1910, Ursula Todd is born to an English banker and his wife. She dies before she can draw her first breath. On that same cold and snowy night, Ursula Todd is born, lets out a lusty wail, and embarks upon a life that will be, to say the least, unusual. For as she grows, she also dies, repeatedly, in a variety of ways, while the young century marches on towards its second cataclysmic world war. Does Ursula''s apparently infinite number of lives give her the power to save the world from its inevitable destiny? And if she can -- will she?', 544, null, 2013, 132800, (select id from series where hardcover_id = 1127), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Swan Song', 'Robert McCammon', '1439166536', 'https://assets.hardcover.app/external_data/61205852/a5d3ce355a962c18a690fad86159ea90d0f6a80c.jpeg', 'Nominated as one of America’s best-loved novels by PBS’s The Great American Read. New York Times bestselling author Robert McCammon’s prescient and astonishing vision of a post-apocalyptic United States comes to life in this classic epic of terror and renewal. Facing down an unprecedented malevolent enemy, the US government responds with a nuclear attack. Soon, America as it was is gone forever, and now every citizen—from the president of the United States to the homeless on the streets of New York City—will fight to stay alive. In a wasteland born of rage and fear, populated by monstrous creatures and marauding armies, Earth’s last survivors are drawn into the final battle between good and evil, which will decide the fate of humanity: Sister, who discovers a strange and transformative glass artifact in the destroyed Manhattan streets…Joshua Hutchins, the pro wrestler who takes refuge from the nuclear fallout at a Nebraska gas station...and Swan, a young girl possessing special powers, who travels alongside Josh to a Midwest town where healing and recovery can begin with her extraordinary gifts. But the ancient force behind the world’s devastation is scouring the walking wounded for recruits to build its relentless army, beginning with Swan herself…', 880, null, 1987, 133584, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Memories of Ice', 'Steven Erikson', '8417347062', 'https://assets.hardcover.app/edition/22499953/096f5612234242607b46858cb13cfcd7d0a1b69b.jpeg', 'The ravaged continent of Genabackis has given birth to a terrifying new empire: the Pannion Domin. Like a tide of corrupted blood, it seethes across the land, devouring all. In its path stands an uneasy alliance: Onearm''s army and Whiskeyjack''s Bridgeburners alongside their enemies of old--the forces of the Warlord Caladan Brood, Anomander Rake and his Tiste Andii mages, and the Rhivi people of the plains.

But ancient undead clans are also gathering; the T''lan Imass have risen. For it would seem something altogether darker and more malign threatens this world. Rumors abound that the Crippled God is now unchained and intent on a terrible revenge.', 1180, null, 2001, 133778, (select id from series where hardcover_id = 1167), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Children of the Mind', 'Orson Scott Card', '0356501876', 'https://assets.hardcover.app/edition/25426445/812d7a2b03d9f69c64d0c56fe14ab77dff5404d4.jpeg', 'The planet Lusitania is home to three sentient species: the Pequeninos; a large colony of humans; and the Hive Queen, brought there by Ender. But once against the human race has grown fearful; the Starways Congress has gathered a fleet to destroy Lusitania.

Jane, the evolved computer intelligence, can save the three sentient races of Lusitania. She has learned how to move ships outside the universe, and then instantly back to a different world, abolishing the light-speed limit. But it takes all the processing power available to her, and the Starways Congress is shutting down the Net, world by world.

Soon Jane will not be able to move the ships. Ender''s children must save her if they are to save themselves.', 370, null, 1996, 136580, (select id from series where hardcover_id = 1059), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Neverending Story', 'Michael Ende, Ralph Manheim, Roswitha Quadflieg', '8419688460', 'https://assets.hardcover.app/book_mappings/7333370/509b2fa094cc96d1ae301b6c498615839fa99015.jpeg', 'This epic work of the imagination has captured the hearts of millions of readers worldwide since it was first published more than a decade ago. Its special story within a story is an irresistible invitation for readers to become part of the book itself. And now this modern classic and bibliophile''s dream is available in hardcover again.

The story begins with a lonely boy named Bastian and the strange book that draws him into the beautiful but doomed world of Fantastica. Only a human can save this enchanted place by giving its ruler, the Childlike Empress, a new name. But the journey to her tower leads through lands of dragons, giants, monsters, and magic and once Bastian begins his quest, he may never return. As he is drawn deeper into Fantastica, he must find the courage to face unspeakable foes and the mysteries of his own heart. 

Readers, too, can travel to the wondrous, unforgettable world of Fantastica if they will just turn the page...
--front flap', 401, null, 1979, 144950, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Curse of Chalion', 'Lois McMaster Bujold', '0061793043', 'https://assets.hardcover.app/edition/32884429/c908f048-2984-49d7-8b2c-c591a0410f84.jpeg', 'A man broken in body and spirit, Cazaril returns to the noble household he once served as page and is named secretary-tutor to the beautiful, strong-willed sister of the impetuous boy who is next in line to rule. It is an assignment Cazaril dreads, for it must ultimately lead him to the place he most fears: the royal court of Cardegoss, where the powerful enemies who once placed him in chains now occupy lofty positions.

But it is more than the traitorous intrigues of villains that threaten Cazaril and the Royesse Iselle here, for a sinister curse hangs like a sword over the entire blighted House of Chalion. And only by employing the darkest, most forbidden of magics can Cazaril hope to protect his royal charge -- an act that will mark him as a tool of the miraculous . . . and trap him in a lethal maze of demonic paradox.', 512, null, 2001, 146704, (select id from series where hardcover_id = 5527), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The 5th Wave', 'Rick Yancey', '014134587X', 'https://assets.hardcover.app/book_mappings/7333181/9a36285fd2698c572f3e4b02ddfab1e57ae6ad6d.jpeg', 'After the 1st wave, only darkness remains. After the 2nd, only the lucky escape. And after the 3rd, only the unlucky survive. After the 4th wave, only one rule applies: trust no one.

Now, it''s the dawn of the 5th wave, and on a lonely stretch of highway, Cassie runs from Them. The beings who only look human, who roam the countryside killing anyone they see. Who have scattered Earth''s last survivors. To stay alone is to stay alive, Cassie believes, until she meets Evan Walker. Beguiling and mysterious, Evan Walker may be Cassie''s only hope for rescuing her brother—or even saving herself. But Cassie must choose: between trust and despair, between defiance and surrender, between life and death. To give up or to get up.', 457, null, 2013, 147494, (select id from series where hardcover_id = 5702), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Parable of the Talents', 'Octavia E. Butler', '1538759403', 'https://assets.hardcover.app/edition/30404385/3cc957a2d515382a0ac631c17a2b6dc075ccd35c.jpeg', 'Environmental devastation and economic chaos have turned America into a land of depravity. Taking advantage of the situation, a zealous bigot wins his way into the White House. Lauren Olamina leads a new faith group directly opposed to the new government. This is the story of the group''s struggle to preserve its vision.

As the government turns a blind eye to the violent bigots who consider a black female leader a threat, Lauren Olamina must either sacrifice her child and her followers or forsake her religion. The plot contains profanity, sexual situations and violence,', 448, null, 1993, 150915, (select id from series where hardcover_id = 5461), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fifth Elephant', 'Terry Pratchett', '0783893078', 'https://assets.hardcover.app/edition/31883904/15b95175-cd96-4592-9cc9-8a2855a04e59.jpg', '''WELL, HE THOUGHT, SO THIS IS DIPLOMACY. IT''S LYING, ONLY FOR A BETTER CLASS OF PEOPLE.'' Commander Sam Vimes of the Ankh-Morpork City Watch is a long way from home. Sent as reluctant ambassador to Uberwald, a mysterious region inhabited by dwarfs, vampires and werewolves, Vimes must learn the art of diplomacy. Fast. But when he uncovers a mystery with ties back home, the policeman in him can''t help but investigate. What could possibly go wrong? Well, quite a lot actually. Vimes finds himself on the run through the frozen forests of Uberwald, armed with only his wits and the trousers of Uncle Vanya (don''t ask). And if he doesn''t make it, there''s going to be a terrible war. But there are monsters on his trail. They''re smart. They''re fast. They''re werewolves. And they''re catching up . . . ''Precisely balanced . . . a cracking comic thriller'' The Times The Fifth Elephant is the fifth book in the City Watch series, but you can read the Discworld novels in any order.', 464, null, 1999, 152389, (select id from series where hardcover_id = 1018), '24') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Long Earth', 'Terry Pratchett, Stephen Baxter', '0552164089', 'https://assets.hardcover.app/edition/31005016/7792bc9d3c2953a28bb064ffd3eaa436408974b3.jpeg', '1916: The Western Front. Private Percy Blakeney wakes up. He is lying on fresh spring grass. He can hear birdsong and the wind in the leaves. Where have the mud, blood, and blasted landscape of no-man''s-land gone? For that matter, where has Percy gone?

2015: Madison, Wisconsin. Police officer Monica Jansson is exploring the burned-out home of a reclusive--some say mad, others allege dangerous--scientist who seems to have vanished. Sifting through the wreckage, Jansson finds a curious gadget: a box containing some rudimentary wiring, a three-way switch, and . . . a potato. It is the prototype of an invention that will change the way humankind views the world forever.', 353, null, 2012, 153034, (select id from series where hardcover_id = 2753), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('My Best Friend''s Exorcism', 'Grady Hendrix', '1504714512', 'https://assets.hardcover.app/edition/4209784/597bbfc45ea3433474b7568b9b986636326bfde9.jpeg', '1988. Charleston, South Carolina. High school sophomores Abby and Gretchen have been best friends since fourth grade. But after an evening of skinny-dipping goes disastrously wrong, Gretchen begins to act--different. She''s moody. She''s irritable. And bizarre incidents keep happening whenever she''s nearby. Abby''s investigation leads her to some startling discoveries--and by the time their story reaches its terrifying conclusion, the fate of Abby and Gretchen will be determined by a single question: Is their friendship powerful enough to beat the devil?', 330, null, 2016, 159170, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Thief', 'Megan Whalen Turner', '0613060326', 'https://assets.hardcover.app/edition/5855845/4bb5477f-7b4b-4fb5-b302-82a3aab810c8.jpg', 'The king''s scholar, the magus, believes he knows the site of an ancient treasure. To attain it for his king, he needs a skillful thief, and he selects Gen from the king''s prison. The magus is interested only in the theif''s abilities. What Gen is interested in is anyone''s guess. Their journey toward the treasure is both dangerous and difficult, lightened only imperceptibly by the tales they tell of the old gods and goddesses.

Megan Whalen Turner weaves Gen''s stories and Gen''s story together with style and verve in a novel that is filled with intrigue, adventure, and surprise.', 304, null, 1996, 162987, (select id from series where hardcover_id = 5530), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fangirl', 'Rainbow Rowell', '8702189070', 'https://assets.hardcover.app/edition/30818174/6ec3965b-3b20-406f-9ec5-33baf6405ff2.jpg', 'Okay, the whole world is a Simon Snow fan, but for Cath, being a fan is her life―and she''s really good at it. She and her twin sister, Wren, ensconced themselves in the Simon Snow series when they were just kids; it''s what got them through their mother leaving.

Reading. Rereading. Hanging out in Simon Snow forums, writing Simon Snow fan fiction, dressing up like the characters for every movie premiere.

Cath''s sister has mostly grown away from fandom, but Cath can''t let go. She doesn''t want to.
Now that they''re going to college, Wren has told Cath she doesn''t want to be roommates. Cath is on her own, completely outside of her comfort zone. She''s got a surly roommate with a charming, always-around boyfriend, a fiction-writing professor who thinks fan fiction is the end of the civilized world, a handsome classmate who only wants to talk about words . . . And she can''t stop worrying about her dad, who''s loving and fragile and has never really been alone.

For Cath, the question is: Can she do this? Can she make it without Wren holding her hand? Is she ready to start living her own life? And does she even want to move on if it means leaving Simon Snow behind?', 406, null, 2013, 174866, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cress', 'Marissa Meyer', '3551582882', 'https://assets.hardcover.app/edition/6455619/30e7419b-2c78-4dcf-a217-541df98855a8.jpg', 'In this third book in the Lunar Chronicles, Cinder and Captain Thorne are fugitives on the run, now with Scarlet and Wolf in tow. Together, they''re plotting to overthrow Queen Levana and her army.

Their best hope lies with Cress, a girl imprisoned on a satellite since childhood who''s only ever had her netscreens as company. All that screen time has made Cress an excellent hacker. Unfortunately, she''s just received orders from Levana to track down Cinder and her handsome accomplice.

When a daring rescue of Cress goes awry, the group is separated. Cress finally has her freedom, but it comes at a higher price. Meanwhile, Queen Levana will let nothing prevent her marriage to Emperor Kai. Cress, Scarlet, and Cinder may not have signed up to save the world, but they may be the only hope the world has.', 552, null, 2013, 180793, (select id from series where hardcover_id = 5558), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Sandman, Vol. 1: Preludes & Nocturnes', 'Neil Gaiman', '1417651636', 'https://assets.hardcover.app/edition/30404367/45670b01f982462ff2f712420fef4eb6cb49d1ee.jpeg', 'Preludes and Nocturnes collects the first eight issues of The Sandman comic by Neil Gaiman published by DC Vertigo. The series centers on Morpheus (Dream of the Endless). Dream is imprisoned for decades by an occultist seeking immortality. Upon escaping, he must reclaim his objects of power while still in a weakened state, confronting an addict to his dream powder, the legions of Hell, and an all-powerful madman (Doctor Destiny) in the process.', 240, null, 1988, 183146, (select id from series where hardcover_id = 149651), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Jingo', 'Terry Pratchett', '0552154172', 'https://assets.hardcover.app/edition/31582444/f1e8fde550813fffbd0b48a1264f0e89bafba4f1.jpeg', '''IT WAS SO MUCH EASIER TO BLAME IT ON THEM. IT WAS BLEAKLY DEPRESSING TO THINK THAT THEY WERE US.'' War is brewing on the Discworld. An island has appeared from the ocean depths, right in the middle of the sea which separates the proud empires of Klatch and Ankh-Morpork. Of course, no one would dream of starting a war with the neighbours without a perfectly good reason . . . such as a ''strategic'' piece of old rock, for instance. But when a Klatchian Prince is almost assassinated, peace talks break down and violent nationalism begins to spread. Ankh-Morpork prepares to fight. Only thing is, they don''t have an army. Or much in the way of weapons. Commander Sam Vimes and the ''officially disbanded'' City Watch get caught up in a deadly political game where the enemy appears to be on both sides and no one will listen to reason. And if they don''t stop this absurd war, no one will . . . ''Generous, amusing and the ideal boarding point for those who have never visited Discworld'' Sunday Telegraph Jingo is the fourth book in the City Watch series, but you can read the Discworld novels in any order.', 464, null, 1997, 192933, (select id from series where hardcover_id = 1018), '21') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Inkheart', 'Cornelia Funke', '0439531659', 'https://assets.hardcover.app/edition/30859827/4e18cc10ebc42ab96553962ed8d1c2b0662a839d.jpeg', 'Twelve-year-old Meggie learns that her father, who repairs and binds books for a living, can "read" fictional characters to life when one of those characters abducts them and tries to force him into service.

Characters from books literally leap off the page in this engrossing fantasy. Meggie has had her father to herself since her mother went away when she was young. Mo taught her to read when she was five, and the two share a mutual love of books. He can "read" characters out of books. When she was three, he read aloud from a book called Inkheart and released characters into the real world. At the same time, Meggie''s mother disappeared into the story. This "story within a story" will delight not just fantasy fans, but all readers who like an exciting plot with larger-than-life characters.', 576, null, 2003, 193169, (select id from series where hardcover_id = 90665), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Count Zero', 'William Gibson', '3608121129', 'https://assets.hardcover.app/edition/30703528/3717d341-fced-4ca9-b130-7586ce8885fa.jpg', 'William Gibson continues the visionary Sprawl Trilogy that began with Neuromancer in this frighteningly probable parable of the future. A corporate mercenary wakes in a reconstructed body, a beautiful woman by his side. Then Hosaka Corporation reactivates him, for a mission more dangerous than the one he’s recovering from: to get a defecting chief of R&D—and the biochip he’s perfected—out intact. But this proves to be of supreme interest to certain other parties—some of whom aren’t remotely human....', 256, null, 1986, 198682, (select id from series where hardcover_id = 19911), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Clockwork Prince', 'Cassandra Clare', '9896573549', 'https://assets.hardcover.app/edition/30863723/dcc91f0228693af4161e1d7fe651178729a71bb4.jpeg', 'In the magical underworld of Victorian London, Tessa Gray has at last found safety with the Shadowhunters. But that safety proves fleeting when rogue forces in the Clave plot to see her protector, Charlotte, replaced as head of the Institute. If Charlotte loses her position, Tessa will be out on the street—and easy prey for the mysterious Magister, who wants to use Tessa’s powers for his own dark ends.

With the help of the handsome, self-destructive Will and the fiercely devoted Jem, Tessa discovers that the Magister’s war on the Shadowhunters is deeply personal. He blames them for a long-ago tragedy that shattered his life. To unravel the secrets of the past, the trio journeys from mist-shrouded Yorkshire to a manor house that holds untold horrors, from the slums of London to an enchanted ballroom where Tessa discovers that the truth of her parentage is more sinister than she had imagined. When they encounter a clockwork demon bearing a warning for Will, they realize that the Magister himself knows their every move—and that one of their own has betrayed them.

Tessa finds her heart drawn more and more to Jem, but her longing for Will, despite his dark moods, continues to unsettle her. But something is changing in Will—the wall he has built around himself is crumbling. Could finding the Magister free Will from his secrets and give Tessa the answers about who she is and what she was born to do?

As their dangerous search for the Magister and the truth leads the friends into peril, Tessa learns that when love and lies are mixed, they can corrupt even the purest heart.', 528, null, 2011, 199427, (select id from series where hardcover_id = 5756), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('1984 / Animal Farm', 'George Orwell', '9798519476355', 'https://assets.hardcover.app/edition/12605380/7fb2187e562e7d7d3964975a8c44ea3c31612dcf.jpeg', 'THE 100TH ANNIVERSARY of George Orwell''s birth has brought these two groundbreaking novels together for the first time, along with a revealing new introduction by Christopher Hitchens.

ALL ANIMALS ARE EQUAL BUT SOME ANIMALS ARE MORE EQUAL THAN OTHERS
George Orwell''s classic satire of the Russian Revolution is the account of the bold struggle, initiated by the animals, that transforms Mr. Jones''s Manor Farm into Animal Farm—a wholly democratic society built on the credo that All Animals Are Created Equal. Out of their cleverness, the pigs Napoleon, Squealer, and Snowball emerge as leaders of the new community in a subtle evolution that proves disastrous. The climax is the brutal betrayal of the faithful horse Boxer, when totalitarian rule is reestablished with the bloodstained postscript to the founding slogan: But Some Animals Are More Equal Than Others.

WAR IS PEACE. FREEDOM IS SLAVERY IGNORANCE IS STRENGTH.
In 1984, London is a grim city where Big Brother is always watching you and the Thought Police can practically read your mind. Winston is a man in grave danger for the simple reason that his memory still functions. Drawn into a forbidden love affair, Winston finds the courage to join a secret revolutionary organization called The Brotherhood, dedicated to the destruction of the Party. Together with his beloved Julia. he hazards his life in a death match against the powers that be.
--front flap', 385, null, 1945, 202093, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ignite Me', 'Tahereh Mafi', '2749959349', 'https://assets.hardcover.app/books/202417/1703321328398495.jpg', 'With Omega Point destroyed, Juliette doesn''t know if the rebels, her friends, or even Adam are alive. But that won''t keep her from trying to take down The Reestablishment once and for all. Now she must rely on Warner, the handsome commander of Sector 45. The one person she never thought she could trust. The same person who saved her life. He promises to help Juliette master her powers and save their dying world . . . but that''s not all he wants with her.

The Shatter Me series is perfect for fans who crave action-packed young adult novels with tantalizing romance like Red Queen by Victoria Aveyard, The Hunger Games by Suzanne Collins, and Legend by Marie Lu. Tahereh Mafi has created a captivating and original story that combines the best of dystopian and paranormal and was praised by Publishers Weekly as "a gripping read from an author who''s not afraid to take risks."

This bestselling series from powerhouse author Tahereh Mafi showcases relentlessly thrilling action, heart-stopping romance, and a war-torn world in which rebellion is the only path to freedom.', 408, null, 2014, 202417, (select id from series where hardcover_id = 1064), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Magician King', 'Lev Grossman', '8817092207', 'https://assets.hardcover.app/edition/30401081/dfe002db332d16f0b1cff9575436b7b232a399bb.jpeg', 'Return to Fillory in the riveting sequel to the *New York Times* bestseller and literary phenomenon of 2009 *The Magicians*.

Quentin Coldwater should be blissfully happy. He escaped a miserable Brooklyn childhood for Brakebills, a secret and exclusive college for magic in upstate New York. When he graduated he discovered that Fillory, the magical utopia described in a series of children''s fantasy novels he never quite outgrew, was real.

Fillory was a far more dangerous place than Quentin could have imagine, and he faced unspeakable tragedies there. But now Quentin and his friends have become the kings and queens of Fillory and, under their reign, Fillory is a peaceful kingdom. But Quentin is restless. He hasn''t escaped the scars of his past, and the peace and luxury of his life in Fillory will prove more fragile than anyone expects.

After a royal morning hunt takes a sinister turn, Quentin''s doubts get the better of him. With Julia, a queen of Fillory and Quentin''s high school friend, in tow, he charters a magical sailing ship and heads off to the farthest reaches of Fillory. He is in search of adventure--the thrill and sense of purpose only a heroic quest can bestow. Instead his journey takes them to the last place Quentin wants to be: his parents'' house in Chesterton, Massachusetts.

Quentin is a magician and a king, but even he can''t rescue them from suburban America. only the dark, twisted sorcery Julia learned in the seedy back alleys of the Brooklyn underground magic scene can put them on the road back to Fillory. But when Julia takes center stage, so too does her story, and with it the secret of the terrible price she paid for her power. As Quentin and Julia follow a trail of clues from Brakebills to Venice to the home of the real-life children who appeared in the Fillory novels, they gradually discover a more sinister, more powerful threat than any they''ve faced. And they must fight death and despair in a world that is very far from the bright, simple fantasy novels they read as children.

In *The Magicians*, Lev Grossman shattered the limits of conventional fantasy writing by imagining magic as practiced in the real world by fallible and capricious people, without the clear absolutes of good and evil most fantasy heroes steer by. *The Magician King* sets these young magicians on an epic quest deep into the dark, glittering heart of magic to reveal the unexpected paradox behind being a hero. It also introduces a powerful new voice, that of Julia, whose angry genius is thrilling and terrifying. The juxtaposition of her rage and Quentin''s yearning creates a novel of resonant psychological complexity and reckoning. Brilliant, inventive, and gut-wrenchingly authentic, *The Magician King* once again proves that Grossman is the modern heir to C. S. Lewis and the cutting edge of literary fantasy.

This description comes from the publisher.', 400, null, 2011, 203808, (select id from series where hardcover_id = 1041), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Winter', 'Marissa Meyer', '954271601X', 'https://assets.hardcover.app/books/211308/7384926-L.jpg', 'Princess Winter is admired by the Lunar people for her grace and kindness, and despite the scars that mar her face, her beauty is said to be even more breathtaking than that of her stepmother, Queen Levana.

Winter despises her stepmother, and knows Levana won''t approve of her feelings for her childhood friend--the handsome palace guard, Jacin. But Winter isn''t as weak as Levana believes her to be and she''s been undermining her stepmother''s wishes for years. Together with the cyborg mechanic, Cinder, and her allies, Winter might even have the power to launch a revolution and win a war that''s been raging for far too long.

Can Cinder, Scarlet, Cress, and Winter defeat Levana and find their happily ever afters? Fans will not want to miss this thrilling conclusion to Marissa Meyer''s national bestselling Lunar Chronicles series.', 833, null, 2006, 211308, (select id from series where hardcover_id = 5558), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Small Favor', 'Jim Butcher', '0356500365', 'https://assets.hardcover.app/edition/30422731/507bdab33027b79e3609c563d00388d6c35b2558.jpeg', 'No one''s tried to kill Harry Dresden for almost an entire year, and his life finally seems to be calming down. For once, the future looks fairly bright. But the past casts one hell of a long shadow.

An old bargain has placed Harry in debt to Mab, monarch of the Winter Court of the Sidhe, the Queen of Air and Darkness-and she''s calling in her marker. It''s a small favor he can''t refuse...one that will trap Harry Dresden between a nightmarish foe and an equally deadly ally, and one that will strain his skills- and loyalties-to their very limits.It figures. Everything was going too well to last...', 437, null, 2008, 213831, (select id from series where hardcover_id = 990), '10') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Running Man', 'Richard Bachman, Stephen King', '1441732799', 'https://assets.hardcover.app/edition/22435580/fcd2be67-0fe4-4b35-85e4-a4c13b5903ff.jpg', 'In the year 2025, the best men don''t run for president, they run for their lives...

Ben Richards is out of work and out of luck. His eighteen-month-old daughter is sick, and neither Ben nor his wife can afford to take her to a doctor. For a man from the poor side of town with no cash and no hope, there''s only one thing to do: become a contestant on one of the Network''s Games, shows where you can win more money than you''ve ever dreamed of—or die trying. Now Ben''s going prime-time on the Network''s highest-rated viewer participation show. And he''s about to become a prey for the masses...', null, null, 1982, 228201, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('There There', 'Tommy Orange', '0525520384', 'https://assets.hardcover.app/edition/30404859/38c2c5e2c2ba5cf0f6438f738d86c76ab5113e4f.jpeg', 'A contemporary classic, this “astonishing literary debut” (Margaret Atwood, bestselling author of The Handmaid’s Tale) “places Native American voices front and center” (NPR/Fresh Air).

Among them is Jacquie Red Feather, newly sober and trying to make it back to the family she left behind. Dene Oxendene, pulling his life together after his uncle’s death and working at the powwow to honor his memory. Fourteen-year-old Orvil, coming to perform traditional dance for the very first time. They converge and collide on one fateful day at the Big Oakland Powwow and together this chorus of voices tells of the plight of the urban Native American—grappling with a complex and painful history, with an inheritance of beauty and spirituality, with communion and sacrifice and heroism

A book with “so much jangling energy and brings so much news from a distinct corner of American life that it’s a revelation” (The New York Times). It is fierce, funny, suspenseful, and impossible to put down–full of poetry and rage, exploding onto the page with urgency and force. There There is at once poignant and unflinching, utterly contemporary and truly unforgettable.
', 292, null, 2018, 231490, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Witches Abroad', 'Terry Pratchett', '0061020613', 'https://assets.hardcover.app/edition/31705921/f6ffb201398ab432e80ff719c3bec69e2e1d9f4e.jpeg', 'The twelfth Discworld novel — It seemed an easy job . . . After all, how difficult could it be to make sure that a servant girl doesn’t marry a prince? But for the witches Granny Weatherwax, Nanny Ogg and Magrat Garlick, travelling to the distant city of Genua, things are never that simple. Servant girls have to marry the prince. That’s what life is all about. You can’t fight a Happy Ending. At least — up until now.', 362, null, 1991, 232184, (select id from series where hardcover_id = 1018), '12') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Daughter of Smoke & Bone', 'Laini Taylor', '9513161420', 'https://assets.hardcover.app/external_data/59550963/cb2f7a810e292436b2c61efcbb1ee89c2ce62084.jpeg', 'Around the world, black hand prints are appearing on doorways, scorched there by winged strangers who have crept through a slit in the sky.

In a dark and dusty shop, a devil’s supply of human teeth grows dangerously low.

And in the tangled lanes of Prague, a young art student is about to be caught up in a brutal otherworldly war.

Meet Karou. She fills her sketchbooks with monsters that may or may not be real, she’s prone to disappearing on mysterious "errands", she speaks many languages - not all of them human - and her bright blue hair actually grows out of her head that color. Who is she? That is the question that haunts her, and she’s about to find out.

When beautiful, haunted Akiva fixes fiery eyes on her in an alley in Marrakesh, the result is blood and starlight, secrets unveiled, and a star-crossed love whose roots drink deep of a violent past. But will Karou live to regret learning the truth about herself?', 356, null, 2001, 232764, (select id from series where hardcover_id = 4905), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blood Song', 'Anthony Ryan', '3608939253', 'https://assets.hardcover.app/book_mappings/7333378/7bbb6ed6136eeb3e5efac8137084fd3db1624cbc.jpeg', 'Vaelin Al Sorna was only a child of ten when his father left him at the iron gate of the Sixth Order—a caste devoted to battle. Vaelin will be trained and hardened to the austere, celibate and dangerous life of a warrior of the Faith. He has no family now save the Order.

Vaelin’s father was Battle Lord to King Janus, ruler of the Unified Realm—and Vaelin’s rage at being deprived of his birthright knows no bounds. Even his cherished memories of his mother are soon challenged by what he learns within the Order.

But one truth overpowers all the rest: Vaelin Al Sorna is destined for a future he has yet to comprehend. A future that will alter not only the Realm, but the world.', 642, null, 2011, 244696, (select id from series where hardcover_id = 5749), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Eric', 'Terry Pratchett', '0552153346', 'https://assets.hardcover.app/edition/30917989/507ee2a0e727038d8889771757ff1b47db5a5f95.jpeg', 'Discworld''s only demonology hacker, Eric, is about to make life very difficult for the rest of Ankh-Morpork''s denizens. This would-be Faust is very bad...at his work, that is. All he wants is to fulfill three little wishes:to live forever, to be master of the universe, and to have a stylin'' hot babe.But Eric isn''t even good at getting his own way. Instead of a powerful demon, he conjures, well, Rincewind, a wizard whose incompetence is matched only by Eric''s. And as if that wasn''t bad enough, that lovable travel accessory the Luggage has arrived, too. Accompanied by his best friends, there''s only one thing Eric wishes now -- that he''d never been born!', 126, null, 1990, 245192, (select id from series where hardcover_id = 1018), '9') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('If It Bleeds', 'Stephen King', '9520421912', 'https://assets.hardcover.app/edition/30662116/3ed7c41843aee06a0874e4ee9cf202e1057d055e.jpeg', 'If it Bleeds is a collection of four new novellas —Mr. Harrigan’s Phone, The Life of Chuck, Rat, and the title story If It Bleeds— each pulling readers into intriguing and frightening places.

A collection of four uniquely wonderful long stories, including a stand-alone sequel to The Outsider.

News people have a saying: ''If it bleeds, it leads''. And a bomb at Albert Macready Middle School is guaranteed to lead any bulletin.

Holly Gibney of the Finders Keepers detective agency is working on the case of a missing dog - and on her own need to be more assertive - when she sees the footage on TV. But when she tunes in again, to the late-night report, she realizes there is something not quite right about the correspondent who was first on the scene. So begins ''If It Bleeds'' , a stand-alone sequel to The Outsider featuring the incomparable Holly on her first solo case.

Dancing alongside are three more long stories - ''Mr Harrigan''s Phone'', ''The Life of Chuck'' and ''Rat'' .

The novella is a form King has returned to over and over again in the course of his amazing career, and many have been made into iconic films, If It Bleeds is a uniquely satisfying collection of longer short fiction by an incomparably gifted writer.', 416, null, 2020, 246203, (select id from series where hardcover_id = 5531), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Screwtape Letters', 'C. S. Lewis', '0786172797', 'https://assets.hardcover.app/edition/30400086/0ad4a540-9e05-4ef2-8a9c-97dad0f9096f.png', 'This profound and striking narrative takes the form of a series of letters from Screwtape, a devil high in the Infernal Civil Service, to his nephew Wormwood, a junior colleague engaged in his first mission on earth, trying to secure the damnation of a young man who has just become a Christian. 

Although the young man initially looks to be a willing victim, he changes his ways and is "lost" to the young devil. 

Dedicated to Lewis''s friend and colleague J. R. R. Tolkien, The Screwtape Letters is a timeless classic on spiritual conflict and the psychology of temptation which are part of our religious experience', 272, null, 1942, 249749, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Illustrated Man', 'Ray Bradbury', '140014826X', 'https://assets.hardcover.app/edition/25064864/b26108be420d45d860e6645409ebe73569bcc618.jpeg', 'The Illustrated Man is a 1951 collection of eighteen science fiction short stories by American writer Ray Bradbury. A recurring theme throughout the eighteen stories is the conflict of the cold mechanics of technology and the psychology of people. It was nominated for the International Fantasy Award in 1952.', 244, null, 1951, 251319, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Changes', 'Jim Butcher', '5170782721', 'https://assets.hardcover.app/edition/30527416/94053fa66f9a9f2839ff363a6b6b8540a6f002bb.jpeg', 'Long ago, Susan Rodriguez was Harry Dresden''s lover-until she was attacked by his enemies, leaving her torn between her own humanity and the bloodlust of the vampiric Red Court. Susan then disappeared to South America, where she could fight both her savage gift and those who cursed her with it.

Now Arianna Ortega, Duchess of the Red Court, has discovered a secret Susan has long kept, and she plans to use it-against Harry. To prevail this time, he may have no choice but to embrace the raging fury of his own untapped dark power. Because Harry''s not fighting to save the world...He''s fighting to save his child.', 562, null, 2010, 252854, (select id from series where hardcover_id = 990), '12') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dead Beat', 'Jim Butcher', '1101128445', 'https://assets.hardcover.app/book_mappings/7333409/af231dc6bc39eb28e0ac99cc227b3bf26e1a7f22.jpeg', 'Paranormal investigations are Harry Dresden’s business and Chicago is his beat, as he tries to bring law and order to a world of wizards and monsters that exists alongside everyday life. And though most inhabitants of the Windy City don’t believe in magic, the Special Investigations Department of the Chicago PD knows better.
 
Karrin Murphy is the head of S. I. and Harry’s good friend. So when a killer vampire threatens to destroy Murphy’s reputation unless Harry does her bidding, he has no choice. The vampire wants the Word of Kemmler (whatever that is) and all the power that comes with it. Now, Harry is in a race against time—and six merciless necromancers—to find the Word before Chicago experiences a Halloween night to wake the dead...', 528, null, 2005, 255544, (select id from series where hardcover_id = 990), '7') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Foundation Trilogy', 'Isaac Asimov', '9877255111', 'https://assets.hardcover.app/editions/20768835/1093753700287044.jpeg', 'Foundation begins a new chapter in the story of man''s future. As the Old Empire crumbles into barbarism throughout the million worlds of the galaxy, Hari Seldon and his band of psychologists must create a new entity, the Foundation-dedicated to art, science, and technology-as the beginning of a new empire.

Foundation and Empire describes the mighty struggle for power amid the chaos of the stars in which man stands at the threshold of a new enlightened life which could easily be destroyed by the old forces of barbarism.

Second Foundation follows the Seldon Plan after the First Empire''s defeat and describes its greatest threat-a dangerous mutant strain gone wild, which produces a mind capable of bending men''s wills, directing their thoughts, reshaping their desires, and destroying the universe.', 752, null, 1950, 275730, (select id from series where hardcover_id = 5450), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Use of Weapons', 'Iain M. Banks', '0316030570', 'https://assets.hardcover.app/external_data/59676942/5066b069758a1068aac6b8fba60276d82b0909de.jpeg', 'The third Culture novel from the awesome imagination of Iain M. Banks, a modern master of science fiction. The man known as Cheradenine Zakalwe was one of Special Circumstances'' foremost agents, changing the destiny of planets to suit the Culture through intrigue, dirty tricks or military action. The woman known as Diziet Sma had plucked him from obscurity and pushed him towards his present eminence, but despite all their dealings she did not know him as well as she thought. The drone known as Skaffen-Amtiskaw knew both of these people. It had once saved the woman''s life by massacring her attackers in a particularly bloody manner. It believed the man to be a burnt-out case. But not even its machine intelligence could see the horrors in his past. Praise for the Culture series: ''Epic in scope, ambitious in its ideas and absorbing in its execution'' Independent on Sunday ''Banks has created one of the most enduring and endearing visions of the future'' Guardian ''Jam-packed with extraordinary invention'' Scotsman ''Compulsive reading'' Sunday Telegraph The Culture series: Consider Phlebas The Player of Games Use of Weapons The State of the Art Excession Inversions Look to Windward Matter Surface Detail The Hydrogen Sonata Other books by Iain M. Banks: Against a Dark Background Feersum Endjinn The Algebraist', 432, null, 1990, 282097, (select id from series where hardcover_id = 1102), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Lost Souls', 'Cassandra Clare', '0606377360', 'https://assets.hardcover.app/edition/12600354/038e06be63b3d2a1be42daf525f84d53a1dcd3d0.jpeg', 'What price is too high to pay, even for love? When Jace and Clary meet again, Clary is horrified to discover that the demon Lilith’s magic has bound her beloved Jace together with her evil brother Sebastian, and that Jace has become a servant of evil. The Clave is out to destroy Sebastian, but there is no way to harm one boy without destroying the other. As Alec, Magnus, Simon, and Isabelle wheedle and bargain with Seelies, demons, and the merciless Iron Sisters to try to save Jace, Clary plays a dangerous game of her own. The price of losing is not just her own life, but Jace’s soul. She’s willing to do anything for Jace, but can she still trust him? Or is he truly lost?

Love. Blood. Betrayal. Revenge. Darkness threatens to claim the Shadowhunters in the harrowing fifth book of the Mortal Instruments series.', 544, null, 2011, 296683, (select id from series where hardcover_id = 5473), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Red Country', 'Joe Abercrombie', '9538230396', 'https://assets.hardcover.app/edition/30425772/39d2f2a9-ebfb-4d5e-b10d-52de2d6d7e2b.jpg', '"Abercrombie writes fantasy like no one else." - The Guardian They burned her home. They stole her brother and sister. But vengeance is following. Shy South hoped to bury her bloody past and ride away smiling, but she''ll have to sharpen up some bad old ways to get her family back, and she''s not a woman to flinch from what needs doing. She sets off in pursuit with only a pair of oxen and her cowardly old step father Lamb for company. But it turns out Lamb''s buried a bloody past of his own. And out in the lawless Far Country the past never stays buried. Their journey will take them across the barren plains to a frontier town gripped by gold fever, through feud, duel and massacre, high into the unmapped mountains to a reckoning with the Ghosts. Even worse, it will force them into an alliance with Nicomo Cosca, infamous soldier of fortune, and his feckless lawyer Temple, two men no one should ever have to trust . . . RED COUNTRY takes place in the same world as the First Law trilogy, Best Served Cold, andThe Heroes. This novel also represents the return of Logen Ninefingers, one of Abercrombie''s most beloved characters. First Law Trilogy The Blade Itself Before They Are Hanged Last Argument of Kings Novels in the First Law world Best Served Cold The Heroes Red Country', 451, null, 2012, 297006, (select id from series where hardcover_id = 6014), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('I Am Number Four', 'Pittacus Lore', '9794336068', 'https://assets.hardcover.app/edition/30400472/87748386-c3c5-4641-8300-de71cc4e6e84.jpg', 'Nine of us came here. We look like you. We talk like you. We live among you. But we are not you. We can do things you dream of doing. We have powers you dream of having. We are stronger and faster than anything you have ever seen. We are the superheroes you worship in movies and comic books—but we are real.

Our plan was to grow, and train, and become strong, and become one, and fight them. But they found us and started hunting us first. Now all of us are running. Spending our lives in shadows, in places where no one would look, blending in. we have lived among you without you knowing. But they know.

They caught Number One in Malaysia.
Number Two in England.
And Number Three in Kenya.
They killed them all.

I am Number Four. I am next.', 448, null, 2010, 300899, (select id from series where hardcover_id = 5768), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Thud!', 'Terry Pratchett', '1407033751', 'https://assets.hardcover.app/edition/30916964/ebcaedd1-f8cd-4d09-9712-a698d46fa7ed.jpg', '“Start with Douglas Adams’s comic science fiction (A Hitchhiker’s Guide to the Galaxy) and J.R.R. Tolkien’s alternative worlds, mix in James Ellroy’s gritty realism and Jonathan Swift’s unflinching satire and, if you’re lucky, you’ll get something like Terry Pratchett’s Thud!” —Wall Street Journal City Watch Commander Sam Vimes must solve the murder of a prominent dwarf or watch as Discworld is plunged into a bloody civil war in Terry Pratchett’s delightful Discworld satire, a brilliant tale of prejudice, ancient feuds, and tender fatherhood. Long, long ago, in a gods-forsaken hellhole called Koom Valley, trolls and dwarfs met in bloody combat. Centuries later, each side still views the other with simmering animosity that has been heightened of late because of one Grag Hamcrusher. The influential dwarf has been fomenting unrest among a section of Ankh-Morpork’s citizenry—a volatile situation made far worse when the petite provocateur is discovered bashed to death . . . with a troll club lying conveniently nearby. If he doesn’t solve the murder of just one dwarf, Commander Sam Vimes of Ankh-Morpork City Watch is going to see it fought again, right outside his office. But more than one corpse is waiting for Vimes in the eerie, summoning darkness of a labyrinthine mine network being secretly excavated beneath Ankh-Morpork’s streets. With war-drums beating ever louder, Vimes must unravel every clue, outwit every assassin, and brave any darkness to find the solution. And the darkness is following him, pulling him deep into the muck and mire of superstition, hatred, and fear—and perhaps all the way to Koom Valley itself. Until six o’clock every day, when without fail, the Commander goes home to read Where’s My Cow?, with accompanying farmyard noises, to his little boy. Because there are some things you must do. The Discworld novels can be read in any order but Thud! is the 7th book in the City Watch collection and the 34th Discworld book. The City Watch collection in order: Guards! Guards! Men at Arms Feet of Clay Jingo The Fifth Elephant Night Watch Thud! Snuff', 448, null, 2005, 301959, (select id from series where hardcover_id = 1018), '34') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Windup Girl', 'Paolo Bacigalupi', '9533165685', 'https://assets.hardcover.app/editions/30400552/8125924570364846.jpg', 'What Happens when bio-terrorism becomes a tool for corporate profits? And what happens when said bio-terrorism forces humanity to the cusp of post-human evolution? In The Windup Girl, award-winning author Paolo Bacigalupi returns to the world of "The Calorie Man"( Theodore Sturgeon Memorial Award-winner, Hugo Award nominee, 2006) and "Yellow Card Man" (Hugo Award nominee, 2007) in order to address these questions.', 359, null, 2001, 302367, (select id from series where hardcover_id = 5770), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bone Season', 'Samantha Shannon', '1408836459', 'https://assets.hardcover.app/edition/28319459/41c3376b2fb9c39ce407006fd335a376e496b698.jpeg', '"It is the year 2059. Several major world cities are under the control of a security force called Scion. Paige Mahoney works in the criminal underworld of Scion London, part of a secret cell known as the Seven Seals. The work she does is unusual: scouting for information by breaking into others’ minds. Paige is a dreamwalker, a rare kind of clairvoyant, and in this world, the voyants commit treason simply by breathing.

But when Paige is captured and arrested, she encounters a power more sinister even than Scion. The voyant prison is a separate city—Oxford, erased from the map two centuries ago and now controlled by a powerful, otherworldly race. These creatures, the Rephaim, value the voyants highly—as soldiers in their army.

Paige is assigned to a Rephaite keeper, Warden, who will be in charge of her care and training. He is her master. Her natural enemy. But if she wants to regain her freedom, Paige will have to learn something of his mind and his own mysterious motives."-- Provided by Amazon', 669, null, 2013, 314307, (select id from series where hardcover_id = 1209), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Exorcist', 'William Peter Blatty', '0062094351', 'https://assets.hardcover.app/edition/24555609/263b5d6d7949508ce4f75072eb0e03c132f9d755.jpeg', 'The Exorcist is a 1971 horror novel by American writer William Peter Blatty. The book details the demonic possession of eleven-year-old Regan MacNeil, the daughter of a famous actress, and the two priests who attempt to exorcise the demon. Published by Harper & Row, the novel was the basis of a highly successful film adaptation released two years later, whose screenplay was also written and produced by Blatty, and part of The Exorcist franchise.

The novel was inspired by a 1949 case of demonic possession and exorcism that Blatty heard about while he was a student in the class of 1950 at Georgetown University. As a result, the novel takes place in Washington, D.C., near the campus of Georgetown University. In September 2011, the novel was reprinted by Harper Collins to celebrate its fortieth anniversary, with slight revisions made by Blatty as well as interior title artwork by Jeremy Caniglia.', 402, null, 1971, 318352, (select id from series where hardcover_id = 6292), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Forward the Foundation', 'Isaac Asimov', '1439507198', 'https://assets.hardcover.app/edition/12696095/70d18a6b-ebfd-4e87-ae41-c2f0ee2b1f29.jpg', 'During the whole Foundation series, one man has always had his hand in the development of a galaxy. Merely hinted at in previous books, visited off and on for historical background - finally here delved into as deep as one can go - the demystified Hari Seldon. This follows about 40 years of his life, and traces his progress in the development of Psychohistory - the pseudo-mathematical science that would one day save the galaxy. 

If you have read the Foundation series, either in it''s entirety or just pieces, this is a must read. It also (if memory serves) is the last book Asimov wrote before his death - the final pages describing Hari Seldon''s final moments of life mirroring his own. A truly beautiful read.', 447, null, 1982, 319510, (select id from series where hardcover_id = 5450), '7') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Acceptance', 'Jeff VanderMeer, Helen Macdonald', '1443428442', 'https://assets.hardcover.app/edition/31755051/0e5ef45586536503bb81a20fc7094b7c73775662.jpeg', '"As Area X expands, the agency tasked with investigating and overseeing it―the Southern Reach―has collapsed in on itself in confusion. Now one last, desperate team crosses the border, determined to reach a remote island that may hold the answers they’ve been seeking. If they fail, the outer world is in peril.

Meanwhile, Acceptance tunnels ever deeper into the circumstances surrounding the creation of Area X―what initiated this unnatural upheaval? Among the many who have tried, who has gotten close to understanding Area X―and who may have been corrupted by it? In this last installment of Jeff VanderMeer’s Southern Reach Trilogy, the mysteries of Area X may be solved, but their consequences and implications are no less profound―or terrifying."-- Provided by Amazon', 352, null, 2014, 321750, (select id from series where hardcover_id = 1089), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Naked Sun', 'Isaac Asimov', '9780345330315', 'https://assets.hardcover.app/edition/30422717/61d07863cb87cf101f96a51c9fc73b4ee201f83f.jpeg', 'On the planet of Solaria, Spacers live in almost complete isolation, tended by robot servants and disgusted by the thought of human contact. And yet, one of their number has been beaten to death. Incapable of solving the crime, the authorities of the Outer Worlds seek help from Earth, from renowned detective Elijah Baley. Partnered once again with the robot Daneel Olivaw, Baley travels to this strange new world and uncovers a plot that could change the relationship between humans and robots for ever.', 256, null, 1953, 325240, (select id from series where hardcover_id = 1044), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wee Free Men', 'Terry Pratchett', '055257919X', 'https://assets.hardcover.app/edition/1946022/897748fe-e6bc-481c-b181-f98432780557.jpg', 'A riotous, wise, and gripping junior Discworld novel from the Carnegie Medal-winning author and acknowledged master of comic fantasy.Nine-year-old Tiffany Aching thinks her Granny Aching - a wise shepherd - might have been a witch, but now Granny Aching is dead and it''s up to Tiffany to work it all out when strange things begin happening: a fairy-tale monster in the stream, a headless horseman and, strangest of all, the tiny blue men in kilts, the Wee Free Men, who have come looking for the new ''hag''. These are the Nac Mac Feegles, the pictsies, who like nothing better than thievin'', fightin'' and drinkin''. Then Tiffany''s young brother goes missing and Tiffany and the Wee Free Men must join forces to save him from the Queen of the Fairies-', 336, null, 2003, 326042, (select id from series where hardcover_id = 1018), '30') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Renegades', 'Marissa Meyer', '8579804884', 'https://assets.hardcover.app/external_data/34559734/62caaeb181b3e2fef4d6306fdca534296b1c6633.jpeg', 'The Renegades are a syndicate of prodigies—humans with extraordinary abilities—who emerged from the ruins of a crumbled society and established peace and order where chaos reigned. As champions of justice, they remain a symbol of hope and courage to everyone...except the villains they once overthrew.

Nova has a reason to hate the Renegades, and she is on a mission for vengeance. As she gets closer to her target, she meets Adrian, a Renegade boy who believes in justice—and in Nova. But Nova''s allegiance is to the villains who have the power to end them both.', 577, null, 2013, 330349, (select id from series where hardcover_id = 1115), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Red Pyramid', 'Rick Riordan', '3867428883', 'https://assets.hardcover.app/edition/30400873/b9034a1d-8a05-43f4-953b-7bc13b37f7b6.jpg', 'Since their mother’s death, Carter and Sadie have become near strangers.  While Sadie has lived with her grandparents in London, her brother has traveled the world with their father, the brilliant Egyptologist, Dr. Julius Kane.

One night, Dr. Kane brings the siblings together for a “research experiment” at the British Museum, where he hopes to set things right for his family.  Instead, he unleashes the Egyptian god Set, who banishes him to oblivion and forces the children to flee for their lives.

Soon, Sadie and Carter discover that the gods of Egypt are waking, and the worst of them—Set—has his sights on the Kanes.  To stop him, the siblings embark on a dangerous journey across the globe—a quest that brings them ever closer to the truth about their family, and their links to a secret order that has existed since the time of the pharaohs.', 529, null, 2010, 331759, (select id from series where hardcover_id = 5784), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Battle', 'C. S. Lewis', '000732510X', 'https://assets.hardcover.app/edition/17265969/13278-L.jpg', 'The conclusion of the saga that began with The Magician''s Nephew', 290, null, 1956, 332776, (select id from series where hardcover_id = 5485), '7') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ghost Story', 'Jim Butcher', '045146379X', 'https://assets.hardcover.app/edition/20054127/3a9d0a39-d07c-487d-904f-4f9ed59e85e0.jpg', '"In his life, Harry''s been shot, stabbed, sliced, beaten, burned, crushed, and tortured. And after someone puts a bullet through his chest and leaves him to die in the waters of Lake Michigan, things really start going downhill. But even trapped in the realm between life and death, Harry can''t catch a break. 

He learns that three of his friends are destined to experience unbearable torment and agony. Only by bringing his murderer to justice can he save his friends and move on to what comes next--a feat that would be a lot easier if he had a body and access to his powers. 

Instead, Harry must work as a ghost, unable to interact with the physical world, invisible and inaudible to almost everyone. Unfortunately he''s not the only specter roaming Chicago. There are malevolent shadows who haven''t forgotten Harry''s predilection for putting evil in its place while he was alive. And now that Harry''s on their turf, they are looking for some serious payback. So the late Harry Dresden will have to pull off the ultimate trick without using any magic--or face an eternity as just another lost soul"--', 481, null, 2011, 333169, (select id from series where hardcover_id = 990), '13') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Thrawn', 'Timothy Zahn', '0425287076', 'https://assets.hardcover.app/external_data/59962191/111c85582d81b0b4beb6dc46143ee711c6574f0e.jpeg', '"Since his introduction in bestselling author Timothy Zahn’s classic Heir to the Empire, Grand Admiral Thrawn has earned an iconic status equal only to the most notorious of Sith lords, Darth Vader. But Thrawn’s origins and the story of his rise in the Imperial ranks have remained mysterious. Now, in Star Wars: Thrawn, Zahn chronicles the fateful events that launched the blue-skinned, red-eyed master of military strategy and lethal warfare into the highest realms of power—and infamy.
 
After Thrawn is rescued from exile by Imperial soldiers, his deadly ingenuity and keen tactical abilities swiftly capture the attention of Emperor Palpatine. And just as quickly, Thrawn proves to be as indispensable to the Empire as he is ambitious; as devoted as its most loyal servant, Darth Vader; and a brilliant warrior never to be underestimated. 

On missions to rout smugglers, snare spies, and defeat pirates, he triumphs time and again—even as his renegade methods infuriate superiors while inspiring ever greater admiration from the Empire. As one promotion follows another in his rapid ascension to greater power, he schools his trusted aide, Ensign Eli Vanto, in the arts of combat and leadership, and the secrets of claiming victory. But even though Thrawn dominates the battlefield, he has much to learn in the arena of politics where ruthless administrator Arihnda Pryce holds the power to be a potent ally or a brutal enemy.
 
All these lessons will be put to the ultimate test when Thrawn rises to admiral and must pit all the knowledge, instincts, and battle forces at his command against an insurgent uprising that threatens not only innocent lives but also the Empire’s grip on the galaxy—and his own carefully laid plans for future ascendancy."-- Provided by Amazon', 496, null, 2017, 336562, (select id from series where hardcover_id = 7956), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Truth', 'Terry Pratchett', '0552154253', 'https://assets.hardcover.app/edition/30917987/f57a53e4-793b-49b0-8e1e-89c14658dd82.jpg', '''A lie can run round the world before the truth can get its boots on.'' William de Worde has somehow found himself editor of Ankh-Morpork''s first newspaper. Well, with a name like that . . . Launched into the world of investigative journalism, alongside reporter Sacharissa Cripslock, William soon learns that the news is a risky business. For a start, his colleagues include a band of axe-wielding dwarfs and a recovering vampire with a life-threatening passion for flash photography. It''s a big news week: the most powerful man in the city has been arrested, leaving Ankh-Morpork without a leader. And a dangerous criminal organisation will do anything to control the story . . . ''An unmitigated delight . . . very, very funny'' The Times The Discworld novels can be read in any order but The Truth is a standalone.', 448, null, 1995, 337035, (select id from series where hardcover_id = 1018), '25') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Sword of Summer', 'Rick Riordan', '2017027820', 'https://assets.hardcover.app/editions/30399693/6074236274781526.jpg', 'Magnus Chase has seen his share of trouble. Ever since that terrible night two years ago when his mother told him to run, he has lived alone on the streets of Boston, surviving by his wits, staying one step ahead of the police and the truant officers.

One day, Magnus learns that someone else is trying to track him down—his uncle Randolph, a man his mother had always warned him about. When Magnus tries to outmaneuver his uncle, he falls right into his clutches. Randolph starts rambling about Norse history and Magnus''s birthright: a weapon that has been lost for thousands of years.

The more Randolph talks, the more puzzle pieces fall into place. Stories about the gods of Asgard, wolves, and Doomsday bubble up from Magnus''s memory. But he doesn''t have time to consider it all before a fire giant attacks the city, forcing him to choose between his own safety and the lives of hundreds of innocents. . . .

Sometimes, the only way to start a new life is to die.', 491, null, 2015, 337645, (select id from series where hardcover_id = 1585), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lords and Ladies', 'Terry Pratchett', '0575052236', 'https://assets.hardcover.app/edition/30575964/9af54ca0-40f9-4788-804f-f79bd23067fe.jpg', 'The fairies are back - but this time they don''t just want your teeth...

Granny Weatherwax and her tiny coven are up against real elves.

It''s Midsummer Night.

No times for dreaming...

With full supporting cast of dwarfs, wizards, trolls, Morris dancers and one orang-utan. And lots of hey-nonny-nonny and blood all over the place.', 378, null, 1992, 339869, (select id from series where hardcover_id = 1018), '14') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Summer Knight', 'Jim Butcher', '1101133945', 'https://assets.hardcover.app/edition/5293286/cacf011abed325441df047b7490a23e747a0e04c.jpeg', 'Ever since his girlfriend left town to deal with her newly acquired taste for blood, Harry Dresden has been down and out in Chicago. He can''t pay his rent. He''s alienating his friends. He can''t even recall the last time he took a shower. 

The only professional wizard in the phone book has become a desperate man. 

And just when it seems things can''t get any worse, in saunters the Winter Queen of Faerie. She has an offer Harry can''t refuse if he wants to free himself of the supernatural hold his faerie godmother has over him — and hopefully end his run of bad luck. All he has to do is find out who murdered the Summer Queen''s right-hand man, the Summer Knight, and clear the Winter Queen''s name. 

It seems simple enough, but Harry knows better than to get caught in the middle of faerie politics. Until he finds out that the fate of the entire world rests on his solving this case. 

No pressure or anything...', 446, null, 2002, 341498, (select id from series where hardcover_id = 990), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Battle Ground', 'Jim Butcher', '0356515729', 'https://assets.hardcover.app/external_data/38965317/68ea8aeeddb8bf753cf2d41a3edcdfa2a01ac54a.jpeg', 'Harry has faced terrible odds before. He has a long history of fighting enemies above his weight class. The Red Court of vampires. The fallen angels of the Order of the Blackened Denarius. The Outsiders.

But this time it’s different. A being more powerful and dangerous on an order of magnitude beyond what the world has seen in a millennium is coming. And she’s bringing an army. The Last Titan has declared war on the city of Chicago, and has come to subjugate humanity, obliterating any who stand in her way.

Harry’s mission is simple but impossible: Save the city by killing a Titan. And the attempt will change Harry’s life, Chicago, and the mortal world forever.', 434, null, 2020, 342378, (select id from series where hardcover_id = 990), '17') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Carpe Jugulum', 'Terry Pratchett', '0061020397', 'https://assets.hardcover.app/edition/31519215/a4c4173cdd73db71f509eab426ba4d35bdda5791.jpeg', 'Carpe Jugulum (Latin for "seize the throat", cf. Carpe diem) is a comic fantasy novel by Terry Pratchett, the twenty-third in the Discworld series. It was first published in 1998.

In Carpe Jugulum, Terry Pratchett pastiches the traditions of vampire literature, playing with the mythic archetypes and featuring a tongue-in-cheek reversal of ''vampyre'' subculture with young vampires who wear bright clothes, drink wine, and stay up until noon. (description taken from [Wikipedia][1])


  [1]: https://en.wikipedia.org/wiki/Carpe_Jugulum', 416, null, 1998, 345699, (select id from series where hardcover_id = 1018), '23') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Naked Lunch', 'William S. Burroughs', '8402081762', 'https://assets.hardcover.app/edition/3899749/f105ee75178322d49025760a3a74d153a28b7911.jpeg', 'Controversial and bizarre cult novel based on the author’s own experiences as a drug addict, first published in 1959. Formed as a series of inter-connected adventures set in locations as diverse as the U.S. Mexico and Morocco sees the protagonist, Burroughs’ alter-ego William Lee on the run from the police and always searching for his next fix. Burroughs once stated that the chapters can be read in any order.', 288, null, 1959, 346984, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Reamde', 'Neal Stephenson', '0062106422', 'https://assets.hardcover.app/editions/30451598/5532944589427888.jpg', 'Across the globe, millions of computer screens flicker with the artfully coded world of T''Rain - an addictive internet role-playing game of fantasy and adventure. But backstreet hackers in China have just unleashed a contagious virus called Reamde, and as it rampages through the gaming world spreading from player to player - holding hard drives hostage in the process - the computer of one powerful and dangerous man is infected, causing the carefully mediated violence of the on-line world to spill over into reality. A fast-talking, internet-addicted mafia accountant is brutally silenced by his Russian employers, and Zula - a talented young T''Rain computer programmer - is abducted and bundled on to a private jet. As she is flown across the skies in the company of the terrified boyfriend she broke up with hours before, and a brilliant Hungarian hacker who may be her only hope, she finds herself sucked into a whirl of Chinese Secret Service agents and gun-toting American Survivalists; the Russian criminal underground and an al-Qaeda cell led by a charismatic Welshman; each a strand of a connected world that devastatingly converges in T''Rain. An inimitable and compelling thriller that careers from British Columbia to South-West China via Russia and the fantasy world of T''Rain, Reamde is an irresistible epic from the unique imagination of one of today''s most individual writers.', 1056, null, 2011, 347774, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('After Dark', 'Haruki Murakami, Jay Rubin', '9734670182', 'https://assets.hardcover.app/editions/1924870/302280743261159.jpg', 'A short, sleek novel of encounters set in the witching hours of Tokyo between midnight and dawn, and every bit as gripping as Haruki Murakami’s masterworks The Wind-Up Bird Chronicle and Kafka on the Shore.

At its center are two sisters: Yuri, a fashion model sleeping her way into oblivion; and Mari, a young student soon led from solitary reading at an anonymous Denny’s into lives radically alien to her own: those of a jazz trombonist who claims they’ve met before; a burly female “love hotel” manager and her maidstaff; and a Chinese prostitute savagely brutalized by a businessman. These “night people” are haunted by secrets and needs that draw them together more powerfully than the differing circumstances that might keep them apart, and it soon becomes clear that Yuri’s slumber–mysteriously tied to the businessman plagued by the mark of his crime – will either restore or annihilate her.

After Dark moves from mesmerizing drama to metaphysical speculation, interweaving time and space as well as memory and perspective into a seamless exploration of human agency – the interplay between self-expression and understanding, between the power of observation and the scope of compassion and love. Murakami’s trademark humor, psychological insight, and grasp of spirit and morality are here distilled with an extraordinary, harmonious mastery.', 191, null, 2004, 354537, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The City of Ember', 'Jeanne DuPrau', '0606268103', 'https://assets.hardcover.app/editions/30403584/2764421111673647-9780375822742_custom-6a805cc491baef4546bf9bc4b0567d89e64f31ca-s6-c30.jpg', 'The city of Ember was built as a last refuge for the human race. Two hundred years later, the great lamps that light the city are beginning to dim. When Lina finds part of an ancient message, she’s sure it holds a secret that will save the city. Now, she and her friend Doon must race to figure out the clues to keep the lights on. If they succeed, they will have to convince everyone to follow them into danger. But if they fail? The lights will burn out and the darkness will close in forever.', 270, null, 2003, 362374, (select id from series where hardcover_id = 5802), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fountainhead', 'Ayn Rand', '0452273331', 'https://assets.hardcover.app/edition/14870863/e8168a2d424d4123c9d9ae6363d4f0a12a74c596.jpeg', 'The revolutionary literary vision that sowed the seeds of Objectivism, Ayn Rand''s groundbreaking philosophy, and brought her immediate worldwide acclaim.

This modern classic is the story of intransigent young architect Howard Roark, whose integrity was as unyielding as granite...of Dominique Francon, the exquisitely beautiful woman who loved Roark passionately, but married his worst enemy...and of the fanatic denunciation unleashed by an enraged society against a great creator. As fresh today as it was then, Rand’s provocative novel presents one of the most challenging ideas in all of fiction—that man’s ego is the fountainhead of human progress...

“A writer of great power. She has a subtle and ingenious mind and the capacity of writing brilliantly, beautifully, bitterly...This is the only novel of ideas written by an American woman that I can recall.”—The New York Times ', 728, null, 1943, 367940, (select id from series where hardcover_id = 68954), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Humans', 'Matt Haig', '1471236137', 'https://assets.hardcover.app/edition/30399750/dcc0e089-26df-44c8-baef-ec8635ce1727.jpg', 'When an extra-terrestrial visitor arrives on Earth, his first impressions of the human species are less than positive. Taking the form of Professor Andrew Martin, a prominent mathematician at Cambridge University, the visitor is eager to complete the gruesome task assigned him and hurry home to his own utopian planet, where everyone is omniscient and immortal.

He is disgusted by the way humans look, what they eat, their capacity for murder and war, and is equally baffled by the concepts of love and family. But as time goes on, he starts to realize there may be more to this strange species than he had thought. Disguised as Martin, he drinks wine, reads poetry, develops an ear for rock music, and a taste for peanut butter. Slowly, unexpectedly, he forges bonds with Martin’s family. He begins to see hope and beauty in the humans’ imperfection, and begins to question the very mission that brought him there.', 304, null, 2013, 368374, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wilder Girls', 'Rory Power', '8418002743', 'https://assets.hardcover.app/external_data/40672680/da55090d5da59218a1c0c6b342c5aec17a88c8cf.jpeg', '**IT''S BEEN EIGHTEEN MONTHS** since the Raxter School for Girls was put under quarantine. Since the Tox hit and pulled Hetty''s life out from under her.

It started slow. First the teachers died one by one. Then it began to infect the students, turning their bodies strange and foreign. Now, cut off from the rest of the world and left to fend for themselves on their island home, the girls don''t dare wander outside the school''s fence, where the Tox has made the woods wild and dangerous. They wait for the cure they were promised as the Tox seeps into everything.

But when Byatt goes missing, Hetty will do anything to find her, even if it means breaking quarantine and braving the horrors that lie beyond the fence. And when she does, Hetty learns that there''s more to their story, to their life at Raxter, than she could have ever thought true.

This description comes from the publisher.', 370, null, 2019, 368716, (select id from series where hardcover_id = 6325), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Homeland', 'R. A. Salvatore', '7770684196', 'https://assets.hardcover.app/edition/4959462/9ffd36a7b93bcbc15d7415cb1cd4a5ae8fe517e0.jpeg', 'Drow ranger Drizzt Do''Urden, first introduced in The Icewind Dale Trilogy, quickly became one of the fantasy genre''s standout characters. But Homeland first reveals the startling tale of how this one lone drow walked out of the shadowy depths of the Underdark, leaving behind a society of evil and a family who want him dead. It is here that the story of this amazing dark elf truly began.', 343, null, 1990, 369226, (select id from series where hardcover_id = 10144), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bluest Eye', 'Toni Morrison', '0808562827', 'https://assets.hardcover.app/external_data/42437748/6778e56629eaa4a607d61573f5792ccc0f4671b1.jpeg', '"So that she will be beautiful, so that people will look at her, so that her world will be different. This is the story of the nightmare at the heart of her yearning, and the tragedy of its fulfillment."-- Provided by Amazon', 205, null, 1970, 373323, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Maskerade', 'Terry Pratchett', '0575058080', 'https://assets.hardcover.app/edition/31705900/7228f6f8fdf48034bb4cc422c0ffa357d74a272a.jpeg', 'The Opera House, Ankh-Morpork: a huge rambling building, where innocent young sopranos are lured to their destiny by a strangely familiar evil mastermind in a hideously deformed evening dress. But Granny Weatherwax is in the audience, and she doesn’t hold with that sort of thing. So there’s going to be trouble (but nevertheless a good evening’s entertainment with murders you can really hum.)', 285, null, 1995, 374210, (select id from series where hardcover_id = 1018), '18') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Paradise Lost', 'John Milton, John      Leonard', '9629546671', 'https://assets.hardcover.app/editions/3757554/1919948996411096.jpg', 'It tells the story of the Fall of Man, a tale of immense drama and excitement, of rebellion and treachery, of innocence pitted against corruption, in which God and Satan fight a bitter battle for control of mankind''s destiny. 

The struggle rages across three worlds - heaven, hell, and earth - as Satan and his band of rebel angels plot their revenge against God. At the center of the conflict are Adam and Eve, who are motivated by all too human temptations but whose ultimate downfall is unyielding love.

Marked by Milton''s characteristic erudition, Paradise Lost is a work epic both in scale and, notoriously, in ambition. For nearly 350 years, it has held generation upon generation of audiences in rapt attention, and its profound influence can be seen in almost every corner of Western culture.', 512, null, 1667, 377089, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Making Money', 'Terry Pratchett', '3442546311', 'https://assets.hardcover.app/edition/31519104/4f3957c5cd69568bc34d45e7ab530b8593d93e96.jpeg', 'Cue Moist von Lipwig, Postmaster General and former con artist. If anyone can rescue the city''s ailing financial institution, it''s him. He doesn''t really want the job, but the thing is, he doesn''t have a choice.

Moist has many problems to solve as part of his new role: the chief cashier is almost certainly a vampire, the chairman needs his daily walkies, there''s something strange happening in the cellar, and the Royal Mint is running at a loss.

Moist begins making some ambitious changes . . . and some dangerous enemies.

Because money is power and certain stakeholders will do anything to keep a firm grip on both . . .', 475, null, 2007, 377256, (select id from series where hardcover_id = 1018), '36') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lincoln in the Bardo', 'George Saunders', '8324055428', 'https://assets.hardcover.app/external_data/37178166/56a00c139c890ff18802c0a049fbc0a13c0d36bd.jpeg', 'February 1862. The Civil War is less than one year old. The fighting has begun in earnest, and the nation has begun to realize it is in for a long, bloody struggle. Meanwhile, President Lincoln''s beloved eleven-year-old son, Willie, lies upstairs in the White House, gravely ill. In a matter of days, despite predictions of a recovery, Willie dies and is laid to rest in a Georgetown cemetery. "My poor boy, he was too good for this earth," the president says at the time. "God has called him home." Newspapers report that a grief-stricken Lincoln returns, alone, to the crypt several times to hold his boy''s body. From that seed of historical truth, George Saunders spins a story of familial love and loss that breaks free of its historical framework into a supernatural realm both hilarious and terrifying. Willie Lincoln finds himself in a strange purgatory where ghosts mingle, gripe, commiserate, quarrel, and enact bizarre acts of penance. Within this transitional state -- called, in the Tibetan tradition, the bardo -- a monumental struggle erupts over young Willie''s soul.', 343, null, 2017, 377416, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Daemon', 'Daniel Suarez', '0143144448', 'https://assets.hardcover.app/external_data/47289868/d407165dc9cc434362af727adc8601a94ea03500.jpeg', 'Technology controls almost everything in our modern-day world, from remote entry on our cars to access to our homes, from the flight controls of our airplanes to the movements of the entire world economy. Thousands of autonomous computer programs, or daemons, make our networked world possible, running constantly in the background of our lives, trafficking e-mail, transferring money, and monitoring power grids. For the most part, daemons are benign, but the same can''t always be said for the people who design them.

Matthew Sobol was a legendary computer game designer—the architect behind half-a-dozen popular online games. His premature death depressed both gamers and his company''s stock price. But Sobol''s fans aren''t the only ones to note his passing. When his obituary is posted online, a previously dormant daemon activates, initiating a chain of events intended to unravel the fabric of our hyper-efficient, interconnected world. With Sobol''s secrets buried along with him, and as new layers of his daemon are unleashed at every turn, it''s up to an unlikely alliance to decipher his intricate plans and wrest the world from the grasp of a nameless, faceless enemy—or learn to live in a society in which we are no longer in control. . . .', 482, null, 2006, 377567, (select id from series where hardcover_id = 1056), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ship of Destiny', 'Robin Hobb', '9029066733', 'https://assets.hardcover.app/external_data/693339/dd610a024b1f9aa2c8c633d02fc1c49da47c11e4.jpeg', 'Robin Hobb has established herself as one of the masters of fantasy fiction And nowhere is that more apparent than in this powerful, poignant, swashbuckling epic of treachery, heroism, and humanity.  The rousing conclusion to the Liveship Traders trilogy, Ship of Destiny is the spellbinding story of a once-thriving city now reduced to shambles by raging war and rampant greed; of a glorious and mythic species on the brutal edge of extinction; and of the Vestrits, the clan, whose destiny is intertwined with both.Bingtown is a city under fire from forces within and without. While accusations of conspiracy fly between the Old Bingtown Traders and the New, invaders attack the harbor, trying to take the city for their own.  Matriarch Ronica Vestrit bears witness to the destruction, but she is not the type of woman to simply surrender.  Even as she finds herself branded a traitor, she searches for a way to bring all the city''s inhabitants together to stand against the Chalcedean threat.  But there is someone who cannot allow Ronica to succeed, no matter what the cost.Far out on the stormy seas, Althea Vestrit, ignorant of all that has befallen Bingtown, continues her mission to track down and recover her liveship Vivacia from the ruthless pirate Kennit.  Serving as the Paragon''s second mate under Captain Brashen, she faces peril beyond imagining... not just from her growing love for Brashen or their reckless scheme to regain the Vivacia, but from the unpredictable vessel Paragon himself, as he wrestles with his madness and plots his own deadly brand of revenge.Yet Althea''s bold scheme may be in vain.  For her beloved Vivacia will face the most terrible confrontation of all as the secret of the liveships is finally revealed.  This is a truth so horrifying, so shattering, it may destroy the Vivacia and all who love her, including the boy-priest Wintrow Vestrit, whose life already hangs in the balance...A triumph of imagination and masterful storytelling, Ship of Destiny is an enthralling blend of intrigue and magic, drama and high fantasy.  It is the fitting conclusion to a tale that is bound to become a classic--by a beguiling author who is already deservedly revered.From the Hardcover edition.', 903, null, 1999, 378786, (select id from series where hardcover_id = 5991), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gulliver''s Travels', 'Jonathan Swift, Malvina G. Vogel', '080851959X', 'https://assets.hardcover.app/edition/13337767/88ad340f0a2ba6d98bd529a399855082735f4aad.jpeg', 'The voyages of an eighteenth-century Englishman carry him to such strange places as Lilliput, where people are six inches tall, and Brobdingnag, a land peopled by giants.', 462, null, 1726, 379497, (select id from series where hardcover_id = 6570), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wasp Factory', 'Iain Banks', '859454006X', 'https://assets.hardcover.app/edition/6503291/48b7933e8c6010722a63c9d9444f01a234bb4e27.jpeg', 'Frank, no ordinary sixteen-year-old, lives with his father outsIde a remote Scottish village. Their life is, to say the least, unconventional. Frank''s mother abandoned them years ago: his elder brother Eric is confined to a psychiatric hospital; and his father measures out his eccentricities on an imperial scale. Frank has turned to strange acts of violence to vent his frustrations. In the bizarre daily rituals there is some solace. But when news comes of Eric''s escape from the hospital Frank has to prepare the ground for his brother''s inevitable return - an event that explodes the mysteries of the past and changes Frank utterly. Iain Banks'' celebrated first novel is a work of extraordinary originality, imagination and horrifying compulsion: horrifying, because it enters a mind whose realities are not our own, whose values of life and death are alien to our society; and compulsive, because the humour and compassion of that mind reach out to us all.', 244, null, 1984, 380645, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Day of the Triffids', 'John Wyndham', '0449013227', 'https://assets.hardcover.app/edition/17928877/8191102-L.jpg', 'When Bill Masen wakes up blindfolded in hospital there is a bitter irony in his situation. Carefully removing his bandages, he realizes that he is the only person who can see: everyone else, doctors and patients alike, have been blinded by a meteor shower. Now, with civilization in chaos, the triffids - huge, venomous, large-rooted plants able to ''walk'', feeding on human flesh - can have their day.', 272, null, 1951, 381999, (select id from series where hardcover_id = 5820), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Prey', 'Michael Crichton', '1417669896', 'https://assets.hardcover.app/external_data/33690666/8fc4476f9500264287d0e2e990774dbbe868cdb0.jpeg', 'In the Nevada desert, an experiment has gone horribly wrong. A cloud of nanoparticles -- micro-robots -- has escaped from the laboratory. This cloud is self-sustaining and self-reproducing. It is intelligent and learns from experience. For all practical purposes, it is alive.

It has been programmed as a predator. It is evolving swiftly, becoming more deadly with each passing hour.

Every attempt to destroy it has failed.

And we are the prey.
--back cover', 528, null, 2002, 383682, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Spin', 'Robert Charles Wilson', '142720540X', 'https://assets.hardcover.app/editions/30400675/20e792df-57b9-4fba-97b4-dc67c2b7cd59.jpg', '<p><b>Now in a Tor Essentials edition, Robert Charles Wilson''s <i>Spin</i>, a Hugo-winning novel of breathtaking cosmic scope</b>.<br><br>One night in October when he was ten years old, Tyler Dupree stood in his backyard and watched the stars go out. They all flared into brilliance at once, then disappeared, replaced by a flat, empty black barrier. He and his best friends, Jason and Diane Lawton, had seen what became known as the Big Blackout. It would shape their lives. <br><br>The effect is worldwide. The sun is now a featureless disk--a heat source, rather than an astronomical object. The moon is gone, but tides remain. Not only have the world''s artificial satellites fallen out of orbit, their recovered remains are pitted and aged, as though they''d been in space far longer than their known lifespans. As Tyler, Jason, and Diane grow up, space probe reveals a bizarre truth: The barrier is artificial, generated by huge alien artifacts. Time is passing faster outside the barrier than inside--more than a hundred million years per day on Earth. At this rate, the death throes of the sun are only about forty years in our future. <br><br>Jason, now a promising young scientist, devotes his life to working against this slow-moving apocalypse. Diane throws herself into hedonism, marrying a sinister cult leader who''s forged a new religion out of the fears of the masses.<br><br>Earth sends terraforming machines to Mars to let the onrush of time do its work, turning the planet green. Next they send humans...and immediately get back an emissary with thousands of years of stories to tell about the settling of Mars. Then Earth''s probes reveal that an identical barrier has appeared around Mars. Jason, desperate, seeds near space with self-replicating machines that will scatter copies of themselves outward from the sun--and report back on what they find. <br><br>Life on Earth is about to get much, much stranger.</p>', 320, null, 2005, 383752, (select id from series where hardcover_id = 5827), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wonder', 'R. J. Palacio', '8496735745', 'https://assets.hardcover.app/edition/13191538/06ce4dae00f9ab1c5799cd4199a1fbd42af87eed.jpeg', 'August Pullman was born with a facial difference that, up until now, has prevented him from going to a mainstream school. Starting 5th grade at Beecher Prep, he wants nothing more than to be treated as an ordinary kid—but his new classmates can’t get past Auggie’s extraordinary face. Beginning from Auggie’s point of view and expanding to include his classmates, his sister, her boyfriend, and others, the perspectives converge to form a portrait of one community’s struggle with empathy, compassion, and acceptance. In a world where bullying among young people is an epidemic, this is a refreshing new narrative full of heart and hope.', 315, null, 2012, 384730, (select id from series where hardcover_id = 1462), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nimona', 'ND Stevenson', '6254482754', 'https://assets.hardcover.app/external_data/4210593/a35ebacfa83180b98880b3883a028b9512f03f59.jpeg', 'Nemeses! Dragons! Science! Symbolism! All these and more await in this brilliantly subversive, sharply irreverent epic from Noelle Stevenson. Featuring an exclusive epilogue not seen in the web comic, along with bonus conceptual sketches and revised pages throughout, this gorgeous full-color graphic novel is perfect for the legions of fans of the web comic and is sure to win Noelle many new ones.

Nimona is an impulsive young shapeshifter with a knack for villainy. Lord Ballister Blackheart is a villain with a vendetta. As sidekick and supervillain, Nimona and Lord Blackheart are about to wreak some serious havoc. Their mission: prove to the kingdom that Sir Ambrosius Goldenloin and his buddies at the Institution of Law Enforcement and Heroics aren''t the heroes everyone thinks they are.

But as small acts of mischief escalate into a vicious battle, Lord Blackheart realizes that Nimona''s powers are as murky and mysterious as her past. And her unpredictable wild side might be more dangerous than he is willing to admit.', 272, null, 2015, 385876, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Timeline', 'Michael Crichton', '061333633X', 'https://assets.hardcover.app/edition/8748012/923d66b8ce01af534ba6421a2b69577f17e99a7d.jpeg', 'At the dawn of the twenty-first century, bold advances in technology exceed all expectations. Computers are built from single molecules. Information moves instantly with no wires or networks. Even moments from the past can be actualized. Now, suddenly, a group of historians have literally entered life in fourteenth-century feudal France. And the world may never be the same again.

Not since Jurassic Park has Michael Crichton given us such a magnificent adventure. Here the science of the future collides head-on with the complex realities of the medieval past. In a gripping-heart-stopping narrative, TIMELINE carries us into a realm of unexpected suspense and danger. overturning our most basic ideas of what is possible...
(back cover)', 514, null, 1999, 386276, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Endymion', 'Dan Simmons', '2221082680', 'https://assets.hardcover.app/edition/31928363/e84be7b3-741e-4fa9-8fc6-b2a199a1b851.jpg', 'Two hundred and seventy-four years after the fall of the WorldWeb in Fall of Hyperion, Raoul Endymion is sent on a quest. Retrieving Aenea from the Sphinx before the Church troops reach her is only the beginning. With hel from a blue-skinned android named A. Bettik, Raoul and Aenea travel the river Tethys, pursued by Father Captain Frederico DeSoya, an influential warrior-priest and his troops. The shrike continues to make enigmatic appearances, and while many questions were raised in Hyperion and Fall of Hyperion, still more are raised here. Raoul''s quest will continue.
', 577, null, 1996, 427353, (select id from series where hardcover_id = 1049), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Unicorn', 'Peter S. Beagle, Patrick Rothfuss', '3608952047', 'https://assets.hardcover.app/edition/11743308/e453fafad2c798b6e98112b76151de0d43d55f6b.jpeg', '*The unicorn lived in a lilac wood, and she lived all alone…*

 …so she ventured out from the safety of the enchanted forest on a quest for others of her kind. Joined along the way by the bumbling magician Schmendrick and the indomitable Molly Grue, the unicorn learns all about the joys and sorrows of life and love before meeting her destiny in the castle of a despondent monarch—and confronting the creature that would drive her kind to extinction....

In *The Last Unicorn*, renowned and beloved novelist Peter S. Beagle spins a poignant tale of love, loss, and wonder that has resonated with millions of readers around the world.', 292, null, 1968, 427357, (select id from series where hardcover_id = 1105), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Stars My Destination', 'Alfred Bester', '9176085007', 'https://assets.hardcover.app/editions/20342771/6788161936437989-59475344.jpg', 'In this pulse-quickening novel, Alfred Bester imagines a future in which people "jaunte" a thousand miles with a single thought, where the rich barricade themselves in labyrinths and protect themselves with radioactive hitmen—and where an inarticulate outcast is the most valuable and dangerous man alive.

The Stars My Destination is a classic of technological prophecy and timeless narrative enchantment by an acknowledged master of science fiction.', 278, null, 1955, 427359, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dragons of Autumn Twilight', 'Margaret Weis', '0316424714', 'https://assets.hardcover.app/edition/30599579/e1a415b8945d7fafba1ba5fb5e455bc07cb8b80b.jpeg', 'Once merely creatures of legend, the dragons have returned to Krynn. But with their arrival comes the departure of the old gods—and all healing magic. As war threatens to engulf the land, lifelong friends reunite for an adventure that will change their lives and shape their world forever . . .

When Tanis, Sturm, Caramon, Raistlin, Flint, and Tasslehoff see a woman use a blue crystal staff to heal a villager, they wonder if it''s a sign the gods have not abandoned them after all. Fueled by this glimmer of hope, the Companions band together to uncover the truth behind the gods'' absence—though they aren''t the only ones with an interest in the staff. The Seekers, a new religious order, wants the artifact for their own ends, believing it will help them replace the gods and overtake the continent of Ansalon. Now, the Companions must assume the unlikely roles of heroes if they hope to prevent the staff from falling into the hands of darkness.

Lifelong friends, they went their separate ways. Now they are together again, though each holds secrets from the others in his heart. They speak of a world shadowed with rumors of war. They speak of tales of strange monsters, creatures of myth, creatures of legend. They do not speak of their secrets. Not then. Not until a chance encounter with a beautiful, sorrowful woman, who bears a magical crystal staff, draws the companions deeper into the shadows, forever changing their lives and shaping the fate of the world.

No one expected them to be heroes.

Least of all, them.', 448, null, 1984, 427388, (select id from series where hardcover_id = 1131), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Unravel Me', 'Tahereh Mafi', '2749918863', 'https://assets.hardcover.app/editions/10365995/7317734863225911.jpg', 'Juliette has escaped to Omega Point. It is a place for people like her—people with gifts—and it is also the headquarters of the rebel resistance.

She''s finally free from The Reestablishment, free from their plan to use her as a weapon, and free to love Adam. But Juliette will never be free from her lethal touch.

Or from Warner, who wants Juliette more than she ever thought possible.

In this exhilarating sequel to Shatter Me, Juliette has to make life-changing decisions between what she wants and what she thinks is right. Decisions that might involve choosing between her heart—and Adam''s life.', 496, null, 2013, 427487, (select id from series where hardcover_id = 1064), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('House of Suns', 'Alastair Reynolds', '2381631291', 'https://assets.hardcover.app/editions/1236926/3a8f3800-e490-47bf-b64b-01316d99d1ae-houseofsuns.jpg', 'Six million years ago, at the dawn of the star-faring era, Abigail Gentian fractured herself into a thousand male and female clones, which she called shatterlings. She sent them out into the galaxy to observe and document the rise and fall of countless human empires. Since then, every two hundred thousand years, they gather to exchange news and memories of their travels.Only this millennium there is no gathering. Someone is eliminating the Gentian line. And Campion and Purslane—two shatterlings who have fallen in love and shared forbidden experiences— must determine exactly who, or what, their enemy is, before they are wiped out of existence.', 484, null, 2008, 427505, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Axiom''s End', 'Lindsay Ellis', '1250256739', 'https://assets.hardcover.app/edition/23378293/d19bfbce-1575-4219-9054-610d1522f2a5.jpg', 'THE INSTANT NEW YORK TIMES BESTSELLER The alternate history first contact adventure Axiom''s End is an extraordinary debut from Hugo finalist and video essayist Lindsay Ellis. Truth is a human right. It’s fall 2007. A well-timed leak has revealed that the US government might have engaged in first contact. Cora Sabino is doing everything she can to avoid the whole mess, since the force driving the controversy is her whistleblower father. Even though Cora hasn’t spoken to him in years, his celebrity has caught the attention of the press, the Internet, the paparazzi, and the government—and with him in hiding, that attention is on her. She neither knows nor cares whether her father’s leaks are a hoax, and wants nothing to do with him—until she learns just how deeply entrenched her family is in the cover-up, and that an extraterrestrial presence has been on Earth for decades. Realizing the extent to which both she and the public have been lied to, she sets out to gather as much information as she can, and finds that the best way for her to uncover the truth is not as a whistleblower, but as an intermediary. The alien presence has been completely uncommunicative until she convinces one of them that she can act as their interpreter, becoming the first and only human vessel of communication. Their otherworldly connection will change everything she thought she knew about being human—and could unleash a force more sinister than she ever imagined.', 384, null, 2020, 427540, (select id from series where hardcover_id = 1068), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Off to Be the Wizard', 'Scott Meyer', '3958351549', 'https://assets.hardcover.app/editions/12252114/230118369051022.jpg', 'Martin Banks is just a normal guy who has made an abnormal discovery: he can manipulate reality, thanks to reality being nothing more than a computer program. With every use of this ability, though, Martin finds his little "tweaks" have not escaped notice. Rather than face prosecution, he decides instead to travel back in time to the Middle Ages and pose as a wizard. What could possibly go wrong? An American hacker in King Arthur''s court, Martin must now train to become a full-fledged master of his powers, discover the truth behind the ancient wizard Merlin ... and not, y''know, die or anything.', 373, null, 2013, 427622, (select id from series where hardcover_id = 1028), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ariadne', 'Jennifer Saint', '1472273893', 'https://assets.hardcover.app/external_data/37179947/ad3205bc35862e598aba9c78ba7cea504462c782.jpeg', 'Ariadne, Princess of Crete, grows up greeting the dawn from her beautiful dancing floor and listening to her nursemaid’s stories of gods and heroes. But beneath her golden palace echo the ever-present hoofbeats of her brother, the Minotaur, a monster who demands blood sacrifice.

When Theseus, Prince of Athens, arrives to vanquish the beast, Ariadne sees in his green eyes not a threat but an escape. Defying the gods, betraying her family and country, and risking everything for love, Ariadne helps Theseus kill the Minotaur. But will Ariadne’s decision ensure her happy ending? And what of Phaedra, the beloved younger sister she leaves behind?

Hypnotic, propulsive, and utterly transporting, Jennifer Saint''s Ariadne forges a new epic, one that puts the forgotten women of Greek mythology back at the heart of the story, as they strive for a better world.', 304, null, 1991, 427734, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hope of Elantris', 'Brandon Sanderson', '9798200818761', 'https://assets.hardcover.app/edition/30399224/97aa1feb-6a66-46ec-82ab-50d1e6f1b65e.jpg', 'The following is a short story I wrote in the Elantris world back in January of 2006. At that point, Elantris had only been out in stores for about seven or eight months, but I actually hadn''t written anything new on the story or world since 2000, when I''d finished the first draft of the original book. This story was originally posted for sale on Amazon.com; once the contract with them ran out, I posted it on my website.

There were always a few holes in the manuscript where I decided not to include viewpoints or sections of explanation in the name of streamlining, particularly at the end. In the back of my mind, I knew what happened. This story talks about one of those holes; it is meant to be read after you''ve finished the novel and takes place during the events of the climax. In the annotation, I''ve written a further explanation of why I wrote this piece. Some of you may find it interesting to read this ahead of time; I put it in the annotation, however, as I know others would rather enjoy the story without bias beforehand, then read my thoughts afterward.
', 25, null, 2006, 427815, (select id from series where hardcover_id = 996), '1.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Winds of Winter', 'George R.R. Martin', '0008165165', 'https://assets.hardcover.app/edition/31868656/959a29919a2cf1d09f553f6cd2240651a538b7e4.jpeg', 'The long-awaited sixth novel in George R. R. Martin''s A Song of Ice and Fire fantasy series.
', null, null, null, 427817, (select id from series where hardcover_id = 981), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Doors of Stone', 'Patrick Rothfuss', '0575081449', 'https://assets.hardcover.app/edition/30399253/4012102f186dc02f51e56a849f8d76c6dd8d2dc9.jpeg', 'The third in ''The Kingkiller Chronicle'' series of fantasy novels by Patrick Rothfuss.', 896, null, 2030, 427839, (select id from series where hardcover_id = 988), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadows for Silence in the Forests of Hell', 'Brandon Sanderson, Kate Reading', '1938570081', 'https://assets.hardcover.app/editions/30390603/8436679013636856.jpg', 'Originally appearing in the Dangerous Women anthology and now available as a solo ebook, Shadows for Silence in the Forests of Hell is a chilling novella of the Cosmere, the universe shared by Brandon Sanderson’s Mistborn series and the #1 New York Times bestselling Stormlight Archive. When the familiar and seemingly safe turns lethal, therein danger lies. Amid a forest where the shades of the dead linger all around, every homesteader knows to follow the Simple Rules: “Don’t kindle flame, don’t shed the blood of another, don''t run at night. These things draw shades.” Silence Montane has broken all three rules on more than one occasion. And to protect her family from a murderous gang with high bounties on their heads, Silence will break every rule again, at the risk of becoming a shade herself.', 72, null, 2013, 427840, (select id from series where hardcover_id = 5497), '11') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sixth of the Dusk', 'Brandon Sanderson', '1938570073', 'https://assets.hardcover.app/editions/30390614/2197820789316729.jpg', 'A fascinating new novella in Brandon Sanderson''s Cosmere, the universe shared by his Mistborn series and the #1 New York Times bestselling Stormlight Archive. Sixth of the Dusk, set in a never-before-seen world, showcases a society on the brink of technological change. On the deadly island of Patji, where birds grant people magical talents and predators can sense the thoughts of their prey, a solitary trapper discovers that the island is not the only thing out to kill him. When he begins to see his own corpse at every turn, does this spell danger for his entire culture?', 90, null, 2014, 427846, (select id from series where hardcover_id = 5497), '13') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ninefox Gambit', 'Yoon Ha Lee', '1501916254', 'https://assets.hardcover.app/edition/30448404/e6c499cf03a614f1102e26a76ec2e1f33b888b1a.jpeg', 'Captain Kel Cheris of the hexarchate is disgraced for using unconventional methods in a battle against heretics. Kel Command gives her the opportunity to redeem herself by retaking the Fortress of Scattered Needles, a star fortress that has recently been captured by heretics. Cheris''s career isn''t the only thing at stake. If the fortress falls, the hexarchate itself might be next. Cheris''s best hope is to ally with the undead tactician Shuos Jedao. The good news is that Jedao has never lost a battle, and he may be the only one who can figure out how to successfully besiege the fortress. The bad news is that Jedao went mad in his first life and massacred two armies, one of them his own. As the siege wears on, Cheris must decide how far she can trust Jedao--because she might be his next victim.', 384, null, 2016, 427867, (select id from series where hardcover_id = 983), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Columbus Day', 'Craig Alanson', '8366375358', 'https://assets.hardcover.app/editions/25282254/714549825438253.jpg', 'We were fighting on the wrong side, of a war we couldn''t win. And that was the good news. 

The Ruhar hit us on Columbus Day. There we were, innocently drifting along the cosmos on our little blue marble, like the native Americans in 1492. Over the horizon come ships of a technologically advanced, aggressive culture, and BAM! There go the good old days, when humans only got killed by each other. So, Columbus Day. It fits. 

When the morning sky twinkled again, this time with Kristang starships jumping in to hammer the Ruhar, we thought we were saved. The UN Expeditionary Force hitched a ride on Kristang ships to fight the Ruhar, wherever our new allies thought we could be useful. So, I went from fighting with the US Army in Nigeria, to fighting in space. It was lies, all of it. We shouldn''t even be fighting the Ruhar, they aren''t our enemy, our allies are. 

I''d better start at the beginning....', 305, null, 2016, 427970, (select id from series where hardcover_id = 1086), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Rithmatist', 'Brandon Sanderson, Ben McSweeney', '8466655867', 'https://assets.hardcover.app/external_data/36901832/68117b40a0f4a4b9cf73a410a4de8eb661e1a966.jpeg', 'From #1 New York Times bestselling author Brandon Sanderson: his debut novel for the young adult audience More than anything, Joel wants to be a Rithmatist. Chosen by the Master in a mysterious inception ceremony, Rithmatists have the power to infuse life into two-dimensional figures known as Chalklings. Rithmatists are humanity''s only defense against the Wild Chalklings—merciless creatures that leave mangled corpses in their wake. Having nearly overrun the territory of Nebrask, the Wild Chalklings now threaten all of the American Isles. As the son of a lowly chalkmaker at Armedius Academy, Joel can only watch as Rithmatist students study the magical art that he would do anything to practice. Then students start disappearing—kidnapped from their rooms at night, leaving trails of blood. Assigned to help the professor who is investigating the crimes, Joel and his friend Melody find themselves on the trail of an unexpected discovery—one that will change Rithmatics—and their world—forever. Bestselling author Brandon Sanderson brings his unique brand of epic storytelling to the teen audience with an engrossing tale of danger and suspense—the first of a series. With his trademark skills in world-building, Sanderson has created a magic system that is so inventive and detailed that that readers who appreciate games of strategy and tactics just may want to bring Rithmatics to life in our world. A Kirkus Reviews Best Book of 2013 A New York Times Book Review Notable Children''s Book of 2013', 448, null, 2013, 428036, (select id from series where hardcover_id = 5498), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('How to Stop Time', 'Matt Haig', '1782118640', 'https://assets.hardcover.app/edition/30401482/24fe0b3c-2633-466e-b046-f07e0f4f2bad.jpg', 'Tom Hazard has a dangerous secret. He may look like an ordinary 41-year-old history teacher, but he’s been alive for centuries. From Elizabethan England to Jazz-Age Paris, from New York to the South Seas, Tom has seen it all. As long as he keeps changing his identity, he can stay one step ahead of his past – and stay alive. The only thing he must not do is fall in love. But what if the one thing he can''t have just happens to be the one thing that might save him?', 336, null, 2017, 428213, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Paper Menagerie and Other Stories', 'Ken Liu', '148142436X', 'https://assets.hardcover.app/book_mappings/7333263/cd28a33edacc7b0f4c6fdb8ef54b62a7833343a4.jpeg', 'Featured in the Netflix series Love, Death & Robots Bestselling author Ken Liu selects his multiple award-winning stories for a groundbreaking collection—including a brand-new piece exclusive to this volume. With his debut novel, The Grace of Kings, taking the literary world by storm, Ken Liu now shares his finest short fiction in The Paper Menagerie and Other Stories. This mesmerizing collection features many of Ken’s award-winning and award-finalist stories, including: “The Man Who Ended History: A Documentary” (Finalist for the Hugo, Nebula, and Theodore Sturgeon Awards), “Mono No Aware” (Hugo Award winner), “The Waves” (Nebula Award finalist), “The Bookmaking Habits of Select Species” (Nebula and Sturgeon Award finalists), “All the Flavors” (Nebula Award finalist), “The Litigation Master and the Monkey King” (Nebula Award finalist), and the most awarded story in the genre’s history, “The Paper Menagerie” (The only story to win the Hugo, Nebula, and World Fantasy awards). Insightful and stunning stories that plumb the struggle against history and betrayal of relationships in pivotal moments, this collection showcases one of our greatest and original voices.', 437, null, 2001, 428295, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kingdom of the Wicked', 'Kerri Maniscalco', '6257382785', 'https://assets.hardcover.app/editions/6937699/2818971068231022.jpg', 'Emilia and her twin sister Vittoria are streghe – witches who live secretly among humans, avoiding notice and persecution. One night, Vittoria misses dinner service at the family''s renowned Sicilian restaurant. Emilia soon finds the body of her beloved twin…desecrated beyond belief. Devastated, Emilia sets out to find her sister''s killer and to seek vengeance at any cost-even if it means using dark magic that''s been long forbidden.
 
Then Emilia meets Wrath, one of the Wicked-princes of Hell she has been warned against in tales since she was a child. Wrath claims to be on Emilia''s side, tasked by his master with solving the series of women''s murders on the island. But when it comes to the Wicked, nothing is as it seems…', 372, null, 2020, 428343, (select id from series where hardcover_id = 1211), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hounded', 'Kevin Hearne', '3608125566', 'https://assets.hardcover.app/edition/27980853/14e5617789042bac88831233369a3e1186887f7d.jpeg', 'Two-thousand-year-old druid Atticus O''Sullivan, Granuaile and the wolfhound Oberon race across modern-day Europe to try to escape the clutches of Olympian goddesses Artemis and Diana and the Norse god of mischief, Loki.', 304, null, 2011, 428349, (select id from series where hardcover_id = 1290), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Natural History of Dragons', 'Marie Brennan', '142724233X', 'https://assets.hardcover.app/external_data/27377629/1e2a707c13b37465b422627731f93122256aa74d.jpeg', 'Marie Brennan begins a thrilling new fantasy series in A Natural History of Dragons, combining adventure with the inquisitive spirit of the Victorian Age. You, dear reader, continue at your own risk. It is not for the faint of heart—no more so than the study of dragons itself. But such study offers rewards beyond compare: to stand in a dragon''s presence, even for the briefest of moments—even at the risk of one''s life—is a delight that, once experienced, can never be forgotten. . . . All the world, from Scirland to the farthest reaches of Eriga, know Isabella, Lady Trent, to be the world''s preeminent dragon naturalist. She is the remarkable woman who brought the study of dragons out of the misty shadows of myth and misunderstanding into the clear light of modern science. But before she became the illustrious figure we know today, there was a bookish young woman whose passion for learning, natural history, and, yes, dragons defied the stifling conventions of her day. Here at last, in her own words, is the true story of a pioneering spirit who risked her reputation, her prospects, and her fragile flesh and bone to satisfy her scientific curiosity; of how she sought true love and happiness despite her lamentable eccentricities; and of her thrilling expedition to the perilous mountains of Vystrana, where she made the first of many historic discoveries that would change the world forever. "Saturated with the joy and urgency of discovery and scientific curiosity."—Publishers Weekly (starred review) on A Natural History of Dragons An NPR Best Book of 2013 The Lady Trent Memoirs 1. A Natural History of Dragons 2. The Tropic of Serpents 3. Voyage of the Basilisk 4. In the Labyrinth of Drakes 5. Within the Sanctuary of Wings', 334, null, 2013, 428391, (select id from series where hardcover_id = 4680), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Clockwork Princess', 'Cassandra Clare', '1406356891', 'https://assets.hardcover.app/external_data/31969536/42b2aa3ffaa6b3e659cc09e598572de57a1501e4.jpeg', 'A net of shadows begins to tighten around the Shadowhunters of the London Institute. Mortmain plans to use his Infernal Devices, an army of pitiless automatons, to destroy the Shadowhunters. He needs only one last item to complete his plan: he needs Tessa Gray.

Charlotte Branwell, head of the London Institute, is desperate to find Mortmain before he strikes. But when Mortmain abducts Tessa, the boys who lay equal claim to her heart, Will and Jem, will do anything to save her. As those who love Tessa rally to rescue her from Mortmain’s clutches, Tessa realizes that the only person who can save her is herself. But can a single girl, even one who can command the power of angels, face down an entire army?

The tangled threads of love and loss intertwine as the Shadowhunters are pushed to the very brink of destruction in the breathtaking conclusion to the Infernal Devices trilogy.', 568, null, 2013, 428619, (select id from series where hardcover_id = 5756), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Middlegame', 'Seanan McGuire, Amber Benson', '1250234204', 'https://assets.hardcover.app/external_data/4076899/4d7a9d2382a04306c8147bfd9b9aa49e1da7c090.jpeg', 'A HUGO AWARD FINALIST! WINNER OF THE LOCUS AWARD FOR BEST FANTASY NOVEL, 2020! A Pick on the 2020 RUSA Reading List! New York Times bestselling and Alex, Nebula, and Hugo-Award-winning author Seanan McGuire introduces readers to a world of amoral alchemy, shadowy organizations, and impossible cities in the standalone fantasy, Middlegame. Meet Roger. Skilled with words, languages come easily to him. He instinctively understands how the world works through the power of story. Meet Dodger, his twin. Numbers are her world, her obsession, her everything. All she understands, she does so through the power of math. Roger and Dodger aren’t exactly human, though they don’t realise it. They aren’t exactly gods, either. Not entirely. Not yet. Meet Reed, skilled in the alchemical arts like his progenitor before him. Reed created Dodger and her brother. He’s not their father. Not quite. But he has a plan: to raise the twins to the highest power, to ascend with them and claim their authority as his own. Godhood is attainable. Pray it isn’t attained. A USA Today Bestseller, and named as one of Paste Magazine''s 30 Best Fantasy Novels of the Decade! At the Publisher''s request, this title is being sold without Digital Rights Management Software (DRM) applied.', null, null, 2019, 428651, (select id from series where hardcover_id = 36159), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Monster Calls', 'Patrick Ness, Jim Kay, Siobhan Dowd', '9638883995', 'https://assets.hardcover.app/external_data/3315208/8b6f4fae3ecff392f47312dde2a0cd1fd8fdb177.jpeg', 'A brilliant, graphic novel written by young but promising Patrick Ness. This is the story about 13 year old Conor and his mother who is dying of cancer. Conor has to face the cruelty of real life and learn to let his close and dearest go. When no human can help him Monster appears...', 226, null, 2011, 428654, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('To Kill a Kingdom', 'Alexandra Christo, Stephanie Willis, Jacob York', '8494799754', 'https://assets.hardcover.app/editions/23963845/6744898258842138-34499221.jpg', 'Princess Lira is siren royalty and the most lethal of them all. With the hearts of seventeen princes in her collection, she is revered across the sea. Until a twist of fate forces her to kill one of her own. To punish her daughter, the Sea Queen transforms Lira into the one thing they loathe most—a human. Robbed of her song, Lira has until the winter solstice to deliver Prince Elian’s heart to the Sea Queen or remain a human forever.

The ocean is the only place Prince Elian calls home, even though he is heir to the most powerful kingdom in the world. Hunting sirens is more than an unsavory hobby—it’s his calling. When he rescues a drowning woman in the ocean, she’s more than what she appears. She promises to help him find the key to destroying all of sirenkind for good—But can he trust her? And just how many deals will Elian have to barter to eliminate mankind’s greatest enemy?', 352, null, 2018, 428681, (select id from series where hardcover_id = 41464), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('King of Scars', 'Leigh Bardugo', '1510106294', 'https://assets.hardcover.app/edition/30889737/85e353d4c400e72604030228ddce5e3b0366063f.jpeg', 'Face your demons...or feed them. The dashing young king, Nikolai Lantsov, has always had a gift for the impossible. No one knows what he endured in his country’s bloody civil war—and he intends to keep it that way. Now, as enemies gather at his weakened borders, Nikolai must find a way to refill Ravka’s coffers, forge new alliances, and stop a rising threat to the once-great Grisha Army.

Yet with every day a dark magic within him grows stronger, threatening to destroy all he has built. With the help of a young monk and a legendary Grisha general, Nikolai will journey to the places in Ravka where the deepest magic survives to vanquish the terrible legacy inside him. He will risk everything to save his country and himself. But some secrets aren’t meant to stay buried—and some wounds aren’t meant to heal.', 514, null, 2014, 428729, (select id from series where hardcover_id = 5591), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('This Savage Song', 'V. E. Schwab', '6067631024', 'https://assets.hardcover.app/external_data/60484930/cf8dba35851aec42b248e46412bc1b7776d469c7.jpeg', 'Kate Harker and August Flynn''s families rule opposite ends of Verity, a grisly metropolis where violent acts summon real monsters: bloodsucking Malchai; clawing Corsai; and soul-stealing Sunai. The truce that keeps the Families at peace is crumbling, and August is sent to spy on Kate. But when Harker''s men try to kill her and pin it on the Flynns, August and Kate find themselves running from both sides, in a city where monsters are real.', 469, null, 2016, 428733, (select id from series where hardcover_id = 1205), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Serpent & Dove', 'Shelby Mahurin', '6178248865', 'https://assets.hardcover.app/editions/30399857/6332808685139415.jpg', 'Book one of a stunning fantasy trilogy, this tale of witchcraft and forbidden love is perfect for fans of Kendare Blake and Sara Holland.

Two years ago, Louise le Blanc fled her coven and took shelter in the city of Cesarine, forsaking all magic and living off whatever she could steal. There, witches like Lou are hunted. They are feared. And they are burned.

As a huntsman of the Church, Reid Diggory has lived his life by one principle: Thou shalt not suffer a witch to live. But when Lou pulls a wicked stunt, the two are forced into an impossible situation—marriage.

Lou, unable to ignore her growing feelings, yet powerless to change what she is, must make a choice. And love makes fools of us all.', 519, null, 2019, 428738, (select id from series where hardcover_id = 5866), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Glass Sword', 'Victoria Aveyard', '201319319X', 'https://assets.hardcover.app/edition/26561543/2836721b-2687-4953-94d0-3af1da050475.jpg', 'in this science fiction, norta is separated by blood. red and silver, silvers being the rich and higher in the society with an ability that makes life much easier. while reds below a servant''s life, and much poorer.
           mare barrow a red blood. somehow finds herself In the scarlet guard. a group of red bloods rebelling against the royal family and other silvers. when mare discovers her ability she is shocked. in this sequel. mare finds as many new bloods as possible to create an army to rebel against the silvers.
       allwhile keeping her relationship with the exiled prince, Calore afloat. she must run through prison. kill.and hardest of them all stay away from king Maven.', 448, null, 2016, 428754, (select id from series where hardcover_id = 1204), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Into the Drowning Deep', 'Mira Grant', '0356508102', 'https://assets.hardcover.app/edition/30854121/e44217fb-6c27-473e-8c7b-92af2ba318a6.jpg', 'But some are deadly. . .

Seven years ago the Atargatis set off on a voyage to the Mariana Trench to film a mockumentary bringing to life ancient sea creatures of legend. It was lost at sea with all hands. Some have called it a hoax; others have called it a tragedy.

Now a new crew has been assembled. But this time they''re not out to entertain. Some seek to validate their life''s work. Some seek the greatest hunt of all. Some seek the truth. But for the ambitious young scientist Victoria Stewart this is a voyage to uncover the fate of the sister she lost.

Whatever the truth may be, it will only be found below the waves.

But the secrets of the deep come with a price.', 448, null, 2017, 428772, (select id from series where hardcover_id = 5870), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bone Shard Daughter', 'Andrea Stewart', '154910733X', 'https://assets.hardcover.app/edition/17587566/16f7a76e5092c83f54f1ae3e47a309fec944821c.jpeg', '"One of the best debut fantasy novels of the year." — BuzzFeed News
"An amazing start to a new trilogy." — Culturess
"It grabs you by the heart and the throat from the first pages and doesn''t let go." — Sarah J. Maas

The emperor''s reign has lasted for decades, his mastery of bone shard magic powering the animal-like constructs that maintain law and order. But now his rule is failing, and revolution is sweeping across the Empire''s many islands.

Lin is the emperor''s daughter and spends her days trapped in a palace of locked doors and dark secrets. When her father refuses to recognise her as heir to the throne, she vows to prove her worth by mastering the forbidden art of bone shard magic.

Yet such power carries a great cost, and when the revolution reaches the gates of the palace, Lin must decide how far she is willing to go to claim her birthright – and save her people.', 496, null, 2020, 428780, (select id from series where hardcover_id = 1221), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Toll', 'Neal Shusterman', '8024272709', 'https://assets.hardcover.app/edition/11662914/12456258-L.jpg', 'In the highly anticipated finale to the New York Times bestselling trilogy, dictators, prophets, and tensions rise. In a world that’s conquered death, will humanity finally be torn asunder by the immortal beings it created?

Citra and Rowan have disappeared. Endura is gone. It seems like nothing stands between Scythe Goddard and absolute dominion over the world scythedom. With the silence of the Thunderhead and the reverberations of the Great Resonance still shaking the earth to its core, the question remains: Is there anyone left who can stop him?

The answer lies in the Tone, the Toll, and the Thunder.', 640, null, 2019, 428944, (select id from series where hardcover_id = 5557), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('These Violent Delights', 'Chloe Gong', '8076615232', 'https://assets.hardcover.app/edition/1032820/51a0f2fd-a3d9-4a91-ae2c-c9369c5170d1.jpg', '"A blood feud between two gangs runs the streets red, leaving the city helpless in the grip of chaos. At the heart of it all is eighteen-year-old Juliette Cai, a former flapper who has returned to assume her role as the proud heir of the Scarlet Gang—a network of criminals far above the law. Their only rivals in power are the White Flowers, who have fought the Scarlets for generations. And behind every move is their heir, Roma Montagov, Juliette’s first love…and first betrayal.

But when gangsters on both sides show signs of instability culminating in clawing their own throats out, the people start to whisper. Of a contagion, a madness. Of a monster in the shadows. As the deaths stack up, Juliette and Roma must set their guns—and grudges—aside and work together, for if they can’t stop this mayhem, then there will be no city left for either to rule."-- Provided by Amazon', 449, null, 2020, 429024, (select id from series where hardcover_id = 1383), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sorcery of Thorns', 'Margaret  Rogerson', '1534451722', 'https://assets.hardcover.app/edition/25264632/0e33af4a38368017f13977cab3f9c550d961f6b5.jpeg', 'From the New York Times bestselling author of An Enchantment of Ravens comes an “enthralling adventure” (Kirkus Reviews, starred review) about an apprentice at a magical library who must battle a powerful sorcerer to save her kingdom.

All sorcerers are evil. Elisabeth has known that as long as she has known anything. Raised as a foundling in one of Austermeer’s Great Libraries, Elisabeth has grown up among the tools of sorcery—magical grimoires that whisper on shelves and rattle beneath iron chains. If provoked, they transform into grotesque monsters of ink and leather.

Then an act of sabotage releases the library’s most dangerous grimoire, and Elisabeth is implicated in the crime. With no one to turn to but her sworn enemy, the sorcerer Nathaniel Thorn, and his mysterious demonic servant, she finds herself entangled in a centuries-old conspiracy. Not only could the Great Libraries go up in flames, but the world along with them.

As her alliance with Nathaniel grows stronger, Elisabeth starts to question everything she’s been taught—about sorcerers, about the libraries she loves, even about herself. For Elisabeth has a power she has never guessed, and a future she could never have imagined.', 464, null, 2019, 429034, (select id from series where hardcover_id = 20081), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Jasmine Throne', 'Tasha Suri', '1549138758', 'https://assets.hardcover.app/external_data/360034/40e6b2d0c35c0a33b46231276a3cdea30bad6aad.jpeg', 'Imprisoned by her dictator brother, Malini spends her days in isolation in the Hirana: an ancient temple that was once the source of the powerful, magical deathless waters — but is now little more than a decaying ruin.

Priya is a maidservant, one among several who make the treacherous journey to the top of the Hirana every night to clean Malini’s chambers. She is happy to be an anonymous drudge, so long as it keeps anyone from guessing the dangerous secret she hides.

But when Malini accidentally bears witness to Priya’s true nature, their destinies become irrevocably tangled. One is a vengeful princess seeking to depose her brother from his throne. The other is a priestess seeking to find her family. Together, they will change the fate of an empire.', 576, null, 2021, 429097, (select id from series where hardcover_id = 30982), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hawthorne Legacy', 'Jennifer Lynn Barnes', '6555670576', 'https://assets.hardcover.app/editions/30401187/2712087599578475-91Y0MgtvzZL._SL1500_.jpg', 'The Inheritance Games ended with a bombshell, and now heiress Avery Grambs has to pick up the pieces and find the man who might hold the answers to all of her questions—including why Tobias Hawthorne left his entire fortune to Avery, a virtual stranger, rather than to his own daughters or grandsons. 

Thanks to a DNA test, Avery knows she’s not a Hawthorne by blood, but clues pile up hinting at a deeper connection to the family than she had ever imagined. As the mystery grows and the plot thickens, Grayson and Jameson, two of the enigmatic and magnetic Hawthorne grandsons, continue to pull Avery in different directions. And there are threats lurking around every corner, as adversaries emerge who will stop at nothing to see Avery out of the picture—by any means necessary. 

With nonstop action, aspirational jet-setting, Knives Out-like family intrigue, swoonworthy romance, and billions of dollars hanging in the balance, The Hawthorne Legacy will thrill Jennifer Lynn Barnes fans and new readers alike.', 354, null, 2021, 429100, (select id from series where hardcover_id = 5593), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Crying of Lot 49', 'Thomas Pynchon', '0397004184', 'https://assets.hardcover.app/edition/3464110/f6830673d71b3c2bf0784f80966bd1f32d608d8e.jpeg', 'When her ex-lover, wealthy real-estate tycoon Pierce Inverarity, dies and designates her the coexecutor of his estate, California housewife Oedipa Maas is thrust into a paranoid mystery of metaphors, symbols, and the United States Postal Service. Traveling across Southern California, she meets some extremely interesting characters, and attains a not inconsiderable amount of self-knowledge.', 152, null, 1965, 429610, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Too Like the Lightning', 'Ada Palmer', '9798200957576', 'https://assets.hardcover.app/edition/32534066/8bb63354-fd1c-4c39-a854-8db6b4086467.jpg', 'Mycroft Canner is a convict. For his crimes he is required, as is the custom of the 25th century, to wander the world being as useful as he can to all he meets. Carlyle Foster is a sensayer—a spiritual counselor in a world that has outlawed the public practice of religion, but which also knows that the inner lives of humans cannot be wished away.

The world into which Mycroft and Carlyle have been born is as strange to our 21st-century eyes as ours would be to a native of the 1500s. It is a hard-won utopia built on technologically-generated abundance, and also on complex and mandatory systems of labelling all public writing and speech. What seem to us normal gender distinctions are now distinctly taboo in most social situations. And most of the world''s population is affiliated with globe-girdling clans of the like-minded, whose endless economic and cultural competition is carefully managed by central planners of inestimable subtlety. To us it seems like a mad combination of heaven and hell. To them, it seems like normal life.

And in this world, Mycroft and Carlyle have stumbled on the wild card that may destablize the system: the boy Bridger, who can effortlessly make his wishes come true. Who can, it would seem, bring inanimate objects to life..', 433, null, 2016, 430672, (select id from series where hardcover_id = 1344), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gods of Risk', 'James S. A. Corey, Erik Davies', '1549165623', 'https://assets.hardcover.app/edition/8582300/7992542-L.jpg', 'A novella set in the hard-scrabble world of James S. A. Corey''s NYT-bestselling Expanse series, Gods of Risk tells the story of Bobbie Draper following the events of Caliban''s War. This story will be available in the complete Expanse story collection, Memory’s Legion. HUGO AWARD WINNER FOR BEST SERIES As tension between Mars and Earth mounts, and terrorism plagues the Martian city of Londres Nova, sixteen-year-old David Draper is fighting his own lonely war. A gifted chemist vying for a place at the university, David leads a secret life as a manufacturer for a ruthless drug dealer. When his friend Leelee goes missing, leaving signs of the dealer''s involvement, David takes it upon himself to save her. But first he must shake his aunt Bobbie Draper, an ex-marine who has been set adrift in her own life after a mysterious series of events nobody is talking about. The Expanse Leviathan Wakes Caliban''s War Abaddon''s Gate Cibola Burn Nemesis Games Babylon''s Ashes Persepolis Rising Tiamat''s Wrath ​Leviathan Falls Memory''s Legion The Expanse Short Fiction Drive The Butcher of Anderson Station Gods of Risk The Churn The Vital Abyss Strange Dogs Auberon The Sins of Our Fathers', null, null, 2012, 430926, (select id from series where hardcover_id = 1026), '2.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Butcher of Anderson Station', 'James S. A. Corey', '1549165674', 'https://assets.hardcover.app/external_data/59520595/b0bc833cdc4121bdb8db78d864a0628bd52323a5.jpeg', 'A novelette set in the hard-scrabble world of James S. A. Corey''s NYT-bestselling Expanse series, The Butcher of Anderson Station deepens the story of Colonel Fred Johnson''s past as seen on the fifth episode of Season 1 of The Expanse. Now a Prime Original series. This story will be available in the complete Expanse story collection, Memory’s Legion. HUGO AWARD WINNER FOR BEST SERIES A new story set in the world of the Expanse. One day, Colonel Fred Johnson will be hailed as a hero to the system. One day, he will meet a desperate man in possession of a stolen spaceship and a deadly secret and extend a hand of friendship. But long before he became the leader of the Outer Planets Alliance, Fred Johnson had a very different name. The Butcher of Anderson Station. This is his story. The Expanse Leviathan Wakes Caliban''s War Abaddon''s Gate Cibola Burn Nemesis Games Babylon''s Ashes Persepolis Rising Tiamat''s Wrath ​Leviathan Falls Memory''s Legion The Expanse Short Fiction Drive The Butcher of Anderson Station Gods of Risk The Churn The Vital Abyss Strange Dogs Auberon The Sins of Our Fathers', 40, null, 2011, 431000, (select id from series where hardcover_id = 1026), '1.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Churn', 'James S. A. Corey', '1549165658', 'https://assets.hardcover.app/external_data/61397718/11d2ad3f225d31e3aa0442a9d201edc10d8da265.jpeg', 'A novella set in the hard-scrabble world of James S. A. Corey''s NYT-bestselling Expanse series, The Churn takes the bestselling sci-fi series to the dark world of organized crime, drugs, secrets, and murder that shaped the Rocinante''s mechanic, Amos. Now a Prime Original series. This story will be available in the complete Expanse story collection, Memory’s Legion. HUGO AWARD WINNER FOR BEST SERIES Before his trip to the stars, before the Rocinante, Timmy was confined to a Baltimore where crime paid you or killed you. Unless the authorities got to you first. On a future Earth beset by overpopulation, pollution, and poverty, people do what they must to survive. The Churn follows a crime boss named Burton as his organization is threatened by a new private security force tasked with cleaning up the city. When the police start cracking down, Burton and his footsoldiers-loyal lieutenant Erich, former prostitute Lydia, and young enforcer Timmy-become increasingly desperate to find a way out. The Expanse Leviathan Wakes Caliban''s War Abaddon''s Gate Cibola Burn Nemesis Games Babylon''s Ashes Persepolis Rising Tiamat''s Wrath ​Leviathan Falls Memory''s Legion The Expanse Short Fiction Drive The Butcher of Anderson Station Gods of Risk The Churn The Vital Abyss Strange Dogs Auberon The Sins of Our Fathers', 75, null, 2014, 431008, (select id from series where hardcover_id = 1026), '3.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Vital Abyss', 'James S. A. Corey, Jefferson Mays', '1478964243', 'https://assets.hardcover.app/external_data/40698064/2fd5a0dd0650dbaab1d7557ce081bdf77358d7af.jpeg', 'A novella set in the hard-scrabble world of James S. A. Corey''s NYT-bestselling Expanse series, The Vital Abyss is the secret history of the cataclysmic events that occurred on Eros station, and the revelation of what came after. . . Now a Prime Original series. This story will be available in the complete Expanse story collection, Memory’s Legion. HUGO AWARD WINNER FOR BEST SERIES Somewhere in the vast expanse of space, a group of prisoners lives in permanent captivity. The only company they have is each other and the Belters who guard them. The only stories they know are the triumphs and crimes that brought them there. The only future they see is an empty life in an enormous room. And then the man from Mars came along . . . The Expanse Leviathan Wakes Caliban''s War Abaddon''s Gate Cibola Burn Nemesis Games Babylon''s Ashes Persepolis Rising Tiamat''s Wrath ​Leviathan Falls Memory''s Legion The Expanse Short Fiction Drive The Butcher of Anderson Station Gods of Risk The Churn The Vital Abyss Strange Dogs Auberon The Sins of Our Fathers', null, null, 2015, 431012, (select id from series where hardcover_id = 1026), '5.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Strange Dogs', 'James S. A. Corey', '1405539011', 'https://assets.hardcover.app/external_data/59012361/38502a50345b7b006d86326bb024f1521a8be345.jpeg', 'Strange Dogs is a novella that expands the world of James S. A. Corey''s New York Times bestselling Expanse series - now a Prime Original TV series. Like many before them, Cara and her family ventured through the gates as scientists and researchers, driven to carve out a new life and uncover the endless possibilities of the unexplored alien worlds now within reach. But soon the soldiers followed and under this new order Cara makes a discovery that will change everything. The Expanse series: Leviathan Wakes Caliban''s War Abaddon''s Gate Cibola Burn Nemesis Games Babylon''s Ashes Persepolis Rising Tiamat''s Wrath Praise for the Expanse: ''The science fictional equivalent of A Song of Ice and Fire'' NPR Books ''As close as you''ll get to a Hollywood blockbuster in book form'' io9.com ''Great characters, excellent dialogue, memorable fights'' wired.com ''High adventure equalling the best space opera has to offer, cutting-edge technology and a group of unforgettable characters . . . Perhaps one of the best tales the genre has yet to produce'' Library Journal ''This is the future the way it''s supposed to be'' Wall Street Journal ''Tense and thrilling'' SciFiNow', 95, null, 2017, 431017, (select id from series where hardcover_id = 1026), '6.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('If on a Winter''s Night a Traveler', 'Italo Calvino', '0919630456', 'https://assets.hardcover.app/external_data/28442196/dcaa1fdb6320477cbcf916791394256e6b63f2ec.jpeg', 'Introduction by Peter Washington; Translation by William Weaver Italo Calvino’s masterpiece combines a love story and a detective story into an exhilarating allegory of reading, in which the reader of the book becomes the book’s central character. Based on a witty analogy between the reader’s desire to finish the story and the lover’s desire to consummate his or her passion, IF ON A WINTER’S NIGHT A TRAVELER is the tale of two bemused readers whose attempts to reach the end of the same book—IF ON A WINTER’S NIGHT A TRAVELER, by Italo Calvino, of course—are constantly and comically frustrated. In between chasing missing chapters of the book, the hapless readers tangle with an international conspiracy, a rogue translator, an elusive novelist, a disintegrating publishing house, and several oppressive governments. The result is a literary labyrinth of storylines that interrupt one another—an Arabian Nights of the postmodern age.', 272, null, 1979, 431145, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The House of the Spirits', 'Isabel Allende', '8447306615', 'https://assets.hardcover.app/external_data/45044277/b73ead53002f98144d363439af732ff4623e7e3f.jpeg', 'The astonishing debut of a gifted storyteller, The House of the Spirits is both a symbolic family saga and the story of an unnamed Latin American country’s turbulent history. Isabel Allende constructs a spirit-ridden world and fills it with colorful and all-too-human inhabitants including Esteban, the patriarch, a volatile and proud man whose lust for land is legendary and who is haunted by tyrannical passion for the wife he can never completely posses; Clara, the matriarch, elusive and mysterious, who foretells family tragedy and shapes the fortunes of the house and the Truebas; Blanca, their daughter, soft-spoken yet rebellious, whose shocking love for the son of her father’s foreman fuels Esteban’s everlasting contempt, even as it produces the grandchild he adores; and Alba, the fruit of Blanca’s forbidden love, a luminous beauty and a fiery and willful woman.

The Trueba family’s passions, struggles, and secrets span three generations and a century of violent change, culminating in a crisis that brings the proud and tyrannical patriarch and his beloved granddaughter to opposite sides of the barricades. Against a backdrop of revolution and counterrevolution, Allende brings to life a family whose private bonds of love and hatred are more complex and enduring than the political allegiances that set them at odds.', 481, null, 1982, 431234, (select id from series where hardcover_id = 5906), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Touch of Darkness', 'Scarlett  St. Clair', '8832233789', 'https://assets.hardcover.app/edition/30536977/f9f9820d14158c3bb7e6381663eb5bb5d0638f56.jpeg', '"The truth is, since she was a little girl, flowers have shriveled at her touch. After moving to New Athens, she hopes to lead an unassuming life disguised as a mortal journalist.

Hades, God of the Dead, has built a gambling empire in the mortal world and his favorite bets are rumored to be impossible.

After a chance encounter with Hades, Persephone finds herself in a contract with the God of the Dead and the terms are impossible: Persephone must create life in the Underworld or lose her freedom forever.

The bet does more than expose Persephone''s failure as a goddess, however. As she struggles to sow the seeds of her freedom, love for the God of the Dead grows - and it''s forbidden."-- Provided by Amazon', 400, null, 2019, 431653, (select id from series where hardcover_id = 79906), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Rook', 'Daniel O''Malley', '0316098809', 'https://assets.hardcover.app/edition/7867780/75b1d15c105dfdb51f95bba9f4a4a4a7cb6f181f.jpeg', 'Myfanwy Thomas awakes in a London park surrounded by dead bodies. With her memory gone, her only hope of survival is to trust the instructions left in her pocket by her former self. She quickly learns that she is a Rook, a high-level operative in a secret agency that protects the world from supernatural threats. But there is a mole inside the organization and this person wants her dead. As Myfanwy battles to save herself, she encounters a person with four bodies, a woman who can enter her dreams, children transformed into deadly fighters, and an unimaginably vast conspiracy. Suspenseful and hilarious, THE ROOK is an outrageously inventive debut for readers who like their espionage with a dollop of purple slime.', 512, null, 2001, 431967, (select id from series where hardcover_id = 1665), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tigana', 'Guy Gavriel Kay', '0007352239', 'https://assets.hardcover.app/edition/30560092/42579dc4-aebb-445f-9818-95835f12ae7e.jpeg', 'Tigana is the magical story of a beleaguered land struggling to be free. It is the tale of a people so cursed by the black sorcery of a cruel despotic king that even the name of their once-beautiful homeland cannot be spoken or remembered... But years after the devastation, a handful of courageous men and women embark upon a dangerous crusade to overthrow their conquerors and bring back to the dark world the brilliance of a long-lost name...Tigana. Against the magnificently rendered background of a world both sensuous and barbaric, this sweeping epic of a passionate people pursuing their dream is breathtaking in its vision, changing forever the boundaries of fantasy fiction.', 692, null, 1990, 432215, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Black Leopard, Red Wolf', 'Marlon James', '0735220182', 'https://assets.hardcover.app/book_mappings/7332873/48dd119d91d4e7404784512425a69a73fd5e0268.jpeg', 'In the stunning first novel in Marlon James''s Dark Star trilogy, myth, fantasy, and history come together to explore what happens when a mercenary is hired to find a missing child. 

Tracker is known far and wide for his skills as a hunter: "He has a nose," people say. Engaged to track down a mysterious boy who disappeared three years earlier, Tracker breaks his own rule of always working alone when he finds himself part of a group that comes together to search for the boy. The band is a hodgepodge, full of unusual characters with secrets of their own, including a shape-shifting man-animal known as Leopard. 

As Tracker follows the boy''s scent--from one ancient city to another; into dense forests and across deep rivers--he and the band are set upon by creatures intent on destroying them. As he struggles to survive, Tracker starts to wonder: Who, really, is this boy? Why has he been missing for so long? Why do so many people want to keep Tracker from finding him? And perhaps the most important questions of all: Who is telling the truth, and who is lying? 

Drawing from African history and mythology and his own rich imagination, Marlon James has written a novel unlike anything that''s come before it: a saga of breathtaking adventure that''s also an ambitious, involving read. Defying categorization and full of unforgettable characters, Black Leopard, Red Wolf is both surprising and profound as it explores the fundamentals of truth, the limits of power, and our need to understand them both.', 620, null, 2019, 432346, (select id from series where hardcover_id = 5600), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nothing to See Here', 'Kevin Wilson', '0062913468', 'https://assets.hardcover.app/edition/30402428/6149d645-89c4-4b14-8d6a-37bf56fa28cc.jpg', 'Lillian and Madison were unlikely roommates and yet inseparable friends at their elite boarding school. But then Lillian had to leave the school unexpectedly in the wake of a scandal and they’ve barely spoken since. Until now, when Lillian gets a letter from Madison pleading for her help.

Madison’s twin stepkids are moving in with her family and she wants Lillian to be their caretaker. However, there’s a catch: the twins spontaneously combust when they get agitated, flames igniting from their skin in a startling but beautiful way. Lillian is convinced Madison is pulling her leg, but it’s the truth.

Thinking of her dead-end life at home, the life that has consistently disappointed her, Lillian, a truly unforgettable and witty protagonist, figures she has nothing to lose. Over the course of one humid, demanding summer, Lillian and the twins learn to trust each other—and stay cool—while also staying out of the way of Madison’s buttoned-up politician husband. Surprised by her own ingenuity yet unused to the intense feelings of protectiveness she feels for them, Lillian ultimately begins to accept that she needs these strange children as much as they need her—urgently and fiercely. Couldn’t this be the start of the amazing life she’d always hoped for?

With white-hot wit and a big, tender heart, Kevin Wilson has written his best book yet—a most unusual story of parental love and the power of a found family.', 272, null, 2019, 432394, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last House on Needless Street', 'Catriona Ward', '1788168488', 'https://assets.hardcover.app/external_data/50292102/41f6f8404e2e4c3010bb93acb43f4fcb408f2d2d.jpeg', 'In a boarded-up house on a dead-end street at the edge of the wild Washington woods lives a family of three.

A teenage girl who isn’t allowed outside, not after last time.
A man who drinks alone in front of his TV, trying to ignore the gaps in his memory.
And a house cat who loves napping and reading the Bible.

An unspeakable secret binds them together, but when a new neighbor moves in next door, what is buried out among the birch trees may come back to haunt them all.', 342, null, 2021, 432642, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Home Before Dark', 'Riley Sager', '1524745189', 'https://assets.hardcover.app/edition/8248273/51c682711c7d7729505fc82c15e0dc02a8f5199e.jpeg', 'Twenty-five years ago, Maggie Holt and her parents moved into Baneberry Hall, a rambling Victorian estate in the Vermont woods. Three weeks later they fled in the dead of night, an ordeal her father recounted in a memoir called House of Horrors. His story of supernatural happenings and malevolent spirits became a worldwide phenomenon, rivaling The Amityville Horror in popularity—and skepticism.

Maggie was too young to remember any of the horrific events that supposedly took place, and as an adult she doesn’t believe a word of her father’s claims. Ghosts, after all, don’t exist. When she inherits Baneberry Hall after his death and returns to renovate the place and sell it, her homecoming is anything but warm. The locals aren’t thrilled that their small town has been made infamous, and human characters with starring roles in House of Horrors are waiting in the shadows.
 
Even more unnerving is Baneberry Hall itself—a place where unsettling whispers of the past lurk around every corner. And as Maggie starts to experience strange occurrences ripped from the pages of her father’s book, the truth she uncovers about the house’s dark history will challenge everything she believes.', 413, null, 2020, 432651, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Republic of Thieves', 'Scott Lynch', '9791028116194', 'https://assets.hardcover.app/edition/30479556/4f36e7cc93e9691957a27559b3ea5e84b82baebe.jpeg', 'With what should have been the greatest heist of their career gone spectacularly sour, Locke and his trusted partner, Jean, have barely escaped with their lives. Or at least Jean has. But Locke is slowly succumbing to a deadly poison that no alchemist or physiker can cure. Yet just as the end is near, a mysterious Bondsmage offers Locke an opportunity that will either save him or finish him off once and for all.
 
Magi political elections are imminent, and the factions are in need of a pawn. If Locke agrees to play the role, sorcery will be used to purge the venom from his body—though the process will be so excruciating he may well wish for death. Locke is opposed, but two factors cause his will to crumble: Jean’s imploring—and the Bondsmage’s mention of a woman from Locke’s past: Sabetha. She is the love of his life, his equal in skill and wit, and now, his greatest rival.
 
Locke was smitten with Sabetha from his first glimpse of her as a young fellow orphan and thief-in-training. But after a tumultuous courtship, Sabetha broke away. Now they will reunite in yet another clash of wills. For faced with his one and only match in both love and trickery, Locke must choose whether to fight Sabetha—or to woo her. It is a decision on which both their lives may depend.', 722, null, 2010, 433314, (select id from series where hardcover_id = 1128), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fifty Shades of Grey', 'E.L. James', '1780891261', 'https://assets.hardcover.app/edition/15439076/402718fa15330d230303147a6a288b339056e762.jpeg', 'When literature student Anastasia Steele goes to interview young entrepreneur Christian Grey, she encounters a man who is beautiful, brilliant, and intimidating. The unworldly, innocent Ana is startled to realize she wants this man and, despite his enigmatic reserve, finds she is desperate to get close to him. Unable to resist Ana’s quiet beauty, wit, and independent spirit, Grey admits he wants her, too—but on his own terms.
 
Shocked yet thrilled by Grey’s singular erotic tastes, Ana hesitates. For all the trappings of success—his multinational businesses, his vast wealth, his loving family—Grey is a man tormented by demons and consumed by the need to control. When the couple embarks on a daring, passionately physical affair, Ana discovers Christian Grey’s secrets and explores her own dark desires.

Erotic, amusing, and deeply moving, the Fifty Shades Trilogy is a tale that will obsess you, possess you, and stay with you forever.

This book is intended for mature audiences.', 514, null, 2010, 433359, (select id from series where hardcover_id = 5919), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Defiant', 'Brandon Sanderson', '8419260010', 'https://assets.hardcover.app/editions/31313377/6789842555978129.jpg', 'From the #1 New York Times bestselling author Brandon Sanderson comes the final book in an epic series about a girl who will travel beyond the stars to save the world she loves from destruction.

Spensa made it out of the Nowhere, but what she saw in the space between the stars has changed her forever. She came face to face with the Delvers, and finally got answers to the questions she''s had about her own strange Cytonic gifts.

The Superiority didn''t stop in it''s fight for galactic dominance while she was gone, though. Spensa''s team, Skyward Flight, was able to hold Winzik off, and even collect allies to help with the cause, but it''s only a matter of time until humanity—and the rest of the galaxy—falls.

Defeating them will require all the knowledge Spensa gathered while in the Nowhere. But being Cytonic is more complicated than she ever could have imagined. Now, Spensa must ask herself: how far is she willing to go for victory, if it means losing herself—and her friends—in the process.

The final book in the Skyward series will free humanity, or see it fall forever.', 432, null, 2023, 434340, (select id from series where hardcover_id = 999), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Five People You Meet in Heaven', 'Mitch Albom', '0786868716', 'https://assets.hardcover.app/external_data/61214732/82632ab2d01e90e5e49be6fb752e284c337f966b.jpeg', 'The Five People You Meet In Heaven is a 2003 novel by Mitch Albom. It follows the life and death of a ride mechanic named Eddie who is killed in an amusement park accident and sent to heaven, where he encounters five people who had a significant impact on him while he was alive. It was published by Hyperion and remained on the New York Times Best Seller list for 95 weeks.', 208, null, 2003, 434758, (select id from series where hardcover_id = 5928), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Only Good Indians', 'Stephen Graham Jones', '1797105574', 'https://assets.hardcover.app/editions/30402943/6917352740068947.jpg', 'From bestselling author Stephen Graham Jones comes a “masterpiece” (Locus Magazine) of a novel about revenge, cultural identity, and the cost of breaking from tradition. This is a remarkable horror story that “will give you nightmares—the good kind of course” (BuzzFeed).

From New York Times bestselling author Stephen Graham Jones comes a novel that is equal parts psychological horror and cutting social commentary on identity politics and the American Indian experience. Fans of Sylvia Moreno Garcia and Tommy Orange will love this story as it follows the lives of four American Indian men and their families, all haunted by a disturbing, deadly event that took place in their youth. Years later, they find themselves tracked by an entity bent on revenge, totally helpless as the culture and traditions they left behind catch up to them in a violent, vengeful way.

In this “thrilling, literate, scary, [and] immersive” (Stephen King) tale, Jones blends his signature storytelling style with a haunting narrative that masterfully intertwines revenge, cultural identity, and tradition.', 352, null, 2020, 434939, (select id from series where hardcover_id = 256942), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Galaxy, and the Ground Within', 'Becky Chambers', '3104915369', 'https://assets.hardcover.app/editions/30411184/6059850649053926.jpg', 'National Bestseller! Return to the sprawling, Hugo Award-winning universe of the Galactic Commons to explore another corner of the cosmos—one often mentioned, but not yet explored—in this absorbing entry in the Wayfarers series, which blends heart-warming characters and imaginative adventure. With no water, no air, and no native life, the planet Gora is unremarkable. The only thing it has going for it is a chance proximity to more popular worlds, making it a decent stopover for ships traveling between the wormholes that keep the Galactic Commons connected. If deep space is a highway, Gora is just your average truck stop. At the Five-Hop One-Stop, long-haul spacers can stretch their legs (if they have legs, that is), and get fuel, transit permits, and assorted supplies. The Five-Hop is run by an enterprising alien and her sometimes helpful child, who work hard to provide a little piece of home to everyone passing through. When a freak technological failure halts all traffic to and from Gora, three strangers—all different species with different aims—are thrown together at the Five-Hop. Grounded, with nothing to do but wait, the trio—an exiled artist with an appointment to keep, a cargo runner at a personal crossroads, and a mysterious individual doing her best to help those on the fringes—are compelled to confront where they’ve been, where they might go, and what they are, or could be, to each other.', 333, null, 2021, 435198, (select id from series where hardcover_id = 1092), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Steppenwolf', 'Hermann Hesse, Basil Creighton', '0553131745', 'https://assets.hardcover.app/editions/3512145/d062403f-cedf-45b3-a03d-0e666b9291ce.jpg', 'A story that focuses on the loneliness and suffering of the protagonist, Harry Haller, who feels that he has no place in a world filled with meaningless frivolity. Having decided to take his own life a chance encounter causes him to change his views and he begins to learn ways to enjoy life. One of the most misunderstood of his novels the book is, according to Hesse, about the possibilities of transcendence and healing.', 256, null, 1927, 435859, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fisherman', 'John  Langan', '1804366498', 'https://assets.hardcover.app/external_data/42464673/73d561f2be945b4cf4eb88ace436f6d044cf9749.jpeg', 'In upstate New York, in the woods around Woodstock, Dutchman''s Creek flows out of the Ashokan Reservoir. Steep-banked, fast-moving, it offers the promise of fine fishing, and of something more, a possibility too fantastic to be true. When Abe and Dan, two widowers who have found solace in each other''s company and a shared passion for fishing, hear rumors of the Creek, and what might be found there, the remedy to both their losses, they dismiss it as just another fish story. Soon, though, the men find themselves drawn into a tale as deep and old as the Reservoir. It''s a tale of dark pacts, of long-buried secrets, and of a mysterious figure known as Der Fisher: the Fisherman. It will bring Abe and Dan face to face with all that they have lost, and with the price they must pay to regain it.', 282, null, 2016, 436320, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Slewfoot: A Tale of Bewitchery', 'Brom', '8328728125', 'https://assets.hardcover.app/external_data/61350707/da4f1422ef272436c66f4cf9538769405500e6d9.jpeg', 'A spirited young Englishwoman, Abitha, arrives at a Puritan colony betrothed to a stranger – only to become quickly widowed when her husband dies under mysterious circumstances. All alone in this pious and patriarchal society, Abitha fights for what little freedom she can grasp onto, while trying to stay true to herself and her past.

Enter Slewfoot, a powerful spirit of antiquity newly woken ... and trying to find his own role in the world. Healer or destroyer? Protector or predator? But as the shadows walk and villagers start dying, a new rumor is whispered: Witch.

Both Abitha and Slewfoot must swiftly decide who they are, and what they must do to survive in a world intent on hanging any who meddle in the dark arts.

Complete with 8 pages of Brom’s mesmerizing full-color artwork and chapter illustrations throughout, his latest book is sure to delight.', 288, null, 2021, 436837, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lovecraft Country', 'Matt Ruff', '1504682874', 'https://assets.hardcover.app/edition/30411761/15d290ef-496e-4ef6-a362-c5a83c9f5100.jpg', 'Now an HBO® Series from J.J. Abrams (Executive Producer of Westworld), Misha Green (Creator of Underground) and Jordan Peele (Director of Get Out)

The critically acclaimed cult novelist makes visceral the terrors of life in Jim Crow America and its lingering effects in this brilliant and wondrous work of the imagination that melds historical fiction, pulp noir, and Lovecraftian horror and fantasy.

Chicago, 1954. When his father Montrose goes missing, 22-year-old Army veteran Atticus Turner embarks on a road trip to New England to find him, accompanied by his Uncle George—publisher of The Safe Negro Travel Guide—and his childhood friend Letitia. On their journey to the manor of Mr. Braithwhite—heir to the estate that owned one of Atticus’s ancestors—they encounter both mundane terrors of white America and malevolent spirits that seem straight out of the weird tales George devours.

At the manor, Atticus discovers his father in chains, held prisoner by a secret cabal named the Order of the Ancient Dawn—led by Samuel Braithwhite and his son Caleb—which has gathered to orchestrate a ritual that shockingly centers on Atticus. And his one hope of salvation may be the seed of his—and the whole Turner clan’s—destruction.

A chimerical blend of magic, power, hope, and freedom that stretches across time, touching diverse members of two black families, Lovecraft Country is a devastating kaleidoscopic portrait of racism—the terrifying specter that continues to haunt us today.', 329, null, 2016, 436903, (select id from series where hardcover_id = 38661), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Billy Summers', 'Stephen King', '9520434542', 'https://assets.hardcover.app/edition/31937930/e3f816ee-9d80-426b-81d6-27c7af882d5f.jpg', 'Billy Summers is a man in a room with a gun. He’s a killer for hire and the best in the business. But he’ll do the job only if the target is a truly bad guy. And now Billy wants out. But first there is one last hit. Billy is among the best snipers in the world, a decorated Iraq war vet, a Houdini when it comes to vanishing after the job is done. So what could possibly go wrong?

How about everything...', 433, null, 2021, 437349, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Peripheral', 'William Gibson', '0670921556', 'https://assets.hardcover.app/external_data/647785/01f633312614305fb66dfec00005136c90fb7643.jpeg', 'Flynne Fisher lives down a country road, in a rural America where jobs are scarce, unless you count illegal drug manufacture, which she’s trying to avoid. Her brother Burton lives on money from the Veterans Administration, for neurological damage suffered in the Marines’ elite Haptic Recon unit. Flynne earns what she can by assembling product at the local 3D printshop. She made more as a combat scout in an online game, playing for a rich man, but she’s had to let the shooter games go.

Wilf Netherton lives in London, seventy-some years later, on the far side of decades of slow-motion apocalypse. Things are pretty good now, for the haves, and there aren’t many have-nots left. Wilf, a high-powered publicist and celebrity-minder, fancies himself a romantic misfit, in a society where reaching into the past is just another hobby. 

Burton’s been moonlighting online, secretly working security in some game prototype, a virtual world that looks vaguely like London, but a lot weirder. He’s got Flynne taking over shifts, promised her the game’s not a shooter. Still, the crime she witnesses there is plenty bad.

Flynne and Wilf are about to meet one another. Her world will be altered utterly, irrevocably, and Wilf’s, for all its decadence and power, will learn that some of these third-world types from the past can be badass.', null, null, 2014, 438128, (select id from series where hardcover_id = 5607), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Rise of Endymion', 'Dan Simmons', '9985310926', 'https://assets.hardcover.app/external_data/49432431/3ca180fb028a96af852f111af69fa2d8ed807c6a.jpeg', 'The time of reckoning has arrived. As a final genocidal Crusade threatens to enslave humanity forever, a new messiah has come of age. She is Aenea and she has undergone a strange apprenticeship to those known as the Others. Now her protector, Raul Endymion, one-time shepherd and convicted murderer, must help her deliver her startling message to her growing army of disciples. But first they must embark on a final spectacular mission to discover the underlying meaning of the universe itself. They have been followed on their journey by the mysterious Shrike - monster, angel, killing machine - who is about to reveal the long-held secret of its origin and purpose. And on the planet of Hyperion, where the story first began, the final revelation will be delivered - an apocalyptic message that unlocks the secrets of existence and the fate of humankind in the galaxy.', 709, null, 1997, 438682, (select id from series where hardcover_id = 1049), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dragonflight', 'Anne McCaffrey', '0808521195', 'https://assets.hardcover.app/edition/2296568/d0844798f9ba77ba15dacb1126ccf47b55935524.jpeg', 'HOW CAN ONE GIRL SAVE AN ENTIRE WORLD?To the nobles who live in Benden Weyr, Lessa is nothing but a ragged kitchen girl. For most of her life she has survived by serving those who betrayed her father and took over his lands. Now the time has come for Lessa to shed her disguise--and take back her stolen birthright. But everything changes when she meets a queen dragon. The bond they share will be deep and last forever. It will protect them when, for the first time in centuries, Lessa''s world is threatened by Thread, an evil substance that falls like rain and destroys everything it touches. Dragons and their Riders once protected the planet from Thread, but there are very few of them left these days. Now brave Lessa must risk her life, and the life of her beloved dragon, to save her beautiful world. . . .From the Paperback edition.', 356, null, 1968, 438686, (select id from series where hardcover_id = 5658), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Unwind', 'Neal Shusterman', '3411809922', 'https://assets.hardcover.app/external_data/3906285/74e60658fc443272fa7b331d1921fbab76051616.jpeg', 'In a future world where those between the ages of thirteen and eighteen can have their lives "unwound" and their body parts harvested for use by other, three teens go to extreme lengths to uphold their beliefs--and, perhaps, save their own lives.', 337, null, 2007, 438689, (select id from series where hardcover_id = 5536), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Kingdom of Copper', 'S. A. Chakraborty', '6178383541', 'https://assets.hardcover.app/books/439240/8983487983150478.jpg', 'Nahri’s life changed forever the moment she accidentally summoned Dara, a formidable, mysterious djinn, during one of her schemes. Whisked from her home in Cairo, she was thrust into the dazzling royal court of Daevabad—and quickly discovered she would need all her grifter instincts to survive there.

Now, with Daevabad entrenched in the dark aftermath of a devastating battle, Nahri must forge a new path for herself. But even as she embraces her heritage and the power it holds, she knows she’s been trapped in a gilded cage, watched by a king who rules from the throne that once belonged to her family—and one misstep will doom her tribe..

Meanwhile, Ali has been exiled for daring to defy his father. Hunted by assassins, adrift on the unforgiving copper sands of his ancestral land, he is forced to rely on the frightening abilities the marid—the unpredictable water spirits—have gifted him. But in doing so, he threatens to unearth a terrible secret his family has long kept buried.

And as a new century approaches and the djinn gather within Daevabad''s towering brass walls for celebrations, a threat brews unseen in the desolate north. It’s a force that would bring a storm of fire straight to the city’s gates . . . and one that seeks the aid of a warrior trapped between worlds, torn between a violent duty he can never escape and a peace he fears he will never deserve.', 645, null, 2018, 439240, (select id from series where hardcover_id = 1628), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Colony', 'John Scalzi', '345352442X', 'https://assets.hardcover.app/edition/20587242/3f3faaa84d2696686d08b860829110a1652b75fe.jpeg', 'Retired from his fighting days, John Perry is now village ombudsman for a human colony on distant Huckleberry. With his wife, former Special Forces warrior Jane Sagan, he farms several acres, adjudicates local disputes, and enjoys watching his adopted daughter grow up. That is, until his and Jane''s past reaches out to bring them back into the game — as leaders of a new human colony, to be peopled by settlers from all the major human worlds, for a deep political purpose that will put Perry and Sagan back in the thick of interstellar politics, betrayal, and war. "Scalzi''s Hugo finalist, Old Man''s War first spawned the equally entertaining Ghost Brigades. And now, a third volume reprises the story of John Perry, former planet-hopping soldier who has now traded his genetically enhanced second body for a commonplace one and a peaceful retirement. Free from the stresses of battle, he''s enjoying domestic bliss with his wife and adopted daughter on a remote Colonial Union world. Then a former commanding general drops by with a tempting proposal. Perry and his wife are apparently the perfect candidates to lead a promising new colony populated by citizens from 10 worlds. They accept, but then the CU deceitfully strands them and their charges on an unknown world. Perry discovers they are pawns in a deadly game calculated to destroy an alien coalition whose purposes include blocking further human colonization . . . Scalzi''s captivating blend of off-world adventure and political intrigue remains consistently engaging."—Carl Hays, Booklist “Full of whodunit twists and explosive action, Scalzi''s third SF novel [is] entertaining storytelling on a very human scale. Several years after the events of The Ghost Brigades (2006), John Perry, the hero of Old Man''s War (2005), and Jane Sagan are leading a normal life as administrator and constable on the colonial planet Huckleberry with their adopted daughter, Zoë, when they get conscripted to run a new colony, ominously named Roanoke. When the colonists are dropped onto a different planet than the one they expected, they find themselves caught in a confrontation between the human Colonial Union and the alien confederation called the Conclave. Hugo-finalist Scalzi avoids political allegory, promoting individual compassion and honesty and downplaying patriotic loyalty—except in the case of the inscrutable Obin, hive-mind aliens whose devotion to Zoë will remind fans of the benevolent role Captain Nemo plays in Verne''s Mysterious Island.”—Publishers Weekly', 336, null, 2007, 439477, (select id from series where hardcover_id = 1048), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The One', 'John Marrs', '1335998853', 'https://assets.hardcover.app/external_data/1514181/c8175760ed3042fe62caf0d90a660dc308d45a4f.jpeg', 'A thrilling speculative novel for fans of Severance, Silo, and Dark Matter

How far would you go to find The One?

A simple DNA test is all it takes. Just a quick mouth swab and soon you’ll be matched with your perfect partner—the one you’re genetically made for.

That’s the promise made by Match Your DNA. A decade ago, the company announced that they had found the gene that pairs each of us with our soul mate. Since then, millions of people around the world have been matched. But the discovery has its downsides: test results have led to the breakup of countless relationships and upended the traditional ideas of dating, romance and love.

Now five very different people have received the notification that they’ve been “Matched.” They’re each about to meet their one true love. But “happily ever after” isn’t guaranteed for everyone. Because even soul mates have secrets. And some are more shocking than others…

The nationally bestselling first book in the Dark Future series, The One is a fascinating novel that shows how even the simplest discoveries can have complicated consequences.', 418, null, 1990, 440679, (select id from series where hardcover_id = 208892), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Graduate', 'Naomi Novik', '0593128869', 'https://assets.hardcover.app/editions/30396979/4323730316562786.jpg', 'In Wisdom, Shelter. That’s the official motto of the Scholomance. I suppose you could even argue that it’s true—only the wisdom is hard to come by, so the shelter’s rather scant. 
 
Our beloved school does its best to devour all its students—but now that I’ve reached my senior year and have actually won myself a handful of allies, it’s suddenly developed a very particular craving for me. And even if I somehow make it through the endless waves of maleficaria that it keeps throwing at me in between grueling homework assignments, I haven’t any idea how my allies and I are going to make it through the graduation hall alive. 
 
Unless, of course, I finally accept my foretold destiny of dark sorcery and destruction. That would certainly let me sail straight out of here. The course of wisdom, surely.
 
But I’m not giving in—not to the mals, not to fate, and especially not to the Scholomance. I’m going to get myself and my friends out of this hideous place for good—even if it’s the last thing I do.', 388, null, 2021, 441044, (select id from series where hardcover_id = 1031), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Traitor Baru Cormorant', 'Seth Dickinson', '6069000102', 'https://assets.hardcover.app/edition/6336284/51bd032bbe68a5f3531d79fab8beab188bcb13d2.jpeg', 'Baru Cormorant believes any price is worth paying to liberate her people-even her soul.

When the Empire of Masks conquers her island home, overwrites her culture, criminalizes her customs, and murders one of her fathers, Baru vows to swallow her hate, join the Empire''s civil service, and claw her way high enough to set her people free.

Sent as an Imperial agent to distant Aurdwynn, another conquered country, Baru discovers it''s on the brink of rebellion. Drawn by the intriguing duchess Tain Hu into a circle of seditious dukes, Baru may be able to use her position to help. As she pursues a precarious balance between the rebels and a shadowy cabal within the Empire, she orchestrates a do-or-die gambit with freedom as the prize.

But the cost of winning the long game of saving her people may be far greater than Baru imagines.
', 400, null, 2015, 441070, (select id from series where hardcover_id = 2756), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Light of All That Falls', 'James Islington', '8027506336', 'https://assets.hardcover.app/edition/30405513/6cfa324e11cecd1e730e3fefd28007de17a688a9.jpeg', 'After a savage battle, the Boundary is whole again -- but it may be too late. Banes now stalk the lands of Andarra, and the Venerate have gathered their armies for a final, crushing blow.
In Ilin Illan, Wirr fights to maintain a precarious alliance between Andarra''s factions of power. With dark forces closing in on the capital, if he cannot succeed, the war is lost.
Imprisoned and alone in a strange land, Davian is pitted against the remaining Venerate. As he desperately tries to keep them from undoing Asha''s sacrifice, he struggles to come to terms with his own path and all he has learned about Caeden, the friend he chose to set free.
Finally, Caeden is confronted with the reality of a plan laid centuries ago -- heartbroken at how it started and devastated by how it must end.', 830, null, 2019, 441085, (select id from series where hardcover_id = 5982), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Consuming Fire', 'John Scalzi', '0765388979', 'https://assets.hardcover.app/edition/32627474/15b079e2-9859-4a31-a6a8-1eb1285b5bb7.jpg', 'The Interdependency—humanity’s interstellar empire—is on the verge of collapse. The extra-dimensional conduit that makes travel between the stars possible is disappearing, leaving entire systems and human civilizations stranded.

Emperox Grayland II of the Interdependency is ready to take desperate measures to help ensure the survival of billions. But arrayed before her are those who believe the collapse of the Flow is a myth—or at the very least an opportunity to an ascension to power.

While Grayland prepares for disaster, others are prepare for a civil war. A war that will take place in the halls of power, the markets of business and the altars of worship as much as it will between spaceships and battlefields.

The Emperox and her allies are smart and resourceful, as are her enemies. Nothing about this will be easy... and all of humanity will be caught in its consuming fire.', 304, null, 2018, 441246, (select id from series where hardcover_id = 1142), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Emperox', 'John Scalzi', '3104913153', 'https://assets.hardcover.app/edition/30448656/155eb0da-03da-4352-865b-f56dbeea0cd9.jpg', 'The collapse of The Flow, the interstellar pathway between the planets of the Interdependency, has accelerated. Entire star systems—and billions of people—are becoming cut off from the rest of human civilization. This collapse was foretold through scientific prediction . . . and yet, even as the evidence is obvious and insurmountable, many still try to rationalize, delay and profit from, these final days of one of the greatest empires humanity has ever known.

Emperox Grayland II has finally wrested control of her empire from those who oppose her and who deny the reality of this collapse. But “control” is a slippery thing, and even as Grayland strives to save as many of her people form impoverished isolation, the forces opposing her rule will make a final, desperate push to topple her from her throne and power, by any means necessary. Grayland and her thinning list of allies must use every tool at their disposal to save themselves, and all of humanity. And yet it may not be enough.

Will Grayland become the savior of her civilization . . . or the last emperox to wear the crown?', 308, null, 2020, 441260, (select id from series where hardcover_id = 1142), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Metro 2033', 'Dmitry Glukhovsky, Σταυρούλα Αργυροπούλου', '8361428992', 'https://assets.hardcover.app/edition/31605402/0f6796c0db2470a9117ddd6d2fb746ce6635a549.jpeg', '2033: Ο κόσμος έχει μετατραπεί σε ερείπια. Λίγες χιλιάδες ανθρώπων έχουν επιζήσει, δεν γνωρίζουν όμως αν είναι και οι τελευταίοι στη Γη. Ζουν στο μετρό της Μόσχας – το μεγαλύτερο αντιπυρηνικό καταφύγιο που κατασκευάστηκε ποτέ, το τελευταίο καταφύγιο του ανθρώπινου είδους. Ο κόσμος του μετρό δεν έχει αύριο: τα όνειρα, τα σχέδια, η ελπίδα μοιάζουν καταδικασμένα. Το συναίσθημα έχει πλέον παραδοθεί στο ένστικτο. Στην ανάγκη για την επιβίωση, με οποιοδήποτε κόστος ή τίμημα.
Η ΒΕ-ΝΤΕ-ΕΝ-ΧΑ, ένας από τους βορειότερους σταθμούς, κατοικείται και παραμένει ακόμη ασφαλής, αλλά μια νέα, τρομερή απειλή έχει κάνει την εμφάνισή της. Ο Αρτιόμ, ένας νέος άντρας που ζει εκεί, θα αναλάβει, περιπλανώμενος στις πιο σκοτεινές σήραγγες, να εισχωρήσει στην καρδιά του μετρό, στη θρυλική Πόλη, για να φέρει σε πέρας την αποστολή που του ανατέθηκε. Είναι αυτός που κρατά στα χέρια του το μέλλον του σταθμού του, το μέλλον του μετρό, αλλά και το μέλλον ίσως ολόκληρης της ανθρωπότητας.
Το παγκόσμιο μπεστ σέλερ, που απέσπασε διθυραμβικές κριτικές και έγινε επιτυχημένο ηλεκτρονικό παιχνίδι, τώρα και στην Ελλάδα. Ένα ταξίδι σε έναν κόσμο σκοτεινό αλλά και συναρπαστικό, σ’ ένα μέλλον που μας καθηλώνει με την άγρια απειλή του.', 544, null, 2011, 443116, (select id from series where hardcover_id = 113813), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ministry for the Future', 'Kim Stanley Robinson', '1549161768', 'https://assets.hardcover.app/edition/12025029/b4ac63decd45e6a860afd45fa71b2119b3004759.jpeg', '*The Ministry for the Future* is a masterpiece of the imagination, using fictional eyewitness accounts to tell the story of how climate change will affect us all. Its setting is not a desolate, post-apocalyptic world, but a future that is almost upon us. Chosen by Barack Obama as one of his favorite books of the year, this extraordinary novel from visionary science fiction writer Kim Stanley Robinson will change the way you think about the climate crisis.

ONE OF BARACK OBAMA’S FAVORITE BOOKS OF THE YEAR

“The best science-fiction nonfiction novel I’ve ever read.” —Jonathan Lethem
 
"If I could get policymakers, and citizens, everywhere to read just one book this year, it would be Kim Stanley Robinson’s The Ministry for the Future." —Ezra Klein (Vox)

"One hopes that this book is read widely—that Robinson’s audience, already large, grows by an order of magnitude. Because the point of his books is to fire the imagination."―New York Review of Books

"If there’s any book that hit me hard this year, it was Kim Stanley Robinson’s The Ministry for the Future, a sweeping epic about climate change and humanity’s efforts to try and turn the tide before it’s too late." ―Polygon (Best of the Year)
 
"Masterly." —New Yorker

"[The Ministry for the Future] struck like a mallet hitting a gong, reverberating through the year ... it’s terrifying, unrelenting, but ultimately hopeful. Robinson is the SF writer of my lifetime, and this stands as some of his best work. It’s my book of the year." —Locus

"Science-fiction visionary Kim Stanley Robinson makes the case for quantitative easing our way out of planetary doom." ―Bloomberg Green

Source: Publisher', 563, null, 2020, 443343, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Tree Grows in Brooklyn', 'Betty Smith', '0060801263', 'https://assets.hardcover.app/book_mappings/7333021/0b43734baa588dec6c20c5f4e1dbb367405b913c.jpeg', 'The beloved American classic about a young girl''s coming-of-age at the turn of the century, Betty Smith''s A Tree Grows in Brooklyn is a poignant and moving tale filled with compassion and cruelty, laughter and heartache, crowded with life and people and incident. The story of young, sensitive, and idealistic Francie Nolan and her bittersweet formative years in the slums of Williamsburg has enchanted and inspired millions of readers for more than sixty years. By turns overwhelming, sublime, heartbreaking, and uplifting, the daily experiences of the unforgettable Nolans are raw with honesty and tenderly threaded with family connectedness -- in a work of literary art that brilliantly captures a unique time and place as well as incredibly rich moments of universal experience.', 509, null, 1943, 444413, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Her Body and Other Parties', 'Carmen Maria Machado', '3608115293', 'https://assets.hardcover.app/external_data/60032229/7efc4be73aa99c3b63587614afb4ff34a1150e19.jpeg', 'In Her Body and Other Parties, Carmen Maria Machado blithely demolishes the arbitrary borders between psychological realism and science fiction, comedy and horror, fantasy and fabulism. While her work has earned her comparisons to Karen Russell and Kelly Link, she has a voice that is all her own. In this electric and provocative debut, Machado bends genre to shape startling narratives that map the realities of women’s lives and the violence visited upon their bodies.

A wife refuses her husband’s entreaties to remove the green ribbon from around her neck. A woman recounts her sexual encounters as a plague slowly consumes humanity. A salesclerk in a mall makes a horrifying discovery within the seams of the store’s prom dresses. One woman’s surgery-induced weight loss results in an unwanted houseguest. And in the bravura novella “Especially Heinous,” Machado reimagines every episode of Law & Order: Special Victims Unit, a show we naïvely assumed had shown it all, generating a phantasmagoric police procedural full of doppelgängers, ghosts, and girls with bells for eyes.

Earthy and otherworldly, antic and sexy, queer and caustic, comic and deadly serious, Her Body and Other Parties swings from horrific violence to the most exquisite sentiment. In their explosive originality, these stories enlarge the possibilities of contemporary fiction.', 245, null, 2017, 445010, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('When We Cease to Understand the World', 'Benjamín Labatut, Adrian Nathan West', '1782278672', 'https://assets.hardcover.app/external_data/59508430/ada95f71e07752b30ae3ffc5c41025355ae56d90.jpeg', 'SELECTED FOR BARACK OBAMA’S SUMMER READING LIST ‘A monstrous and brilliant book’ Philip Pullman ‘Wholly mesmerising and revelatory... Completely fascinating’ William Boyd Sometimes discovery brings destruction When We Cease to Understand the World shows us great minds striking out into dangerous, uncharted terrain. Fritz Haber, Alexander Grothendieck, Werner Heisenberg, Erwin Schrödinger: these are among the luminaries into whose troubled lives we are thrust as they grapple with the most profound questions of existence. They have strokes of unparalleled genius, they alienate friends and lovers, they descend into isolated states of madness. Some of their discoveries revolutionise our world for the better; others pave the way to chaos and unimaginable suffering. The lines are never clear. With breakneck pace and wondrous detail, Benjamín Labatut uses the imaginative resources of fiction to break open the stories of scientists and mathematicians who expanded our notions of the possible.', 192, null, 2019, 445032, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Zoe''s Tale', 'John Scalzi', '3453525612', 'https://assets.hardcover.app/edition/32502130/08e94d424590543d340833f768fd998cbdb443a2.jpeg', 'How do you tell your part in the biggest tale in history?

I ask because it''s what I have to do. I''m Zoe Boutin Perry: A colonist stranded on a deadly pioneer world. Holy icon to a race of aliens. A player (and a pawn) in a interstellar chess match to save humanity, or to see it fall. Witness to history. Friend. Daughter. Human. Seventeen years old.

Everyone on Earth knows the tale I am part of. But you don''t know my tale: How I did what I did — how I did what I had to do — not just to stay alive but to keep you alive, too. All of you. I''m going to tell it to you now, the only way I know how: not straight but true, the whole thing, to try make you feel what I felt: the joy and terror and uncertainty, panic and wonder, despair and hope. Everything that happened, bringing us to Earth, and Earth out of its captivity. All through my eyes.

It''s a story you know. But you don''t know it all.', 336, null, 2008, 445045, (select id from series where hardcover_id = 1048), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Burning God', 'R.F. Kuang', '8835715172', 'https://assets.hardcover.app/external_data/50321830/c88e820437839aeed7b528ae46d4e045498c9c3d.jpeg', 'After saving her nation of Nikan from foreign invaders and battling the evil Empress Su Daji in a brutal civil war, Fang Runin was betrayed by allies and left for dead.

Despite her losses, Rin hasn''t given up on those for whom she has sacrificed so much – the people of the southern provinces and especially Tikany, the village that is her home. Returning to her roots, Rin meets difficult challenges – and unexpected opportunities. While her new allies in the Southern Coalition leadership are sly and untrustworthy, Rin quickly realizes that the real power in Nikan lies with the millions of common people who thirst for vengeance and revere her as a goddess of salvation.

Backed by the masses and her Southern Army, Rin will use every weapon to defeat the Dragon Republic, the colonizing Hesperians, and all who threaten the shamanic arts and their practitioners. As her power and influence grows, though, will she be strong enough to resist the Phoenix''s intoxicating voice urging her to burn the world and everything in it?', 636, null, 2020, 445509, (select id from series where hardcover_id = 985), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Paladin''s Grace', 'T. Kingfisher', '1705297722', 'https://assets.hardcover.app/edition/31616697/f6d02864f30f09d61d845f0a71056eac0888679b.jpeg', 'Three years later, Stephen is a broken paladin, living only for the chance to be useful before he dies. But all that changes when he encounters a fugitive named Grace in an alley and witnesses an assassination attempt gone wrong. Now the pair must navigate a web of treachery, beset on all sides by spies and poisoners, while a cryptic killer stalks one step behind...

From the Hugo and Nebula Award winning author of Swordheart and The Twisted Ones comes a saga of murder, magic, and love on the far side of despair.', 416, null, 2020, 445663, (select id from series where hardcover_id = 2206), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Jade Legacy', 'Fonda Lee', '1668604272', 'https://assets.hardcover.app/edition/13452302/45836e5c86d48b624825c9f537946a888bc21957.jpeg', '"Jade, the mysterious and magical substance once exclusive to the Green Bone warriors of Kekon, is now known and coveted throughout the world. Everyone wants access to the supernatural abilities it provides, from traditional forces such as governments, mercenaries, and criminal kingpins, to modern players, including doctors, athletes, and movie studios. As the struggle over the control of jade grows ever larger and more deadly, the Kaul family, and the ancient ways of the Kekonese Green Bones, will never be the same. The Kauls have been battered by war and tragedy. They are plagued by resentments and old wounds as their adversaries are on the ascent and their country is riven by dangerous factions and foreign interference that could destroy the Green Bone way of life altogether. As a new generation arises, the clan''s growing empire is in danger of coming apart. The clan must discern allies from enemies, set aside bloody rivalries, and make terrible sacrifices... but even the unbreakable bonds of blood and loyalty may not be enough to ensure the survival of the Green Bone clans and the nation they are sworn to protect"--', 713, null, 2021, 445842, (select id from series where hardcover_id = 1085), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Age of Myth', 'Michael J. Sullivan', '1490641319', 'https://assets.hardcover.app/edition/4684056/9996b1ee1b799cedc76a61e47b2ec70e633eda1e.jpeg', '"Michael J. Sullivan''s trailblazing career began with the breakout success of his Riyria series: full-bodied, spellbinding fantasy adventures whose imaginative scope and sympathetic characters won a devoted readership and comparisons to fantasy masters Brandon Sanderson, Scott Lynch, and J.R.R. Tolkien himself. Now, Sullivan''s stunning hardcover debut, Age of Myth, inaugurates an original five-book series--and one of fantasy''s finest next-generation storytellers continues to break new ground. Since time immemorial, humans have worshiped the gods they call Fhrey, truly a race apart: invincible in battle, masters of magic, and seemingly immortal. But when a god falls to a human blade, the balance of power between humans and the those they thought were gods changes forever. Now only a few stand between humankind and annihilation: Raithe, reluctant to embrace his destiny as the God Killer. Suri, a young seer burdened by signs of impending doom. And Persephone, who must overcome personal tragedy to lead her people. The Age of Myth is over. The time of rebellion has begun"--

"A new series set in the world of the Riyria Chronicles. In the land of the Rhune, trees can tell the future and the gods are beyond reproach. But when Raithe''s father is slain, he does the unthinkable--he kills a god. From this act, rises the legend of the God Killer, the seeds of a rebellion, and the question of whether the gods are really immortal after all"--', 409, null, 2016, 445850, (select id from series where hardcover_id = 5990), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Soul Music', 'Terry Pratchett', '075315157X', 'https://assets.hardcover.app/edition/31519385/0d708a07daa8aa2cd9211cf30ae66cb25935afce.jpeg', 'It’s hard to grow up normal when Grandfather rides a white horse and wields a scythe — and especially when you have to face the new and addictive music that has entered Discworld. It’s lawless. It changes people. It’s called Music with Rocks In. It’s alive. And it won’t fade away.', 286, null, 1994, 446075, (select id from series where hardcover_id = 1018), '16') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Moving Pictures', 'Terry Pratchett', '0575064862', 'https://assets.hardcover.app/edition/30917992/02df5916-197f-40df-adbe-94778241bf3e.jpg', '''HOLY WOOD IS A DIFFERENT SORT OF PLACE . . . HERE, THE MOST IMPORTANT THING IS TO BE IMPORTANT.'' A new phenomenon is taking over the Discworld: moving pictures. Created by the alchemists of Ankh-Morpork, the growing ''clicks'' industry moves to the sandy land of Holy Wood, attracted by the light of the sun and some strange calling no one can quite put their finger on... Also drawn to Holy Wood are aspiring young stars Victor Tugelbend, a wizarding student dropout, and Theda ''Ginger'' Withel, a small-town girl with big dreams. But behind the glitz and glamour of the clicks, a sinister presence lurks. Because belief is powerful in the Discworld, and sometimes downright dangerous... The magic of movies might just unravel reality itself. ''Funny, delightfully inventive, and refuses to lie down in its genre'' - Observer The Discworld novels can be read in any order but Moving Pictures is a standalone.', 400, null, 1990, 446076, (select id from series where hardcover_id = 1018), '10') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Monstrous Regiment', 'Terry Pratchett', '0552149403', 'https://assets.hardcover.app/edition/30587045/f3d9d1862fb510c15b3840de843cb55e5e41e9d1.jpeg', 'In the small yet aggressive country of Borogravia, there are strict rules citizens must follow.

For a start, women belong in the kitchen - not in jobs, pubs, or indeed trousers. And certainly not on the front line.

Polly Perks has to become a boy in a hurry if she wants to find her missing brother in the army. Cutting off her hair and wearing the trousers is easy. Going to war however, is not.

Polly and her fellow raw recruits are suddenly in the thick of a losing battle. All they have on their side is the most artful sergeant in the army and a vampire with a lust for coffee.

It''s time to make a stand.

The Discworld novels can be read in any order but Monstrous Regiment is a standalone.', 484, null, 2003, 446077, (select id from series where hardcover_id = 1018), '31') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Feet of Clay', 'Terry Pratchett', '0062275518', 'https://assets.hardcover.app/edition/32262836/bdb61ccfcbc32d8e9bc034403c281813cb0ef4ec.jpeg', 'Nineteenth in the Discworld universe and third entry of the City Watch series, this novel follows Captain Carrot, Commander Vimes, and the rest of the Night Watch as they attempt to unravel the mystery of who poisoned Lord Vetinari the Patrician.', 409, null, 1996, 446079, (select id from series where hardcover_id = 1018), '19') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fool''s Assassin', 'Robin Hobb', '0593725468', 'https://assets.hardcover.app/external_data/31738009/ddfcf02a6c0f6cb2778e7269022f3015b9e82361.jpeg', 'Tom Badgerlock has been living peaceably in the manor house at Withywoods with his beloved wife Molly these many years, the estate a reward to his family for loyal service to the crown. But behind the facade of respectable middle-age lies a turbulent and violent past. For Tom Badgerlock is actually FitzChivalry Farseer, bastard scion of the Farseer line, convicted user of Beast-magic, and assassin. A man who has risked much for his king and lost more. On a shelf in his den sits a triptych carved in memory stone of a man, a wolf and a fool. Once, these three were inseparable friends: Fitz, Nighteyes and the Fool. But one is long dead, and one long-missing. Then one Winterfest night a messenger arrives to seek out Fitz, but mysteriously disappears, leaving nothing but a blood-trail. What was the message? Who was the sender? And what has happened to the messenger? Suddenly Fitz''s violent old life erupts into the peace of his new world, and nothing and no one is safe.', 630, null, 2014, 448515, (select id from series where hardcover_id = 6001), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Dowry of Blood', 'S.T. Gibson', '1916366937', 'https://assets.hardcover.app/edition/30551178/2007f7ef26600fc56320ed3049c59d75979cc5de.jpeg', 'Saved from the brink of death by a mysterious stranger, Constanta is transformed from a medieval peasant into a bride fit for an undying king. But when Dracula draws a cunning aristocrat and a starving artist into his web of passion and deceit, Constanta realizes that her beloved is capable of terrible things.

Finding comfort in the arms of her rival consorts, she begins to unravel their husband''s dark secrets. With the lives of everyone she loves on the line, Constanta will have to choose between her own freedom and her love for her husband. But bonds forged by blood can only be broken by death.', 304, null, 2021, 450530, (select id from series where hardcover_id = 208035), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Elder Race', 'Adrian Tchaikovsky', '1250768721', 'https://assets.hardcover.app/book/453591/2d90478e-d6c8-4734-a63a-a49e4bb34ab6.jpg', 'A junior anthropologist on a distant planet must help the locals he has sworn to study to save a planet from an unbeatable foe.

Lynesse is the lowly Fourth Daughter of the queen, and always getting in the way.

But a demon is terrorizing the land, and now she’s an adult (albeit barely) and although she still gets in the way, she understands that the only way to save her people is to invoke the pact between her family and the Elder sorcerer who has inhabited the local tower for as long as her people have lived here (though none in living memory has approached it).

But Elder Nyr isn’t a sorcerer, and he is forbidden to help, for his knowledge of science tells him the threat cannot possibly be a demon…', 204, null, 2021, 453591, (select id from series where hardcover_id = 257975), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lost Apothecary', 'Sarah Penner', '1922626236', 'https://assets.hardcover.app/edition/21373583/56296d40afd83524667821387fc911ffb6d3c8b2.jpeg', 'Rule #1: The poison must never be used to harm another woman.
Rule #2: The names of the murderer and her victim must be recorded in the apothecary’s register.

One cold February evening in 1791, at the back of a dark London alley in a hidden apothecary shop, Nella awaits her newest customer. Once a respected healer, Nella now uses her knowledge for a darker purpose - selling well-disguised poisons to desperate women who would kill to be free of the men in their lives. But when her new patron turns out to be a precocious twelve-year-old named Eliza Fanning, an unexpected friendship sets in motion a string of events that jeopardizes Nella’s world and threatens to expose the many women whose names are written in her register.

In present-day London, aspiring historian Caroline Parcewell spends her tenth wedding anniversary alone, reeling from the discovery of her husband’s infidelity. When she finds an old apothecary vial near the river Thames, she can’t resist investigating, only to realize she’s found a link to the unsolved “apothecary murders” that haunted London over two centuries ago. As she deepens her search, Caroline’s life collides with Nella’s and Eliza’s in a stunning twist of fate - and not everyone will survive.', 320, null, 2021, 454061, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mona Lisa Overdrive', 'William Gibson', '9605210665', 'https://assets.hardcover.app/edition/30539909/c5482fd0-65f5-4c23-9f4f-4ac801b9e5d7.jpg', 'William Gibson, author of the extraordinary multiaward-winning novel Neuromancer, has written his most brilliant and thrilling work to date . . .The Mona Lisa Overdrive. Enter Gibson''s unique world—lyric and mechanical, sensual and violent, sobering and exciting—where multinational corporations and high tech outlaws vie for power, traveling into the computer-generated universe known as cyberspace. Into this world comes Mona, a young girl with a murky past and an uncertain future whose life is on a collision course with internationally famous Sense/Net star Angie Mitchell. Since childhood, Angie has been able to tap into cyberspace without a computer. Now, from inside cyberspace, a kidnapping plot is masterminded by a phantom entity who has plans for Mona, Angie, and all humanity, plans that cannot be controlled . . . or even known. And behind the intrigue lurks the shadowy Yazuka, the powerful Japanese underworld, whose leaders ruthlessly manipulate people and events to suit their own purposes . . . or so they think.', 320, null, 1988, 457145, (select id from series where hardcover_id = 19911), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Skin Game', 'Jim Butcher', '9780451464390', 'https://assets.hardcover.app/edition/26561937/36162b095bb5ad016b7913e26a8ec95f1a97a1f1.jpeg', 'Chicago’s only professional wizard is about to have a very bad day in the latest novel in the #1 New York Times bestselling Dresden Files... 

As Winter Knight to the Queen of Air and Darkness, Harry Dresden never knows what the scheming Mab might want him to do. Usually, it’s something awful. Mab has traded Harry’s skills to pay off a debt. And now he must help a group of villains led by Harry’s most despised enemy, Nicodemus Archleone, to break into a high-security vault so that they can then access a vault in the Nevernever. 

Problem is, the vault belongs to Hades, Lord of the freaking Underworld. And Dresden is dead certain that Nicodemus has no intention of allowing any of his crew to survive the experience. Dresden’s always been tricky, but he’s going to have to up his backstabbing game to survive this mess...', 614, null, 2014, 458592, (select id from series where hardcover_id = 990), '15') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Aeronaut''s Windlass', 'Jim Butcher', '0451466802', 'https://assets.hardcover.app/editions/30801350/1956741642305315.jpg', 'Jim Butcher, the #1 New York Times bestselling author of the Dresden Files and the Codex Alera novels, conjures up a new series set in a fantastic world of noble families, steam-powered technology, and magic-wielding warriors... Since time immemorial, the Spires have sheltered humanity. Within their halls, the ruling aristocratic houses develop scientific marvels, foster trade alliances, and maintain fleets of airships to keep the peace. Captain Grimm commands the merchant ship Predator. Loyal to Spire Albion, he has taken their side in the cold war with Spire Aurora, disrupting the enemy’s shipping lines by attacking their cargo vessels. But when the Predator is damaged in combat, Grimm joins a team of Albion agents on a vital mission in exchange for fully restoring his ship. And as Grimm undertakes this task, he learns that the conflict between the Spires is merely a premonition of things to come. Humanity’s ancient enemy, silent for more than ten thousand years, has begun to stir once more. And death will follow in its wake...', 630, null, 2015, 458602, (select id from series where hardcover_id = 7868), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Half a King', 'Joe Abercrombie', '3453315995', 'https://assets.hardcover.app/edition/30395366/cbb156a87e85aee8bd9717c2c9d7d5a4df83cf58.jpeg', 'Betrayed by his family and left for dead, prince Yarvi, reluctant heir to a divided kingdom, has vowed to reclaim a throne he never wanted. But first he must survive cruelty, chains and the bitter waters of the shattered sea itself - all with only one good hand. Born a weakling in the eyes of a hard, cold world, he cannot grip a shield or swing an axe, so has sharpened his mind to a deadly edge. Gathering a strange fellowship of the outcast, he finds they can help him more than any noble could. Even so, Yarvi''s path may end as it began - in twists, traps and tragedy.', 336, null, 2014, 458843, (select id from series where hardcover_id = 6740), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Drive', 'James S. A. Corey', '1549165690', 'https://assets.hardcover.app/edition/31472228/7cf5a512-2bfe-4f43-90a0-51fbcd470695.jpg', 'A novella set in the universe of James S. A. Corey''s New York Times bestselling Expanse series, now a Prime Original series. This story will be available in the complete Expanse story collection, Memory''s Legion. HUGO AWARD WINNER FOR BEST SERIES The Expanse series: Leviathan Wakes Caliban''s War Abaddon''s Gate Cibola Burn Nemesis Games Babylon''s Ashes Persepolis Rising Tiamat''s Wrath Leviathan Falls Memory''s Legion The Expanse Short Fiction: Drive The Butcher of Anderson Station Gods of Risk The Churn The Vital Abyss Strange Dogs Auberon The Sins of Our Fathers Praise for the Expanse: ''The science fictional equivalent of A Song of Ice and Fire'' NPR Books ''As close as you''ll get to a Hollywood blockbuster in book form'' io9.com ''Great characters, excellent dialogue, memorable fights'' wired.com ''This is the future the way it''s supposed to be'' Wall Street Journal', 80, null, 2012, 460727, (select id from series where hardcover_id = 1026), '2.7') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wisdom of Crowds', 'Joe Abercrombie', '5043823828', 'https://assets.hardcover.app/external_data/50560073/c434421435eb33716cfb5981fb4bd645d69f0df2.jpeg', 'Chaos. Fury. Destruction.

The Great Change is upon us . . .

Some say that to change the world you must first burn it down. Now that belief will be tested in the crucible of revolution: the Breakers and Burners have seized the levers of power, the smoke of riots has replaced the smog of industry, and all must submit to the wisdom of crowds.

With nothing left to lose, Citizen Brock is determined to become a new hero for the new age, while Citizeness Savine must turn her talents from profit to survival before she can claw her way to redemption. Orso will find that when the world is turned upside down, no one is lower than a monarch. And in the bloody North, Rikke and her fragile Protectorate are running out of allies . . . while Black Calder gathers his forces and plots his vengeance.

The banks have fallen, the sun of the Union has been torn down, and in the darkness behind the scenes, the threads of the Weaver''s ruthless plan are slowly being drawn together . . .', 528, null, 2021, 461467, (select id from series where hardcover_id = 2839), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Heroes', 'Joe Abercrombie', '9535987143', 'https://assets.hardcover.app/edition/30414689/bbfc3ba04ad783a5d6cfb19cd21b346fa3aab7d6.jpeg', 'Set over three days, "The Heroes"--the new novel by the author of "Best Served Cold"--is about violence and ambition, gruesome deaths and betrayals, and the brutal truth that no plan survives contact with the enemy.', 610, null, 2011, 461560, (select id from series where hardcover_id = 6014), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Season of Storms', 'Andrzej Sapkowski, David   French', '3423260572', 'https://assets.hardcover.app/external_data/60537957/609c6f67ffc6996ff5c488141bcb698dc4e74ee3.jpeg', 'World fantasy award lifetime achievement winner, Andrzej Sapkowski, introduces Geralt of Rivia. a witcher who is one of the few capable of hunting the monsters that prey on humanity. 

A mutant who has the task of killing unnatural beings. He uses magical signs, potions, and the pride of every witcher -- two swords, steel and silver. But, a contract has gone wrong, and Geralt finds himself without his trademark weapons. Now, he needs them back because sorcerers are scheming and across the world clouds are gathering. The season of storms is coming... ', 432, null, 2013, 461967, (select id from series where hardcover_id = 1808), '0.6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Elite', 'Kiera Cass', '8376862456', 'https://assets.hardcover.app/external_data/526289/210b989863440e1a4a0239b797dcb1f9b220934f.jpeg', 'The Selection began with thirty-five girls. Now with the group narrowed down to the six Elite, the competition to win Prince Maxon''s heart is fiercer than ever—and America is still struggling to decide where her heart truly lies. Is it with Maxon, who could make her life a fairy tale? Or with her first love, Aspen?

America is desperate for more time. But the rest of the Elite know exactly what they want—and America''s chance to choose is about to slip away.', 323, null, 2013, 465081, (select id from series where hardcover_id = 1545), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Some Desperate Glory', 'Emily Tesh', '1250293006', 'https://assets.hardcover.app/external_data/61248737/7fba8b5b2bfcb43814a04ea79ac493e2f2c310e4.jpeg', 'Since she was born, Kyr has trained for the day she can avenge the murder of planet Earth. Raised in the bowels of Gaea Station alongside the last scraps of humanity, she readies herself to face the Wisdom, the powerful, reality-shaping weapon that gave the majoda their victory over humanity.

They are what’s left. They are what must survive. Kyr is one of the best warriors of her generation, the sword of a dead planet. When Command assigns her brother to certain death and relegates her to Nursery to bear sons until she dies trying, she knows she must take humanity''s revenge into her own hands.

Alongside her brother’s brilliant but seditious friend and a lonely, captive alien, Kyr escapes from everything she’s known into a universe far more complicated than she was taught and far more wondrous than she could have imagined.', 438, null, 2022, 465106, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Book Eaters', 'Sunyi Dean', '1250810205', 'https://assets.hardcover.app/external_data/261436/535bfc8aeed5dc0639c547e22697994934645bea.jpeg', 'Out on the Yorkshire Moors lives a secret line of people for whom books are food, and who retain all of a book''s content after eating it. To them, spy novels are a peppery snack; romance novels are sweet and delicious. Eating a map can help them remember destinations, and children, when they misbehave, are forced to eat dry, musty pages from dictionaries.

Devon is part of The Family, an old and reclusive clan of book eaters. Her brothers grow up feasting on stories of valor and adventure, and Devon—like all other book eater women—is raised on a carefully curated diet of fairy tales and cautionary stories.

But real life doesn''t always come with happy endings, as Devon learns when her son is born with a rare and darker kind of hunger—not for books, but for human minds.

At the Publisher''s request, this title is being sold without Digital Rights Management Software (DRM) applied.', 304, null, 2022, 465119, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Amazing Adventures of Kavalier & Clay', 'Michael Chabon', '0008229244', 'https://assets.hardcover.app/edition/30385746/96cdd59ef83ad016f0a468bf76f0049bc36ec5da.jpeg', 'A young escape artist and budding magician named Joe Kavalier arrives on the doorstep of his cousin, Sammy Clay. While the long shadow of Hitler falls across Europe, America is happily in thrall to the Golden Age of comic books, and in a distant corner of Brooklyn, Sammy is looking for a way to cash in on the craze. He finds the ideal partner in the aloof, artistically gifted Joe, and together they embark on an adventure that takes them deep into the heart of Manhattan, and the heart of old-fashioned American ambition. From the shared fears, dreams, and desires of two teenage boys, they spin comic book tales of the heroic, fascist-fighting Escapist and the beautiful, mysterious Luna Moth, otherworldly mistress of the night. Climbing from the streets of Brooklyn to the top of the Empire State Building, Joe and Sammy carve out lives, and careers, as vivid as cyan and magenta ink. Spanning continents and eras, this superb book by one of America’s finest writers remains one of the defining novels of our modern American age.', 706, null, 2000, 467910, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Trouble With Peace', 'Joe Abercrombie', '8073324687', 'https://assets.hardcover.app/edition/30633353/afb3baf4f7df86b01b93e69276cb180cefd7aa5b.jpeg', 'Despite the peace, unrest snakes through each layer of society, the Breakers still lurk in the shadows, and Orso struggles to find a path through the maze of politics.', 512, null, 2020, 468114, (select id from series where hardcover_id = 2839), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Call of Cthulhu', 'H. P. Lovecraft', '5389208528', 'https://assets.hardcover.app/external_data/26903847/9c2811e93a3bd561cbd584348f17c1dc833ebb9a.jpeg', 'Lovecraft is considered by many as the creator of the modern horror story. In his macabre tales, demonic spirits, terrifying rites, ancient curses and aliens meet in rural New England. The Call of Cthulhu is one of his best and most famous works.', 64, null, 1926, 468787, (select id from series where hardcover_id = 56583), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Cartographers', 'Peng Shepherd', '1398705438', 'https://assets.hardcover.app/edition/30391832/4bb0181188deca12ac218c909ecc532743a141f0.jpeg', 'What is the purpose of a map?

Nell Young’s whole life and greatest passion is cartography. Her father, Dr. Daniel Young, is a legend in the field and Nell’s personal hero. But she hasn’t seen or spoken to him ever since he cruelly fired her and destroyed her reputation after an argument over an old, cheap gas station highway map.

But when Dr. Young is found dead in his office at the New York Public Library, with the very same seemingly worthless map hidden in his desk, Nell can’t resist investigating. To her surprise, she soon discovers that the map is incredibly valuable and exceedingly rare. In fact, she may now have the only copy left in existence... because a mysterious collector has been hunting down and destroying every last one—along with anyone who gets in the way.

But why?

To answer that question, Nell embarks on a dangerous journey to reveal a dark family secret and discovers the true power that lies in maps...

From the critically acclaimed author of The Book of M, a highly imaginative thriller about a young woman who discovers that a strange map in her deceased father’s belongings holds an incredible, deadly secret—one that will lead her on an extraordinary adventure and to the truth about her family’s dark history.', 400, null, 2021, 470914, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Maidens', 'Alex Michaelides', '125082754X', 'https://assets.hardcover.app/external_data/40674758/285064a5ee4ea66d200f1e35d336cc714aa85fad.jpeg', '"Alex Michaelides’s long-awaited next novel, ''The Maidens,'' is finally here...the premise is enticing and the elements irresistible."
—The New York Times

"A deliciously dark, elegant, utterly compulsive read—with a twist that blew my mind. I loved this even more than I loved The Silent Patient and that''s saying something!"
—Lucy Foley, New York Times bestselling author of The Guest List

From the #1 New York Times bestselling author of The Silent Patient comes a spellbinding tale of psychological suspense, weaving together Greek mythology, murder, and obsession, that further cements “Michaelides as a major player in the field” (Publishers Weekly).

Edward Fosca is a murderer. Of this Mariana is certain. But Fosca is untouchable. A handsome and charismatic Greek tragedy professor at Cambridge University, Fosca is adored by staff and students alike—particularly by the members of a secret society of female students known as The Maidens.

Mariana Andros is a brilliant but troubled group therapist who becomes fixated on The Maidens when one member, a friend of Mariana’s niece Zoe, is found murdered in Cambridge.

Mariana, who was once herself a student at the university, quickly suspects that behind the idyllic beauty of the spires and turrets, and beneath the ancient traditions, lies something sinister. And she becomes convinced that, despite his alibi, Edward Fosca is guilty of the murder. But why would the professor target one of his students? And why does he keep returning to the rites of Persephone, the maiden, and her journey to the underworld?

When another body is found, Mariana’s obsession with proving Fosca’s guilt spirals out of control, threatening to destroy her credibility as well as her closest relationships. But Mariana is determined to stop this killer, even if it costs her everything—including her own life.', 336, null, 2021, 474446, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dead Silence', 'S.A. Barnes', '3453322932', 'https://assets.hardcover.app/external_data/59451041/0e6002316ffc12bc9f57a4600c2b52667bd04c07.jpeg', 'Titanic meets The Shining in S.A. Barnes’ Dead Silence, a SF horror novel in which a woman and her crew board a decades-lost luxury cruiser and find the wreckage of a nightmare that hasn''t yet ended.

A GHOST SHIP.
A SALVAGE CREW.
UNSPEAKABLE HORRORS.

Claire Kovalik is days away from being unemployed—made obsolete—when her beacon repair crew picks up a strange distress signal. With nothing to lose and no desire to return to Earth, Claire and her team decide to investigate.

What they find at the other end of the signal is a shock: the Aurora, a famous luxury space-liner that vanished on its maiden tour of the solar system more than twenty years ago. A salvage claim like this could set Claire and her crew up for life. But a quick trip through the Aurora reveals something isn’t right.

Whispers in the dark. Flickers of movement. Words scrawled in blood. Claire must fight to hold onto her sanity and find out what really happened on the Aurora, before she and her crew meet the same ghastly fate.', 343, null, 1996, 475184, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Children of Hurin', 'J.R.R. Tolkien, Christopher Tolkien', '3608937625', 'https://assets.hardcover.app/editions/30413609/8649859672067284.jpg', 'The ‘Great Tale’ of The Children of Húrin, set during the legendary time before The Lord of the Rings. Morgoth, the first Dark Lord, dwells in the vast fortress of Angband in the North; and within the shadow of the fear of Angband, and the war waged by Morgoth against the Elves, the fates of Turin and his sister Nienor will be tragically entwined. Their brief and passionate lives are dominated by the elemental hatred that Morgoth bears them as the children of Hurin, the man who dared to defy him to his face. Against them Morgoth sends his most formidable servant, Glaurung, a powerful spirit in the form of a huge wingless dragon of fire. Sardonic and mocking, Glaurung manipulates the fates of Turin and Nienor by lies of diabolic cunning and guile, in an attempt to fulfil the curse of Morgoth.', 320, null, 2001, 477791, (select id from series where hardcover_id = 11399), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Howling Dark', 'Christopher Ruocchio', '0756419271', 'https://assets.hardcover.app/edition/30421404/09f7ec3d-b221-43ec-be46-f287c4c0da46.jpeg', 'Hadrian Marlowe is lost.

For half a century, he has searched the farther suns for the lost planet of Vorgossos, hoping to find a way to contact the elusive alien Cielcin. He has not succeeded, and for years has wandered among the barbarian Normans as captain of a band of mercenaries.

Determined to make peace and bring an end to nearly 400 years of war, Hadrian must venture beyond the security of the Sollan Empire and among the Extrasolarians who dwell between the stars. There, he will face not only the aliens he has come to offer peace, but contend with creatures that once were human, with traitors in his midst, and with a meeting that will bring him face to face with no less than the oldest enemy of mankind.

If he succeeds, he will usher in a peace unlike any in recorded history. If he fails...the galaxy will burn.', 688, null, 2019, 481417, (select id from series where hardcover_id = 6522), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Remarkably Bright Creatures', 'Shelby Van Pelt', '0063204177', 'https://assets.hardcover.app/external_data/59469142/340246db2f5b43b566a8dfc27887bb13301ca4cd.jpeg', 'After Tova Sullivan''s husband died, she began working the night shift at the Sowell Bay Aquarium, mopping floors and tidying up. Keeping busy has always helped her cope, which she''s been doing since her eighteen-year-old son, Erik, mysteriously vanished on a boat in Puget Sound over thirty years ago.

Tova becomes acquainted with curmudgeonly Marcellus, a giant Pacific octopus living at the aquarium. Marcellus knows more than anyone can imagine but wouldn''t dream of lifting one of his eight arms for his human captors--until he forms a remarkable friendship with Tova.

Ever the detective, Marcellus deduces what happened the night Tova''s son disappeared. And now Marcellus must use every trick his old invertebrate body can muster to unearth the truth for her before it''s too late.

Shelby Van Pelt''s debut novel is a gentle reminder that sometimes taking a hard look at the past can help uncover a future that once felt impossible.', 360, null, 2022, 481892, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Villains Duology', 'V. E. Schwab', '9123918381', 'https://assets.hardcover.app/edition/30447202/5b70a95f4c16a076adaee9462926fa48124eebe3.jpeg', 'V. E. Schwab''s New York Times bestselling Villains duology, now in a boxed set along with a gorgeous double-sided poster! In the Villains duology (Vicious, Vengeful) V. E. Schwab brings to life a gritty comic-book-style world in vivid prose: a world where gaining superpowers doesn''t automatically lead to heroism, and a time when allegiances are called into question. A dynamic and original twist on what it means to be a hero and a villain. A killer from page one...highly recommended! --Jonathan Maberry, New York Times bestselling author of Marvel Universe vs The Avengers and Patient Zero', 944, null, 2018, 498225, (select id from series where hardcover_id = 2426), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Golem and the Djinni', 'Helene Wecker', '0062110837', 'https://assets.hardcover.app/editions/30447801/8e9cdf10-c45f-4b5d-a4ea-3242ee65b1ac.jpg', 'Chava is a golem, a creature made of clay, brought to life by a disgraced rabbi who dabbles in dark Kabbalistic magic, created to be the wife of a man who dies at sea on the voyage from Poland. Chava is unmoored and adrift as the ship arrives in New York harbor in 1899.

Ahmad is a jinni, a being of fire born in the ancient Syrian desert, trapped in an old copper flask, and released in New York City, though still not entirely free.

Ahmad and Chava become unlikely friends and soul mates with a mystical connection. Marvelous and compulsively readable, Helene Wecker''s debut novel The Golem and the Jinni weaves strands of Yiddish and Middle Eastern literature, historical fiction and magical fable, into a wondrously inventive and unforgettable tale.', 656, null, 2013, 498604, (select id from series where hardcover_id = 20603), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Study in Drowning', 'Ava Reid', '9895771843', 'https://assets.hardcover.app/edition/31887199/3eb05027146a00d8c1f7a4bb3c52e411be960256.jpeg', 'Effy Sayre has always believed in fairy tales. Haunted by visions of the Fairy King since childhood, she’s had no choice. Her tattered copy of Angharad—Emrys Myrddin’s epic about a mortal girl who falls in love with the Fairy King, then destroys him—is the only thing keeping her afloat. So when Myrddin’s family announces a contest to redesign the late author’s estate, Effy feels certain it’s her destiny.

But musty, decrepit Hiraeth Manor is an impossible task, and its residents are far from welcoming. Including Preston Héloury, a stodgy young literature scholar determined to expose Myrddin as a fraud. As the two rivals piece together clues about Myrddin’s legacy, dark forces, both mortal and magical, conspire against them—and the truth may bring them both to ruin.

Part historical fantasy, part rivals-to-lovers romance, part Gothic mystery, and all haunting, dreamlike atmosphere, Ava Reid''s powerful YA debut will lure in readers who loved The Atlas Six, House of Salt and Sorrows, or Girl, Serpent, Thorn.', 378, null, 2023, 503761, (select id from series where hardcover_id = 122590), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Haunting Adeline', 'H. D. Carlton', '6581238112', 'https://assets.hardcover.app/editions/30457494/2004678148140760.jpg', '"For Adeline Reilly, moving back to Seattle was supposed to be the perfect fresh start. With her flourishing career as an author, and the inheritance of her late grandmother’s gothic mansion, there is nothing to stand in her way.
But Adeline isn’t alone in Parson’s Manor.
It isn’t the angry souls haunting the hallways of her childhood home that Adeline fears–it’s the mysterious break-ins, roses appearing, and threatening messages that somehow sound more like eerie promises.
Adeline has a stalker.
Yet, she quickly discovers she’s not the first person in her family to fall victim to a shadow in pursuit.
Left behind are her great-grandmother’s haunting journals detailing the story of her own phantom, and subsequently, her brutal murder.
Parson’s Manor now holds more than just Adeline’s memories—it houses a grim future that could lead to history repeating itself.
If she doesn’t fall in love with her stalker first."-- Provided by Amazon', 549, null, 2021, 506421, (select id from series where hardcover_id = 65036), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Measure', 'Nikki Erlick, Julia Whelan', '2265156582', 'https://assets.hardcover.app/external_data/61201034/85e514124fac12791c47ce6d4b9e7bb15383743e.jpeg', 'Eight ordinary people. One extraordinary choice.

It seems like any other day. You wake up, pour a cup of coffee, and head out.

But today, when you open your front door, waiting for you is a small wooden box. This box holds your fate inside: the answer to the exact number of years you will live.

From suburban doorsteps to desert tents, every person on every continent receives the same box. In an instant, the world is thrust into a collective frenzy. Where did these boxes come from? What do they mean? Is there truth to what they promise?

As society comes together and pulls apart, everyone faces the same shocking choice: Do they wish to know how long they’ll live? And, if so, what will they do with that knowledge?

The Measure charts the dawn of this new world through an unforgettable cast of characters whose decisions and fates interweave with one another: best friends whose dreams are forever entwined, pen pals finding refuge in the unknown, a couple who thought they didn’t have to rush, a doctor who cannot save himself, and a politician whose box becomes the powder keg that ultimately changes everything. Eight ordinary people. One extraordinary choice.

It seems like any other day. You wake up, pour a cup of coffee, and head out.

But today, when you open your front door, waiting for you is a small wooden box. This box holds your fate inside: the answer to the exact number of years you will live.

From suburban doorsteps to desert tents, every person on every continent receives the same box. In an instant, the world is thrust into a collective frenzy. Where did these boxes come from? What do they mean? Is there truth to what they promise?

As society comes together and pulls apart, everyone faces the same shocking choice: Do they wish to know how long they’ll live? And, if so, what will they do with that knowledge?

The Measure charts the dawn of this new world through an unforgettable cast of characters whose decisions and fates interweave with one another: best friends whose dreams are forever entwined, pen pals finding refuge in the unknown, a couple who thought they didn’t have to rush, a doctor who cannot save himself, and a politician whose box becomes the powder keg that ultimately changes everything.', null, null, 2022, 507180, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lightlark', 'Alex Aster, Suzy Jackson', '9798885786676', 'https://assets.hardcover.app/external_data/60505030/6bcc3a72b8563ad05352ca8d7b2df7f324a76e7a.jpeg', '"Every 100 years, the island of Lightlark appears to host the Centennial, a deadly game that only the rulers of six realms are invited to play. The invitation is a summons—a call to embrace victory and ruin, baubles and blood.

The Centennial offers the six rulers one final chance to break the curses that have plagued their realms for centuries. Each ruler has something to hide. Each realm’s curse is uniquely wicked. To destroy the curses, one ruler must die.

Isla Crown is the young ruler of Wildling—a realm of temptresses cursed to kill anyone they fall in love with. They are feared and despised, and are counting on Isla to end their suffering by succeeding at the Centennial.

To survive, Isla must lie, cheat, and betray…even as love complicates everything."-- Provided by Amazon', null, null, 2022, 507196, (select id from series where hardcover_id = 58256), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wrong Place Wrong Time', 'Gillian McAllister', '0241520940', 'https://assets.hardcover.app/external_data/61208165/023d2820c923a090367c49681ffbb516994cc012.jpeg', 'It is midnight on the morning of Halloween, and Jen anxiously waits up for her 18-year-old son, Todd, to return home. But worries about his broken curfew transform into something much more dangerous when Todd finally emerges from the darkness. As Jen watches through the window, she sees her funny, seemingly happy teenage son stab a total stranger.

She doesn’t know who the victim is, or why Todd has committed such a devastating act of violence. All she knows is that her life, and Todd’s, have been shattered. 

After her son is taken into custody, Jen falls asleep in despair. But when she wakes up…it is yesterday. The murder has not happened yet—and there may be a chance to stop it. Each morning, when Jen wakes, she is further back in the past, first weeks, then years, before the murder. And Jen realizes that somewhere in the past lies the trigger for Todd’s terrible crime…and it is her mission to find it, and prevent it from taking place.

Both the story of a mother’s love and the sacrifices she will make for her child, and a thriller with a brilliant twist, Wrong Place Wrong Time is a one-of-a-kind novel that begs to be read in one sitting.', 408, null, 2022, 512236, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('How to Sell a Haunted House', 'Grady Hendrix', '1803361646', 'https://assets.hardcover.app/edition/30468218/a56940278da65eecfb9a6310d8d33757c3f3351e.jpeg', 'New York Times bestselling author Grady Hendrix takes on the haunted house in a thrilling new novel that explores the way your past—and your family—can haunt you like nothing else.
 
When Louise finds out her parents have died, she dreads going home. She doesn’t want to leave her daughter with her ex and fly to Charleston. She doesn’t want to deal with her family home, stuffed to the rafters with the remnants of her father’s academic career and her mother’s lifelong obsession with puppets and dolls. She doesn’t want to learn how to live without the two people who knew and loved her best in the world.
 
Most of all, she doesn’t want to deal with her brother, Mark, who never left their hometown, gets fired from one job after another, and resents her success. Unfortunately, she’ll need his help to get the house ready for sale because it’ll take more than some new paint on the walls and clearing out a lifetime of memories to get this place on the market.
 
But some houses don’t want to be sold, and their home has other plans for both of them…
 
Like his novels The Southern Book Club’s Guide to Slaying Vampires and The Final Girl Support Group, How to Sell a Haunted House is classic Hendrix: equal parts heartfelt and terrifying—a gripping new read from “the horror master” (USA Today).', 430, null, 2022, 515619, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Island of Doctor Moreau', 'H. G. Wells', '0575074779', 'https://assets.hardcover.app/edition/30471995/c9948e477fcddf60a184c88f603ac45b4223a6ec.jpeg', 'Ranked among the classic novels of the English language and the inspiration for several unforgettable movies, this early work of H. G. Wells was greeted in 1896 by howls of protest from reviewers, who found it horrifying and blasphemous. They wanted to know more about the wondrous possibilities of science shown in his first book, The Time Machine, not its potential for misuse and terror. In The Island of Dr. Moreau, a shipwrecked gentleman named Edward Prendick, stranded on a Pacific island lorded over by the notorious Dr. Moreau, confronts dark secrets, strange creatures, and a reason to run for his life.

While this riveting tale was intended to be a commentary on evolution, divine creation, and the tension between human nature and culture, modern readers familiar with genetic engineering will marvel at Wells’s prediction of the ethical issues raised by producing “smarter” human beings or bringing back extinct species. These levels of interpretation add a richness to Prendick’s adventures on Dr. Moreau’s island of lost souls without distracting from what is still a rip-roaring good read.', 176, null, 1896, 519013, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mountain in the Sea', 'Ray Nayler', '0374605955', 'https://assets.hardcover.app/book/527367/639130df-b559-48e1-9f09-aebfeaaed664.jpeg', 'The transnational tech corporation DIANIMA has sealed off the remote Con Dao Archipelago, where a species of octopus has been discovered that may have developed its own language and culture. The marine biologist Dr. Ha Nguyen, who has spent her life researching cephalopod intelligence, will do anything for the chance to study them. She travels to the islands to join DIANIMA’s team: a battle-scarred securityagent and the world’s first (and possibly last) android.

The octopuses hold the key to unprecedented breakthroughs in extrahuman intelligence. As Dr. Nguyen struggles to communicate with the newly discovered species, forces larger than DIANIMA close in to seize the octopuses for themselves.

But no one has yet asked the octopuses what they think. Or what they might do about it.

A near-future thriller, a meditation on the nature of consciousness, and an eco-logical call to arms, Ray Nayler’s dazzling literary debut The Mountain in the Sea is a mind-blowing dive into the treasure and wreckage of humankind’s legacy.', 420, null, 2022, 527367, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Day of Fallen Night', 'Samantha Shannon', '1635577926', 'https://assets.hardcover.app/edition/30503606/5901bbb27a4f14fd41baec66f29be613bb9a633f.jpeg', 'In A Day of Fallen Night, Samantha Shannon sweeps readers back to the universe of Priory of the Orange Tree and into the lives of four women, showing us a course of events that shaped their world for generations to come.

Tunuva Melim is a sister of the Priory. For fifty years, she has trained to slay wyrms – but none have appeared since the Nameless One, and the younger generation is starting to question the Priory''s purpose.

To the north, in the Queendom of Inys, Sabran the Ambitious has married the new King of Hróth, narrowly saving both realms from ruin. Their daughter, Glorian, trails in their shadow – exactly where she wants to be.

The dragons of the East have slept for centuries. Dumai has spent her life in a Seiikinese mountain temple, trying to wake the gods from their long slumber. Now someone from her mother''s past is coming to upend her fate.

When the Dreadmount erupts, bringing with it an age of terror and violence, these women must find the strength to protect humankind from a devastating threat.', 881, null, 2023, 546429, (select id from series where hardcover_id = 17180), '0') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Starling House', 'Alix E. Harrow', '1250882788', 'https://assets.hardcover.app/edition/30590591/74b1cf39df7c9286b234647e92f89057ca9402fd.jpeg', 'I dream sometimes about a house I’ve never seen….

Opal is a lot of things―orphan, high school dropout, full-time cynic and part-time cashier―but above all, she''s determined to find a better life for her younger brother Jasper. One that gets them out of Eden, Kentucky, a town remarkable for only two things: bad luck and E. Starling, the reclusive nineteenth century author of The Underland, who disappeared over a hundred years ago.

All she left behind were dark rumors―and her home. Everyone agrees that it’s best to ignore the uncanny mansion and its misanthropic heir, Arthur. Almost everyone, anyway.

I should be scared, but in the dream I don’t hesitate.

Opal has been obsessed with The Underland since she was a child. When she gets the chance to step inside Starling House―and make some extra cash for her brother''s escape fund―she can''t resist.

But sinister forces are digging deeper into the buried secrets of Starling House, and Arthur’s own nightmares have become far too real. As Eden itself seems to be drowning in its own ghosts, Opal realizes that she might finally have found a reason to stick around.

In my dream, I’m home.

And now she’ll have to fight.

Welcome to Starling House: enter, if you dare.', 392, null, 2023, 617030, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Godkiller', 'Hannah Kaner', '6256411676', 'https://assets.hardcover.app/edition/30705350/514f60935b57bb61f2aa02d3e9cc9ba725a3ef6e.jpeg', 'Kissen’s family were killed by zealots of a fire god. Now, she makes a living killing gods, and enjoys it. That is until she finds a god she cannot kill: Skedi, a god of white lies, has somehow bound himself to a young noble, and they are both on the run from unknown assassins.
 
Joined by a disillusioned knight on a secret quest, they must travel to the ruined city of Blenraden, where the last of the wild gods reside, to each beg a favour.
 
Pursued by demons, and in the midst of burgeoning civil war, they will all face a reckoning – something is rotting at the heart of their world, and only they can be the ones to stop it.', 304, null, 2023, 617060, (select id from series where hardcover_id = 115319), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Holly', 'Stephen King', '1668014947', 'https://assets.hardcover.app/external_data/59174872/6f0ce6a7711abca7c6decf84b739e5ebe22b56b6.jpeg', 'When Penny Dahl calls the Finders Keepers detective agency, hoping for help locating her missing daughter, Holly Gibney is reluctant to accept the case. Her partner, Pete, has Covid. Her (very complicated) mother has just passed away. And Holly is meant to be on leave. But something in Penny’s desperate voice makes it impossible to turn her down.

Meanwhile, mere blocks from where Bonnie Dahl disappeared live Professors Rodney and Emily Harris. They are the picture of bourgeois respectability: married octogenarians, devoted to each other, and semi-retired lifelong academics. But they are also harboring a shocking, unholy secret in the basement of their well-kept, book-lined home, one that may be related to Bonnie’s disappearance. And it will prove nearly impossible to discover what they are up to…for they are savvy, they are patient, and they are ruthless. Now Holly must summon all of her formidable talents to outthink and outmaneuver these unimaginably depraved and brilliantly disguised adversaries in this chilling and unforgettable masterwork from Stephen King.', 474, null, 2023, 633384, (select id from series where hardcover_id = 5531), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Two Twisted Crowns', 'Rachel Gillig', '0316312886', 'https://assets.hardcover.app/external_data/61236890/72f0738a5c403dcc92bce62a3c2ee10dd9aa199e.jpeg', 'In the luscious, dark sequel to One Dark Window, Elspeth must face the consequences of what she’s wrought – perfect for readers of Hannah Whitten’s For the Wolf and Alexis Henderson’s The Year of the Witching

Elspeth and Ravyn have gathered most of the twelve Providence Cards, but the last, and most important one remains to be found: The Twin Alders.

If they are going to find it before the Solstice and cure the kingdom of the dark magic infecting it, they will need to journey beyond the dangerous mist-cloaked forest that surrounds their kingdom.

And the only one who can lead them there is the monster that shares Elspeth’s head. The Nightmare. And he’s not eager to share any longer.', 465, null, 2023, 674917, (select id from series where hardcover_id = 36763), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Heartless Hunter', 'Kristen Ciccarelli', '0008650608', 'https://assets.hardcover.app/editions/30731497/6833034835950607.jpg', '"Now, in the aftermath of a devastating revolution, witches have been diminished from powerful rulers to outcasts ruthlessly hunted due to their waning magic, and Rune must hide what she is.

Spending her days pretending to be nothing more than a vapid young socialite, Rune spends her nights as the Crimson Moth, a witch vigilante who rescues her kind from being purged. When a rescue goes wrong, she decides to throw the witch hunters off her scent and gain the intel she desperately needs by courting the handsome Gideon Sharpe - a notorious and unforgiving witch hunter loyal to the revolution - who she can''t help but find herself falling for.

Gideon loathes the decadence and superficiality Rune represents, but when he learns the Crimson Moth has been using Rune’s merchant ships to smuggle renegade witches out of the republic, he inserts himself into her social circles by pretending to court her right back. He soon realizes that beneath her beauty and shallow façade, is someone fiercely intelligent and tender who feels like his perfect match. Except, what if she’s the very villain he’s been hunting?"-- Provided by Amazon', 416, null, 2024, 735422, (select id from series where hardcover_id = 65624), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Unmaking of June Farrow', 'Adrienne Young', '9780593598672', 'https://assets.hardcover.app/external_data/140899/96abb6738f6d3e4460351f81c634b2aa9f3b8d57.jpeg', 'In the small mountain town of Jasper, North Carolina, June Farrow is waiting for fate to find her. The Farrow women are known for their thriving flower farm—and the mysterious curse that has plagued their family line. The whole town remembers the madness that led to Susanna Farrow’s disappearance, leaving June to be raised by her grandmother and haunted by rumors.

It’s been a year since June started seeing and hearing things that weren’t there. Faint wind chimes, a voice calling her name, and a mysterious door appearing out of nowhere—the signs of what June always knew was coming. But June is determined to end the curse once and for all, even if she must sacrifice finding love and having a family of her own.

After her grandmother’s death, June discovers a series of cryptic clues regarding her mother’s decades-old disappearance, except they only lead to more questions. But could the door she once assumed was a hallucination be the answer she’s been searching for? The next time it appears, June realizes she can touch it and walk past the threshold. And when she does, she embarks on a journey that will not only change both the past and the future, but also uncover the lingering mysteries of her small town and entangle her heart in an epic star-crossed love.

With The Unmaking of June Farrow, Adrienne Young delivers a brilliant novel of romance, mystery, and a touch of the impossible—a story you will never forget.

', 320, null, 2023, 746655, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Emily Wilde’s Map of the Otherlands', 'Heather Fawcett', '035651918X', 'https://assets.hardcover.app/editions/30763999/4181576994647947.jpg', 'Emily Wilde is a genius scholar of faerie folklore—she just wrote the world’s first comprehensive of encylopaedia of faeries. She’s learned many of the secrets of the Hidden Folk on her adventures . . . and also from her fellow scholar and former rival, Wendell Bambleby. 

Because Bambleby is more than infuriatingly charming. He’s an exiled faerie king on the run from his murderous mother, and in search of a door back to his realm. So despite Emily’s feelings for Bambleby, she’s not ready to accept his proposal of marriage: Loving one of the Fair Folk comes with secrets and danger. And she also has a new project to focus on: a map of the realms of faerie. 

While she is preparing her research, Bambleby lands her in trouble yet again, when assassins sent by Bambleby’s mother invade Cambridge. Now Bambleby and Emily are on another adventure, this time to the picturesque Austrian Alps, where Emily believes they may find the door to Bambley’s realm, and the key to freeing him from his family’s dark plans. But with new relationships for the prickly Emily to navigate and dangerous Folk lurking in every forest and hollow, Emily must unravel the mysterious workings of faerie doors, and of her own heart.', 352, null, 2004, 763446, (select id from series where hardcover_id = 32465), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ficciones', 'Jorge Luis Borges', '0141183845', 'https://assets.hardcover.app/edition/27607251/07db65332612e3640198ac30d6e6c6e600aa0a5f.jpeg', 'A collection of his short stories in which Borges often uses the labyrinth as a literary device to expound his ideas on all aspects of human life and endeavor.


----------
Contains:
[Tlön, Uqbar, Orbis Tertius](https://openlibrary.org/works/OL444914W)', 192, null, 1944, 777120, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Battle Royale', 'Koushun Takami, Urszula Knap, Maciej Kamuda', '156931778X', 'https://assets.hardcover.app/edition/30853870/b9479560-b7d2-45b1-90e8-dc782fbd9413.jpg', 'Koushun Takami''s notorious high-octane thriller is based on an irresistible premise: a class of junior high school students is taken to a deserted island where, as part of a ruthless authoritarian program, they are provided arms and forced to kill one another until only one survivor is left standing. Criticized as violent exploitation when first published in Japan - where it then proceeded to become a runaway bestseller - Battle Royale is a Lord of the Flies for the 21st century, a potent allegory of what it means to be young and (barely) alive in a dog-eat-dog world. Made into a controversial hit movie of the same name, Battle Royale is already a contemporary Japanese pulp classic, now available for the first time in the English language.', 772, null, 1999, 833733, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Saga, Vol. 2', 'Fiona Staples, Brian K. Vaughan', '0606351795', 'https://assets.hardcover.app/edition/9524216/537161e56962bb2b7eb682ed463c149d0eac4885.jpeg', 'After battling assassins, rampaging armies, and aliens, little Hazel faces something truly frightening--her grandparents.', 144, null, 2013, 844795, (select id from series where hardcover_id = 5476), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fragile Threads of Power', 'V. E. Schwab', '1250333962', 'https://assets.hardcover.app/editions/31755061/73874cbe-fd5a-4257-bb38-43f52a882409.jpg', 'Once there were four worlds, nestled like pages in a book, each pulsing with fantastical power and connected by a single city: London.

After a desperate attempt to prevent corruption and ruin in the four Londons, there are only three:
● Grey London, thriving but barely able to remember its magical heritage
● Red London, ruled lately by the Maresh family, flourishing and powerful
● White London, left to brutality and decay

Now the worlds are going to collide anew—brought to a dangerous precipice by the discoveries of three remarkable magicians.

There''s Kosika, the child queen of White London, who has nourished her city on blood and dreams—and whose growing devotion to both is leading her down a dangerous path.

Then there''s Delilah Bard, born a thief in Grey London, who crossed the worlds to become a legend far from there. She''s an infamous magician, a devious heroine, and a risk-taking rogue, all rolled into one unforgettable package. Having disappeared to seek new adventure, an old favor now calls Lila back to a dangerous port, to join some old friends who need more help than they realize.

Last there is Tes, a young runaway with an unusual and powerful ability, hiding out in Red London while trying to stay out of the limelight.

Tes is the only one who can keep all the worlds from unraveling—if she manages to stay alive first.', 664, null, 2022, 883645, (select id from series where hardcover_id = 7607), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Murder at the End of the World', 'Stuart Turton', '1526634910', 'https://assets.hardcover.app/external_data/885699/4be5f0a3f4e98c3b71e5405c09fe9aea4319b17d.jpeg', 'From the bestselling author of The 7 1/2 Deaths of Evelyn Hardcastle and The Devil and the Dark Water comes an inventive, high-concept murder mystery: an ingenious puzzle, an extraordinary backdrop, and an audacious solution.

Solve the murder to save what''s left of the world.

Outside the island there is nothing: the world was destroyed by a fog that swept the planet, killing anyone it touched.

On the island: it is idyllic. One hundred and twenty-two villagers and three scientists, living in peaceful harmony. The villagers are content to fish, farm and feast, to obey their nightly curfew, to do what they''re told by the scientists.

Until, to the horror of the islanders, one of their beloved scientists is found brutally stabbed to death. And then they learn that the murder has triggered a lowering of the security system around the island, the only thing that was keeping the fog at bay. If the murder isn''t solved within 107 hours, the fog will smother the island―and everyone on it.

But the security system has also wiped everyone''s memories of exactly what happened the night before, which means that someone on the island is a murderer―and they don''t even know it.

And the clock is ticking.', 368, null, 2024, 965786, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Sorceress Comes to Call', 'T. Kingfisher', '1250351308', 'https://assets.hardcover.app/external_data/61145943/f6791eab91fe28b2fe7178c1ff55fd240534352e.jpeg', '*The hardcover edition features a foil stamp on the casing and custom endpapers illustrated by the author.*

Cordelia knows her mother is . . . unusual. Their house doesn’t have any doors between rooms—there are no secrets in this house—and her mother doesn''t allow Cordelia to have a single friend. Unless you count Falada, her mother''s beautiful white horse. The only time Cordelia feels truly free is on her daily rides with him.

But more than simple eccentricity sets her mother apart. Other mothers don’t force their daughters to be silent and motionless for hours, sometimes days, on end. Other mothers aren’t evil sorcerers.

When her mother unexpectedly moves them into the manor home of a wealthy older Squire and his kind but keen-eyed sister, Hester, Cordelia knows this welcoming pair are to be her mother''s next victims. But Cordelia feels at home for the very first time among these people, and as her mother''s plans darken, she must decide how to face the woman who raised her to save the people who have become like family.', 322, null, 2024, 969046, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Somewhere Beyond the Sea', 'TJ Klune', '3453323335', 'https://assets.hardcover.app/editions/31019620/7396225421748550.jpg', 'Arthur Parnassus lives a good life, built on the ashes of a bad one. He’s the headmaster of a strange orphanage on a distant and peculiar island, and he hopes to soon be the adoptive father to the six magical and so-called dangerous children who live there.

Arthur works hard and loves with his whole heart so none of the children ever feel the neglect and pain that he once felt as an orphan on that very same island so long ago. And he is not alone: joining him is the love of his life, Linus Baker, a former caseworker in the Department in Charge of Magical Youth; Zoe Chapelwhite, the island’s sprite; and her girlfriend, Mayor Helen Webb. Together, they will do anything to protect the children.

But when Arthur is summoned to make a public statement about his dark past, he finds himself at the helm of a fight for the future that his family, and all magical people, deserve.

And when a new magical child hopes to join them on their island home―one who finds power in calling himself monster, a name Arthur worked so hard to protect his children from―Arthur knows they’re at a breaking point: their family will either grow stronger than ever or fall apart.

Welcome back to Marsyas Island. This is Arthur’s story.

Somewhere Beyond the Sea is a story of resistance, lovingly told, about the daunting experience of fighting for the life you want to live and doing the work to keep it.', 416, null, 2024, 994867, (select id from series where hardcover_id = 119124), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Naturals', 'Jennifer Lynn Barnes', '6585348443', 'https://assets.hardcover.app/editions/31066835/4275430027698144.jpeg', '"Piecing together the tiniest details, she can tell you who you are and what you want. But, it''s not a skill that she''s ever taken seriously. That is, until the FBI come knocking: they''ve begun a classified program that uses exceptional teenagers to crack infamous cold cases, and they need Cassie.

What Cassie doesn''t realize is that there''s more at risk than a few unsolved homicides-especially when she''s sent to live with a group of teens whose gifts are as unusual as her own. Soon, it becomes clear that no one in the Naturals program is what they seem. And when a new killer strikes, danger looms close. Caught in a lethal game of cat and mouse with a killer, the Naturals are going to have to use all of their gifts just to survive."-- Provided by Amazon', 308, null, 2013, 1042511, (select id from series where hardcover_id = 3336), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Service Model', 'Adrian Tchaikovsky', '1250290287', 'https://assets.hardcover.app/edition/31094415/2127458c01e65aa244a45258f644275eee234064.jpeg', 'Murderbot meets Redshirts in a delightfully humorous tale of robotic murder from the Hugo-nominated author of Elder Race and Children of Time.

To fix the world they must first break it, further.

Humanity is a dying breed, utterly reliant on artificial labor and service.

When a domesticated robot gets a nasty little idea downloaded into its core programming, they murder their owner. The robot discovers they can also do something else they never did before: They can run away.

Fleeing the household they enter a wider world they never knew existed, where the age-old hierarchy of humans at the top is disintegrating into ruins and an entire robot ecosystem devoted to human wellbeing is having to find a new purpose.

Sometimes all it takes is a nudge to overcome the limits of your programming.', 373, null, 2024, 1070337, (select id from series where hardcover_id = 180625), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Compulsory', 'Martha Wells', '1645241726', 'https://assets.hardcover.app/editions/31107018/3703183372715204.jpg', 'While trying to watch episode 44 of The Rise and Fall of Sanctuary Moon, Murderbot is—again, what is it with humans?—distracted by something that is technically outside its purview. A miner is suddenly in danger following a pointless (to Murderbot’s way of thinking) argument, and the choice is to risk discovery and leap into action, which would require hitting the pause button during a very exciting part of SanctuaryMoon, or to follow orders and stay still.

This is a tougher choice than it seems. But then, when has Murderbot ever been faced with an easy choice?', 15, null, 2018, 1082982, (select id from series where hardcover_id = 1053), '0.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Book of Doors', 'Gareth  Brown', '2383992100', 'https://assets.hardcover.app/edition/31992450/f8e9dc699f064f0c5bfe8fd7872384b59b5d6a3d.jpeg', 'Cassie Andrews works in a New York City bookshop, shelving books, making coffee for customers, and living an unassuming, ordinary life. Until the day one of her favorite customers—a lonely yet charming old man—dies right in front of her. Cassie is devastated. She always loved his stories, and now she has nothing to remember him by. Nothing but the last book he was reading.

But this is no ordinary book…

It is the Book of Doors.

Inscribed with enigmatic words and mysterious drawings, it promises Cassie that any door is every door. You just need to know how to open them.

Then she’s approached by a gaunt stranger in a rumpled black suit with a Scottish brogue who calls himself Drummond Fox. He’s a librarian who keeps watch over a unique set of rare volumes. The tome now in Cassie’s possession is not the only book with great power, but it is the one most coveted by those who collect them.

Now, Cassie is being hunted by those few who know of the Special Books. With only her roommate, Izzy, to confide in, she has to decide if she will help the mysterious and haunted Drummond protect the Book of Doors—and the other books in his secret library’s care—from those who will do evil. Because only Drummond knows where the unique library is, and only Cassie’s book can get them there.

But there are those willing to kill to obtain those secrets. And a dark force—in the form of a shadowy, sadistic woman—is at the very top of that list.

A debut novel full of magic, adventure, and romance, The Book of Doors opens up a thrilling world of contemporary fantasy for fans of The Midnight Library, The Invisible Life of Addie Larue, The Night Circus, and any modern story that mixes the wonder of the unknown with just a tinge of darkness.', 432, null, 2024, 1083047, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Spellshop', 'Sarah Beth Durst', '1035042339', 'https://assets.hardcover.app/editions/31112318/6041354856479757.webp', 'Kiela has always had trouble dealing with people. Thankfully, as a librarian at the Great Library of Alyssium, she and her assistant, Caz―a magically sentient spider plant―have spent the last decade sequestered among the empire’s most precious spellbooks, preserving their magic for the city’s elite.

When a revolution begins and the library goes up in flames, she and Caz flee with all the spellbooks they can carry and head to a remote island Kiela never thought she’d see again: her childhood home. Taking refuge there, Kiela discovers, much to her dismay, a nosy―and very handsome―neighbor who can’t take a hint and keeps showing up day after day to make sure she’s fed and to help fix up her new home.

In need of income, Kiela identifies something that even the bakery in town doesn’t have: jam. With the help of an old recipe book her parents left her and a bit of illegal magic, her cottage garden is soon covered in ripe berries.

But magic can do more than make life a little sweeter, so Kiela risks the consequences of using unsanctioned spells and opens the island’s first-ever and much needed secret spellshop.

Like a Hallmark rom-com full of mythical creatures and fueled by cinnamon rolls and magic, The Spellshop will heal your heart and feed your soul.', 384, null, 2024, 1088283, (select id from series where hardcover_id = 200760), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Alchemised', 'SenLinYu', '3989780689', 'https://assets.hardcover.app/edition/31173970/920e9d065f6a8cd28ac63e6b326607da89bea878.jpeg', 'Once a promising alchemist, Helena Marino is now a prisoner—of war and of her own mind. Her Resistance friends and allies have been brutally murdered, her abilities suppressed, and the world she knew destroyed.

In the aftermath of a long war, Paladia’s new ruling class of corrupt guild families and depraved necromancers whose vile, undead creatures helped bring about their victory, holds Helena captive.

According to Resistance records, she was a healer of little importance within their ranks. But Helena has inexplicable memory loss of the months leading up to her capture, making her enemies wonder: Is she truly as insignificant as she appears, or are her lost memories hiding some vital piece of the Resistance’s final gambit?

To uncover the memories buried deep within her mind, Helena is sent to the High Reeve, one of the most powerful and ruthless necromancers in this new world. Trapped on his crumbling estate, Helena’s fight—to protect her lost history and to preserve the last remaining shreds of her former self—is just beginning. For her prison and captor have secrets of their own . . . secrets Helena must unearth, whatever the cost.', 1054, null, 2025, 1149853, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lights Out', 'Navessa Allen', '1529442419', 'https://assets.hardcover.app/edition/32499986/6b1cd8bf65d5bd0305509740ba385726ba5e6202.jpeg', 'Trauma nurse Aly Cappellucci doesn’t need any more kinks. She likes the one she’s landed on just fine. To her, nothing could top the masked men she follows online. Unless one of those men was shirtless, heavily tattooed, and waiting for her in her bedroom. 

She dreams about being hunted by one in particular, of him chasing her down and doing deliciously dark things to her willing body. She never could have guessed that by sending one drunken text, those dreams would become her new reality.

I want things most people don’t, craving darkness and depravity instead of light and love.

Josh Hammond has spent his life avoiding the limelight, but his online persona is another story. At night, he posts masked thirst traps for his millions of fans to drool over, but one follower has caught his eye: Aly. After reading a comment begging him to break into her house wearing a mask, he decides to take her up on her offer.

Together, Aly and Josh live out their darkest fantasies, unaware that Aly has captured the attention of someone else. Someone with far more sinister intentions than a little light stalking. 

As Josh turns from predator to protector and the stakes heighten, he must ask himself how far he’s willing to go for the woman he’s obsessed with.', 416, null, 2024, 1180115, (select id from series where hardcover_id = 140317), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Drop of Corruption', 'Robert Jackson Bennett', '0593949943', 'https://assets.hardcover.app/editions/31279842/4125379324485783.jpg', 'In the canton of Yarrowdale, at the very edge of the Empire’s reach, an impossible crime has occurred. A Treasury officer has disappeared into thin air—abducted from his quarters while the door and windows remained locked from the inside, in a building whose entrances and exits are all under constant guard.

To solve the case, the Empire calls on its most brilliant and mercurial investigator, the great Ana Dolabra. At her side, as always, is her bemused assistant Dinios Kol.

Before long, Ana’s discovered that they’re not investigating a disappearance, but a murder—and that the killing was just the first chess move by an adversary who seems to be able to pass through warded doors like a ghost, and who can predict every one of Ana’s moves as though they can see the future.

Worse still, the killer seems to be targeting the high-security compound known as the Shroud. Here, the Empire’s greatest minds dissect fallen Titans to harness the volatile magic found in their blood. Should it fall, the destruction would be terrible indeed—and the Empire itself will grind to a halt, robbed of the magic that allows its wheels of power to turn. 

Din has seen Ana solve impossible cases before. But this time, with the stakes higher than ever and Ana seemingly a step behind their adversary at every turn, he fears that his superior has finally met an enemy she can’t defeat.

', 432, null, 2025, 1254783, (select id from series where hardcover_id = 46710), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Desolation Called Peace', 'Arkady Martine', '1250186471', 'https://assets.hardcover.app/external_data/49448457/409f1b4894ba7245196820c9dd898f39af25ce50.jpeg', 'An alien armada lurks on the edges of Teixcalaanli space. No one can communicate with it, no one can destroy it, and Fleet Captain Nine Hibiscus is running out of options.

In a desperate attempt at diplomacy with the mysterious invaders, the fleet captain has sent for a diplomatic envoy. Now Mahit Dzmare and Three Seagrass—still reeling from the recent upheaval in the Empire—face the impossible task of trying to communicate with a hostile entity.

Their failure will guarantee millions of deaths in an endless war. Their success might prevent Teixcalaan’s destruction—and allow the empire to continue its rapacious expansion.

Or it might create something far stranger . . .', 496, null, 2021, 1377550, (select id from series where hardcover_id = 5468), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Bury Our Bones in the Midnight Soil', 'V. E. Schwab', '1250398541', 'https://assets.hardcover.app/editions/31622506/fe0049fa-5e98-4984-aaf9-9c95dd327b69.jpg', '1532. Santo Domingo de la Calzada.
A young girl grows up wild and wily―her beauty is only outmatched by her dreams of escape. But María knows she can only ever be a prize, or a pawn, in the games played by men. When an alluring stranger offers an alternate path, María makes a desperate choice. She vows to have no regrets.

1827. London.
A young woman lives an idyllic but cloistered life on her family’s estate, until a moment of forbidden intimacy sees her shipped off to London. Charlotte’s tender heart and seemingly impossible wishes are swept away by an invitation from a beautiful widow―but the price of freedom is higher than she could have imagined.

2019. Boston.
College was supposed to be her chance to be someone new. That’s why Alice moved halfway across the world, leaving her old life behind. But after an out-of-character one-night stand leaves her questioning her past, her present, and her future, Alice throws herself into the hunt for answers . . . and revenge.

This is a story about life―how it ends, and how it starts.', 544, null, 2025, 1396631, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Not Till We Are Lost', 'Dennis E. Taylor', '1680683454', 'https://assets.hardcover.app/editions/31469389/7597277688037378.jpg', 'The Bobiverse is a different place in the aftermath of the Starfleet War, and the days of the Bobs gathering in one big happy moot are far behind. There’s anti-Bob sentiment on multiple planets, the Skippies playing with an A.I. time bomb, and multiple Bobs just wanting to get away from it all.

But it all pales compared to what Icarus and Daedalus discover on their 26,000-year journey to the center of the galaxy. Sure, it could settle the Fermi Paradox for good (and what Bob doesn’t want to solve a mystery of the universe?). But it also reveals a threat to the galaxy greater than anything the Bobs could have imagined.

Just another average day in the Bobiverse.', 340, null, 2024, 1432670, (select id from series where hardcover_id = 1107), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Buffalo Hunter Hunter', 'Stephen Graham Jones', '1668098016', 'https://assets.hardcover.app/edition/31475163/f8aacab35496a1607f8130c42a91eec7f82793a6.jpeg', 'A chilling historical horror novel set in the American west in 1912 following a Lutheran priest who transcribes the life of a vampire who haunts the fields of the Blackfeet reservation looking for justice.

A diary, written in 1912 by a Lutheran pastor is discovered within a wall. What it unveils is a slow massacre, a chain of events that go back to 217 Blackfeet dead in the snow. Told in transcribed interviews by a Blackfeet named Good Stab, who shares the narrative of his peculiar life over a series of confessional visits. This is an American Indian revenge story written by one of the new masters of horror, Stephen Graham Jones.', 444, null, 2025, 1437438, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Zodiac Academy: The Awakening', 'Caroline Peckham, Susanne Valenti', '9781916926257', 'https://assets.hardcover.app/editions/30390690/2249982766164498.jpeg', 'I’m a Gemini. Impulsive. Curious. Headstrong. A twin. Heir to a throne I know nothing about. And it turns out, I’m Fae.

But of course there’s a catch - all I have to do to claim my birth right is prove that I’m the most powerful supernatural in the whole of Solaria. And sure, technically that’s true as I’m the daughter of the Savage King. But the bit they didn’t put in the brochure was that every single Fae in this Kingdom would claim my throne if they could.

The school they’ve sent me to is both dangerous as sh*t and one helluva party. Vampires bite weaker students in the corridors, the Werewolf pack has orgies in the Wailing Wood at every full moon and don’t even get me started on the dark and twisted ways the Sirens use their powers on people’s emotions, or how my sinfully tempting Cardinal Magic teacher hosts detentions that leave people needing therapy.

Classes are totally interesting if you manage to live through them. And that Gemini star sign I mentioned? It now determines my elemental magic and affects my destiny, so learning astrology is essential if I’m going to beat down my classmates – which is actively encouraged by the way.

My biggest problem is the drool worthy Dragon shifter who has his eyes on my throne. He and his three psycho friends are determined to make my time here hell.

All I’ve got to do is survive. But fate might have other ideas.

Dammit, why couldn’t I have gotten a letter to Hogwarts?', 436, null, 2019, 1459781, (select id from series where hardcover_id = 7134), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Underground Railroad', 'Colson Whitehead', '0385542364', 'https://assets.hardcover.app/edition/29620225/f008ccbc2d8fe0ea58cd84bbbcf294a46f869876.jpeg', 'Cora is a slave on a cotton plantation in Georgia. Life is hell for all the slaves, but especially bad for Cora; an outcast even among her fellow Africans, she is coming into womanhood—where even greater pain awaits. When Caesar, a recent arrival from Virginia, tells her about the Underground Railroad, they decide to take a terrifying risk and escape. Matters do not go as planned—Cora kills a young white boy who tries to capture her. Though they manage to find a station and head north, they are being hunted.

In Whitehead’s ingenious conception, the Underground Railroad is no mere metaphor—engineers and conductors operate a secret network of tracks and tunnels beneath the Southern soil. Cora and Caesar’s first stop is South Carolina, in a city that initially seems like a haven. But the city’s placid surface masks an insidious scheme designed for its black denizens. And even worse: Ridgeway, the relentless slave catcher, is close on their heels. Forced to flee again, Cora embarks on a harrowing flight, state by state, seeking true freedom.

Like the protagonist of Gulliver’s Travels, Cora encounters different worlds at each stage of her journey—hers is an odyssey through time as well as space. As Whitehead brilliantly re-creates the unique terrors for black people in the pre–Civil War era, his narrative seamlessly weaves the saga of America from the brutal importation of Africans to the unfulfilled promises of the present day. The Underground Railroad is at once a kinetic adventure tale of one woman’s ferocious will to escape the horrors of bondage and a shattering, powerful meditation on the history we all share.', 306, null, 2016, 1487609, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Secret of Secrets', 'Dan Brown, Fernanda Abreu', '8817174459', 'https://assets.hardcover.app/edition/31830477/31aa397f1175d024ab3bbb8e3abf57d951d76676.jpeg', 'Robert Langdon, esteemed professor of symbology, travels to Prague to attend a groundbreaking lecture by Katherine Solomon—a prominent noetic scientist with whom he has recently begun a relationship. Katherine is on the verge of publishing an explosive book that contains startling discoveries about the nature of human consciousness and threatens to disrupt centuries of established belief. 

But a brutal murder catapults the trip into chaos, and Katherine suddenly disappears along with her manuscript. Langdon finds himself targeted by a powerful organization and hunted by a chilling assailant sprung from Prague’s most ancient mythology. 

As the plot expands into London and New York, Langdon desperately searches for Katherine... and for answers. In a thrilling race through the dual worlds of futuristic science and mystical lore, he uncovers a shocking truth about a secret project that will forever change the way we think about the human mind.', 688, null, 2025, 1729702, (select id from series where hardcover_id = 1084), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Everlasting', 'Alix E. Harrow', '1529061172', 'https://assets.hardcover.app/edition/31877191/526ae194-1ed1-4f0e-85bd-f5db671b4454.webp', 'Sir Una Everlasting was Dominion’s greatest hero: the orphaned girl who became a knight, who died for queen and country. Her legend lives on in songs and stories, in children’s books and recruiting posters―but her life as it truly happened has been forgotten.

Centuries later, Owen Mallory―failed soldier, struggling scholar―falls in love with the tale of Una Everlasting. Her story takes him to war, to the archives―and then into the past itself. Una and Owen are tangled together in time, bound to retell the same story over and over again, no matter what it costs.

But that story always ends the same way. If they want to rewrite Una’s legend―if they want to tell a different story--they’ll have to rewrite history itself.', 400, null, 2025, 1768096, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Yesteryear', 'Caro Claire Burke', '0008742766', 'https://assets.hardcover.app/edition/32720645/91d910bf-e696-4366-aa09-14f0a6a6cea9.jpg', 'Natalie lives a traditional lifestyle. Her charming farmhouse is rustic, her husband a handsome cowboy, her six children each more delightful than the last. So what if there are nannies and producers behind the scenes, her kitchen hiding industrial-grade fridges and ovens, her husband the heir to a political dynasty? What Natalie’s followers—all 8 million of them—don’t know won’t hurt them. And The Angry Women? The privileged, Ivy League, coastal elite haters who call her an antifeminist iconoclast? They’re sick with jealousy. Because Natalie isn’t simply living the good life, she’s living the ideal—and just so happens to be building an empire from it.

Until one morning she wakes up in a life that isn’t hers. Her home, her husband, her children—they’re all familiar, but something’s off. Her kitchen is warmed by a sputtering fire rather than electricity, her children are dirty and strange, and her soft-handed husband is suddenly a competent farmer. Just yesterday Natalie was curating photos of homemade jam for her Instagram, and now she’s expected to haul firewood and handwash clothes until her fingers bleed. Has she become the unwitting star of a ruthless reality show? Could it really be time travel? Is she being tested by God? By Satan? When Natalie suffers a brutal injury in the woods, she realizes two things: This is not her beautiful life, and she must escape by any means possible.

A gripping, electrifying novel that is as darkly funny as it is frightening, Yesteryear is a gimlet-eyed look at tradition, fame, faith, and the grand performance of womanhood.', 391, null, 2026, 1941363, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Platform Decay', 'Martha Wells', '1250460786', 'https://assets.hardcover.app/edition/32156003/e38e4f2d-41b3-44e2-a847-513056d1c43e.jpg', 'After volunteering to run a rescue mission, Murderbot realizes that it will have to spend significant time with a bunch of humans it doesn''t know.

Including human children. Ugh.

This may well call for... eye contact!

(Emotion check: Oh, for f—)', 244, null, 2026, 1989398, (select id from series where hardcover_id = 1053), '8') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mists of Avalon', 'Marion Zimmer Bradley', '2857042019', 'https://assets.hardcover.app/book_mappings/7333108/4c58366d65b20e2e17573e941dfcb14ddf65424f.jpeg', 'The magical saga of the women behind King Arthur''s throne. “A monumental reimagining of the Arthurian legends . . . reading it is a deeply moving and at times uncanny experience. . . . An impressive achievement.”—The New York Times Book Review In Marion Zimmer Bradley''s masterpiece, we see the tumult and adventures of Camelot''s court through the eyes of the women who bolstered the king''s rise and schemed for his fall. From their childhoods through the ultimate fulfillment of their destinies, we follow these women and the diverse cast of characters that surrounds them as the great Arthurian epic unfolds stunningly before us. As Morgaine and Gwenhwyfar struggle for control over the fate of Arthur''s kingdom, as the Knights of the Round Table take on their infamous quest, as Merlin and Viviane wield their magics for the future of Old Britain, the Isle of Avalon slips further into the impenetrable mists of memory, until the fissure between old and new worlds'' and old and new religions'' claims its most famous victim.', 904, null, 1979, 2023539, (select id from series where hardcover_id = 10210), '7') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Bridge to Terabithia', 'Katherine Paterson, Donna Diamond', '0064401847', 'https://assets.hardcover.app/edition/30402215/fc7b41ec-293b-4d8a-ac29-b29d7ac60394.jpg', 'The life of a ten-year-old boy in rural Virginia expands when he becomes friends with a newcomer who subsequently meets an untimely death trying to reach their hideaway, Terabithia, during a storm.', 128, null, 1977, 2280862, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('La Belle Sauvage: The Book of Dust Volume One', 'Philip Pullman', '1547904216', 'https://assets.hardcover.app/editions/31972914/880a3e79-78a1-431a-8232-d9120c051647.jpg', 'This book is set ten years before The Golden Compass and tells the story of how Lyra came to be living at Jordan College.', 570, null, 2017, 2349390, (select id from series where hardcover_id = 991), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Wizard’s Guide to Defensive Baking', 'T. Kingfisher', '8056658408', 'https://assets.hardcover.app/external_data/61250249/4b1fbf8a26b027409046f84de4a076153192a722.jpeg', 'Fourteen year old Mona is a baker but she is also a not-very-powerful wizard - her medium of choice is dough. She can make pastries dance and bread light and fluffy - nothing extreme or dangerous. But when someone starts killing off all the wizards her minor wizard status doesn''t matter and she has to run or be killed. But the people killing off the wizards have to be stopped and Mona doesn''t let her lowly abilities stop her - a wizard''s got to do what a wizard''s got to do. 

Such a clever, funny, amazing story.', 298, null, 2020, 2411449, null, null) on conflict (hardcover_id) do nothing;
